SELECT 'moj-all-verified-judgments-review-002-chunk-111' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"184a92d5-c4b9-5da6-ad37-8be281d41fa8","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء -سكب أحد السجناء الزيت الساخن على سجني آخر مما تسبب يف إصابته بحروق -إقرار -وجود سوابق -التعزير بالسجن االنفرادي ملدة ستني يوم ا واجللد .","document_number":"34189860","case_number":"3493295","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة قلوة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/16","year":"1434","subject":"إيذاء -سكب أحد السجناء الزيت الساخن على سجني آخر مما تسبب يف إصابته بحروق -إقرار -وجود سوابق -التعزير بالسجن االنفرادي ملدة ستني يوم ا واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34189860 :‬تاريخه‪1434/4/16 :‬هـ‬\n                     ‫رقم الدعوى‪3493295:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34189860‬تاريخه‪1434/4/16 :‬هـ‬\n\n\n\n‫إيــذاء‪ -‬ســكب أحــد الســجناء الزيــت الســاخن علــى ســجني آخــر ممــا‬\n‫تســبب يف إصابتــه بحــروق ‪ -‬إقــرار ‪ -‬وجــود ســوابق ‪ -‬التعزيــر بالســجن‬\n                                  ‫االنفــرادي ملــدة ســتني يوم ـ ًا واجللــد ‪.‬‬\n\n\n\n\n‫‪-‬عــن أبــي بكــرة رضــي اهلل عنــه أن النبــي صلــى اهلل عليــه وســلم قــال ‪:‬‬\n‫(إن دمائكــم وأموالكــم وأعراضكــم عليكــم حــرام كحرمــة يومكــم هــذا‬\n             ‫يف شــهركم هــذا يف بلدكــم هــذا ) رواه البخــاري ومســلم‬\n\n\n\n‫توجيــه االتهــام للمدعــى عليــه بالقيــام بســكب زيــت ســاخن علــى أحــد‬\n‫الســجناء ممــا تســبب لــه يف اإلصابــة املوصوفــة بالتقريــر الطبــي‪ ،‬وذلــك‬\n‫بعــد وروود خطــاب مــن الســجن املتضمــن بــاغ ســجني لديهــم مفــاده‬\n‫قيــام الســجني املدعــى عليــه بســكب زيــت طعــام علــى يــده والتســبب يف‬\n‫إصابتــه وذلــك بحضــور عــدد مــن الســجناء ‪ ،‬طلــب املدعــي العــام إثبــات‬\n‫إدانتــه مبــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة رادعــة والتشــديد‬\n‫عليــه لقــاء تعــدد ســوابقه وإثــارة الفوضــى داخــل الســجن ‪ ،‬بعــرض‬\n‫دعــوى املدعــي العــام علــى املدعــى عليــه صــادق عليهــا جملــة وتفصيــا‬\n‫ونظــر ًا ألن املدعــى عليــه أقــر مبــا جــاء يف دعــوى املدعــي العــام وألن مــا‬\n\n                                                                                       ‫‪52‬‬\n\f     ‫أقــدم عليــه املدعــى عليــه فيــه مــن اجلــرأة علــى أذيــة النــاس يف أبدانهــم‬\n     ‫مــا يــدل علــى اســتهتاره بأرواحهــم ممــا يقتضــي عقوبتــه مبــا يردعــه‪،‬‬\n     ‫ونظــر ًا لكثــرة ســوابق املدعــى عليــه وعــدم ارتداعــه رغــم احلكــم‬\n     ‫عليــه أكثــر مــن مــرة وألن املدعــى عليــه قــد ســبق وأن أثــار فوضــى‬\n     ‫يف الســجن بســبب مشــاكله مــع الســجناء ومــن أجــل ذلــك جــرى نقلــه‬\n     ‫إلــى ســجن ‪ ........‬جلميــع مــا تقــدم فقــد مت احلكــم بتعزيــر املدعــى عليــه‬\n     ‫لقــاء ذلــك بالســجن يف الســجن االنفــرادي ملــدة ســتني يومـ ًا وجلــده تســعا‬\n     ‫وســبعني جلــدة دفعــة واحــدة وبعــرض ذلــك علــى املدعــي العــام قــرر عــدم‬\n     ‫قناعتــه باحلكــم معتبــر ًا الئحــة الدعــوى الئحتــه االعتراضيــة وبعرضــه‬\n     ‫علــى املدعــى عليــه قــرر قناعتــه باحلكــم‪ ،‬وبعــد رفــع احلكــم حملكمــة‬\n                                                   ‫االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنا‪......‬القاضــي يف احملكمــة العامــة‬\n     ‫مبحافظــة قلــوة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمة العامة مبحافظة قلوة برقم ‪ 3493295‬وتاريخ ‪1434/02/25‬‬\n     ‫هـ املقيدة باحملكمة برقم ‪ 34478656‬وتاريخ ‪ 1434/02/25‬هـ ففي‬\n     ‫يوم الثالثاء املوافق‪ 1434/04/16‬هـ افتتحت اجللســة الســاعة ‪09 : 30‬‬\n     ‫وفيهــا حضــر املدعــي العــام بهيئــة التحقيــق واالدعــاء العــام مبحافظــة‬\n     ‫قلوة‪......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪......‬مدعيــا علــى‬\n     ‫احلاضــر معــه ‪......‬ســعودي بالســجل املدنــي رقــم ‪......‬قائــا املدعــي العــام‬\n     ‫يف دعــواه أنــه بتاريــخ ‪1434/2/2‬ه ـ ورد لشــرطة محافظــة قلوة خطاب‬\n     ‫مــن ســجن قلــوة املتضمــن بــاغ الســجني لديهم‪......‬مفــاده قيــام الســجني‬\n\n‫‪53‬‬\n\f‫املدعــى عليــه أعــاه بســكب زيــت طعــام علــى يــده والتســبب يف إصابتــه‬\n‫وذلــك بحضــور عــدد مــن الســجناء‪ .‬وبســماع شــهادة الســجني‪...... /‬أفــاد‬\n‫بأنــه أثنــاء جلوســه يف العزبــة داخــل الســجن برفقــة ‪......‬حضــر املدعــى‬\n‫عليــه أعــاه وبيــده مقــاة بهــا زيــت مغلــي فقــام بســكبها علــى ‪......‬ممــا‬\n‫تســبب لــه بحــروق‪ .‬وبســماع شــهادة الســجني ‪......‬أفــاد مبثــل مــا أفــاد بــه‬\n‫الســجني‪ ......‬وقــد أثبــت التقريــر اإلصابــي النهائــي رقــم (‪ )......‬وتاريــخ‬\n‫‪1434/2/6‬ه ـ الصــادر مــن مستشــفى قلــوة العــام املتضمــن إصابــة‬\n‫الســجني (‪ )......‬بحريــق مــن الدرجــة األولــى بنســبة ‪ %12‬بأجــزاء متفرقــة‬\n‫مــن اجلســم وحــددت مــدة الشــفاء بعشــرة أيام فقــط‪ .‬وباســتجواب املدعى‬\n‫عليــه ومواجهتــه مبــا نســب إليــه أقــر بقيامــه بســكب زيــت مغلــي علــى‬\n‫املدعــو‪...... /‬وأنــه هــو املتســبب الوحيــد يف تلــك اإلصابــات ولم يشــاركه‬\n‫أحــد يف ذلــك وقــد انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه‬\n‫بالقيــام بســكب زيــت ســاخن علــى املواطــن‪...... /‬ممــا تســبب لــه يف‬\n‫اإلصابــة املوصوفــة بالتقريــر الطبــي املشــار إليــه وذلــك لألدلــة والقرائــن‬\n                                                                           ‫التاليــة ‪-:‬‬\n      ‫‪-1‬اعترافه املدون ص (‪ )14‬من دفتر التحقيق املرفق لفه رقم (‪.)1‬‬\n                ‫‪-2‬التقرير اإلصابي النهائي املنوه عنه املرفق لفة رقم (‪.)13‬‬\n‫‪-3‬مــا جــاء بشــهادة الشــهود املنــوه عنهــا املدونــة ص رقــم (‪ )16‬مــن دفتــر‬\n‫التحقيــق لفــه رقــم (‪ .)1‬وبالبحــث عــن ســوابقه عثــر لــه علــى ســت ســوابق‬\n‫جنائيــة مســجلة عليــه األولــى ســرقة محــات جتاريــة والثانيــة ســرقة‬\n‫أمــوال والثالثــة والرابعــة شــرب املســكرات وســرقة ســيارات واخلامســة‬\n                                       ‫والسادســة اســتعمال املخــدرات وســرقة ‪.‬‬\n‫وحيــث أن مــا قــام بــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n\n\n                                                                                          ‫‪54‬‬\n\f     ‫فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا اطلــب إثبــات إدانتــه مبــا اســند‬\n     ‫إليــه واحلكــم عليــه بعقوبــة تعزيريــة رادعــه والتشــديد عليــه لقــاء تعــدد‬\n     ‫ســوابقه وإثــارة الفوضــى داخــل الســجن ‪( .‬علم ـ ًا بــأن احلــق اخلــاص ال‬\n     ‫زال قائم ـ ًا ) ويف هــذه اجللســة حضــر املدعــى عليــه وبعــرض دعــوى‬\n     ‫املدعــي العــام عليــه أجــاب قائ ـاً‪ :‬مــا ذكــره املدعــي العــام يف دعــواه‬\n     ‫ا وكان ذلــك بســبب انــه يتكلــم علــي‬         ‫كلــه صحيــح جملــة وتفصي ـ ً‬\n     ‫ويســبني ويســب أهلــي فاشــتكيته علــى مديــر الســجن وقلــت لــه تــرى‬\n     ‫اللــي يؤذينــي راح أحرقــه واســتمر املذكــور يف أذيتــي فســكبت عليــه‬\n     ‫الزيــت كمــا جــاء يف دعــوى املدعــي العــام هكــذا أجــاب فبنــاء علــى‬\n     ‫مــا تقــدم مــن الدعــوى واإلجابــة وحيــث اعتــرف املدعــى عليــه مبــا جــاء‬\n     ‫يف دعــوى املدعــي العــام مــن ســكبه للزيــت الســاخن علــى الســجني‬\n     ‫املذكــور وأحــدث بــه اإلصابــة املذكــورة وحيــث أن مــا أقــدم عليــه‬\n     ‫املدعــى عليــه فيــه مــن اجلــرأة علــى أذيــة النــاس يف أبدانهــم مــا يــدل علــى‬\n     ‫اســتهتاره بأرواحهــم ممــا يقتضــي عقوبتــه مبــا يردعــه وقــد روى البخاري‬\n     ‫ومســلم عــن أبــي بكــرة رضــي اهلل عنــه أن النبــي صلــى اهلل عليــه وســلم‬\n     ‫قــال (إن دمائكــم وأموالكــم وأعراضكــم عليكــم حــرام كحرمــة‬\n     ‫يومكــم هــذا يف شــهركم هــذا يف بلدكــم هــذا ) ونظــر ًا لكثــرة‬\n     ‫ســوابق املدعــى عليــه وعــدم ارتداعــه رغــم احلكــم عليــه أكثــر مــن مــرة‬\n     ‫وحيــث أن املدعــى عليــه قــد ســبق وأن أثــار فوضــى يف ســجن قلــوة بســبب‬\n     ‫مشــاكله مــع الســجناء ومــن أجــل ذلــك جــرى نقلــه إلــى ســجن املخــواة‬\n     ‫جلميــع مــا تقــدم فقــد قــررت تعزيــر املدعــى عليــه لقــاء ذلــك بالســجن‬\n     ‫يف الســجن االنفــرادي ملــدة ســتني يوم ـ ًا وجلــده تســعا وســبعني جلــدة‬\n     ‫دفعــة واحــدة وبــه حكمــت وبعــرض ذلــك علــى املدعــي العــام قــرر عــدم‬\n\n\n‫‪55‬‬\n\f‫قناعتــه باحلكــم معتبــر ًا الئحــة الدعــوى الئحتــه االعتراضيــة وبعرضــه‬\n‫علــى املدعــى عليــه قــرر قناعتــه باحلكــم وســيتم رفــع كامــل أوراق‬\n‫املعاملــة حملكمــة اإلســتئناف كاملتبــع وأغلقــت اجللســة ‪10 : 00‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫حــرر يف ‪ 1434/04/16‬ه ـ احلمــد هلل وحــده والصــاة والســام علــى‬\n‫مــن ال نبــي بعــده وبعــد ‪ :‬فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫الثالثــة مبحكمــة االســتئناف يف منطقــة مكــة املكرمــة االطــاع علــى‬\n‫املعاملــة الــواردة مــن فضيلــة القاضــي باحملكمــة العامــة مبحافظــة‬\n‫قلــوة الشــيخ‪....../‬برقم ‪ 34478656‬وتاريــخ ‪1434/5/15‬ه ـ املرفــق بهــا‬\n‫الصــك الصــادر مــن فضيلتــه برقــم ‪ 34189860‬وتاريــخ ‪1434/4/16‬ه ـ‬\n‫املتضمــن دعــوى املدعــي العــام ضــد‪ ،....../‬املتهــم بالقيــام بســكب زيــت‬\n‫ســاخن علــى شــخص ممــا تســبب يف اصابتــه احملكــوم فيــه مبــا دون‬\n‫باطــن الصــك ‪.‬وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــى‬\n‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                        ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪56‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":52,"source_page_end":56,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"93c0e5375a620ec9f72ff036207c25274f251f741d641eb1a87b978ae7a8461f","normalized_text_hash":"d2680cd8d44d4ab961dd47001ad1ed961cbd918fef228376424ec478e8f31312","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p52-34189860"},{"id":"fd27e600-c293-5383-b5ca-68fed751b431","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -ضرب الزوج لزوجته -التعريض بالقذف -سب الزوج زوجته -توجه التهمة بالقرائن -تعزير الزوج بالسجن لضربه زوجته وسبها والتعريض بقذفها.","document_number":"34229637","case_number":"32464220","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بخميس مشيط وصدق ذلك احلكم من محكمة الاستئناف مبنطقة عسير هكذا قالت","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/4","year":"1434","subject":"اعتداء -ضرب -ضرب الزوج لزوجته -التعريض بالقذف -سب الزوج زوجته -توجه التهمة بالقرائن -تعزير الزوج بالسجن لضربه زوجته وسبها والتعريض بقذفها.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 34229637 :‬تاريخه‪1434/6/4 :‬هـ‬\n                        ‫رقم الدعوى‪32464220:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34364666‬تاريخه‪1434/11/20 :‬هـ‬\n\n\n\n     ‫اعتــداء ‪ -‬ضــرب ‪ -‬ضــرب الــزوج لزوجتــه ‪ -‬التعريــض بالقــذف ‪ -‬ســب‬\n     ‫الــزوج زوجتــه ‪ -‬توجــه التهمــة بالقرائــن ‪ -‬تعزيــر الــزوج بالســجن‬\n                              ‫لضربــه زوجتــه وســبها والتعريــض بقذفهــا‪.‬‬\n\n\n\n\n                              ‫‪-1‬قول اهلل تعالى ‪( :‬وال تنسوا الفضل بينكم)‬\n     ‫‪-2‬قيــام الشــبهة علــى االعتــداء بالضــرب والتعريــض بالقــذف موجــب‬\n                                                                    ‫للتعزيــر‪.‬‬\n     ‫‪-3‬النكــول عــن اليمــن يف الدعــوى اجلنائيــة اخلاصــة بطلــب التعزيــر‬\n     ‫قرينــة تــورث التهمــة بالنــاكل يجــوز معهــا تعزيــره خصوصــا إذا قامــت‬\n                                                     ‫قرائــن أخــرى تعضدهــا‪.‬‬\n\n\n\n\n     ‫ادعــت املدعيــة بــأن زوجهــا املدعــى عليــه رزقــت منــه بأربعــة أوالد وهــو‬\n     ‫يكثــر مــن ضربهــا وســبها وشــتمها وأنــه عــرض بقذفهــا بقولــه أن إحدى‬\n     ‫بناتــه ال تشــبهه وأنهــا مقيمــة لــدى أهلهــا وال ترغــب بالعــودة إليــه وتطلــب‬\n     ‫إيقــاع العقوبــة التعزيريــة عليــه‪ ،‬أقــر املدعــى عليــه بــأن املدعيــة ‪ -‬زوجتــه‬\n     ‫‪ -‬ال زالــت يف عصمتــه وأنهــا مقيمــة لــدى أهلهــا منــذ فتــرة إال أنــه لــم‬\n     ‫يضربهــا ولــم يعــرض بقذفهــا وأن ســبب غضبهــا قيامــه بالــزواج مــن‬\n\n‫‪57‬‬\n\f‫امــرأة أخــرى وأن دعواهــا كيديــة ويرغــب يف عودتهــا لــه‪ ،‬بعرضــه علــى‬\n‫املدعيــة قــررت بــأن غضبهــا العتدائــه عليهــا ضربــا وقذفــا وليــس ألجــل‬\n‫زواجــه‪ ،‬قــررت بــأن بينتهــا األشــعة الســينية املتضمنــة وجــود شــرخني‬\n‫صغيريــن بعظمــة األنــف اليمنــى واليســرى وقــررت بأنــه املتســبب فيهمــا‬\n‫وال بينــة لديهــا ســوى ذلــك وتطلــب ميينــه وباالطالع على األشــعة وعرضها‬\n‫علــى املدعــى عليــه أنكــر تســببه بهــذا الفعــل‪ ،‬ثــم جــرى محاولــة‬\n‫الصلــح بينهمــا فلــم يصطلحــا ثــم حضــرت املدعيــة وقــررت بأنــه صــدر‬\n‫لهــا حكــم مصــدق مــن االســتئناف بفســخ نكاحهــا مــن املدعــى عليــه‬\n‫وتطلــب مواصلــة النظــر يف القضيــة‪ ،‬قــرر املدعــى عليــه طلــب إيقــاف‬\n‫النظــر يف القضيــة حلــن الفصــل يف قضيــة احلضانــة والنفقــة املقامــة مــن‬\n‫املدعيــة إال أن احملكمــة لعــدم وجاهتــه لــم تلتفــت لطلبــه‪ ،‬جــرى محاولة‬\n‫الصلــح بينهمــا مــرة أخــرى وبــاءت بالفشــل ‪ .‬قــرر املدعــى عليــه بأنــه لــن‬\n‫يحلــف اليمــن علــى نفــي دعــوى املدعيــة إال إن أثبتــت دعواهــا ضــده‬\n‫ـاء علــى جميــع مــا ســبق فقــد قــررت احملكمــة مؤاخــذة املدعــى‬      ‫‪ ،‬وبنـ ً‬\n‫عليــه ‪ ،‬بيــد أنــه مــع قيــام موجــب التشــديد يف العقوبــة فهنــاك مــا يوجــب‬\n‫أيضــا تخفيفهــا كضعــف القرائــن‪ ،‬وجــود قرابــة بــن الزوجــن وأوالد‬\n‫بينهمــا وقــد قــال اهلل تعالــى‪« :‬وال تنســوا الفضــل بينكــم» ولهــذا رأت‬\n‫احملكمــة التوســط يف العقوبــة فقــررت توجيــه التهمــة للمدعــى عليــه‬\n‫باعتدائــه بالضــرب علــى املدعيــة وســبها وشــتمها والتعريــض بقذفهــا‬\n‫بســجنه خمســة عشــر يومــا ورد دعــوى املدعــى عليــه إيقــاف النظــر يف‬\n‫الدعــوى وبــه حكمــت‪ ،‬وبعــرض احلكــم علــى الطرفــن قــررا عــدم‬\n‫القناعــة بــه وطلبــا رفعــه إلــى محكمــة االســتئناف بالئحــة اعتراضيــة‪،‬‬\n                                   ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n                                                                                     ‫‪58‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة اجلزئيــة‬\n     ‫بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة اجلزئيــة بخميــس مشــيط برقــم وتاريــخ ‪ 1432/10/20‬ه ـ‬\n     ‫املقيــدة باحملكمــة برقــم وتاريــخ ‪ 1432/10/20‬ه ـ ففــي يــوم االحــد‬\n     ‫املوافق‪ 1432/10/20‬هـ افتتحت اجللســة الســاعة ‪9 : 30‬وفيها حضرت‬\n     ‫املدعيــة ‪ ،..........‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪،..........‬‬\n     ‫وهــي برفقــة والدهــا حامــل الســجل املدنــي رقــم ‪ ،..........‬وادعــت علــى‬\n     ‫احلاضــر معهــا يف مجلــس القضــاء ‪ ،..........‬ســعودي اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم ‪ ،..........‬قائلــه يف دعواهــا إن هــذا احلاضــر هــو‬\n     ‫زوجــي وقــد أجنبــت منــه أربعــة أوالد ثــاث بنــات وابــن وخــال فتــرة‬\n     ‫حياتــي الزوجيــة معــه لــم أهنــأ معــه بعيشــة طيبــة ‪ ،‬حيــث أنــه يتكــرر‬\n     ‫منــه االعتــداء علــي بالضــرب والســب والشــتم ‪ ،‬بــل بلــغ بــه األمــر أنــه‬\n     ‫قذفنــي يف عرضــي بقولــه إن هــذه البنــت ويقصــد إحــدى بناتــه منــي‬\n     ‫ال تشــبهني‪ ،‬وهــو بذلــك يعــرض بقــذيف ‪ ،‬وإنــي أطلــب احلكــم عليــه‬\n     ‫بعقوبــة رادعــة‪ ،‬علمــا أننــي اآلن غاضبــة منــه وجالســة يف منــزل والــدي‬\n     ‫ولــم يعــد لــي أي رغبــة يف العــودة إليــه ‪ ،‬وأوالدي يســكنون معــي هكــذا‬\n     ‫ادعــت‪ ،‬وبســؤال املدعــى عليــه قــال صحيــح أن املدعيــة زوجتــي وال زالــت‬\n     ‫يف عصمتــي ولــي منهــا أربعــة أوالد ‪ ،‬وهــي اآلن عنــد أهلهــا مــع أوالدهــا‬\n     ‫غاضبــة منــي منــذ ســتة أشــهر بســبب أننــي تزوجــت عليهــا بطلــب منهــا‪،‬‬\n     ‫ثــم ملــا تزوجــت غضبــت منــي وذهبــت إلــى بيــت أهلهــا‪ ،‬ولــم أعتــدِ عليهــا‪،‬‬\n     ‫ولــم أتعــرض لهــا بالقــذف ‪ ،‬ودعواهــا مجــرد دعــوى كيديــة‪ ،‬وأنــا لــي‬\n\n‫‪59‬‬\n\f‫رغبــة أكيــدة يف عودتهــا إلــى بيــت الطاعــة هكــذا أجــاب ‪ ،‬وبعــرض‬\n‫ذلــك علــى املدعيــة قالــت إننــي لــم أغضــب مــن زواجــه ‪ ،‬وأنــا راضيــة‬\n‫اآلن بزواجــه مــن الثانيــة ‪،‬وإمنــا أنــا غاضبــة منــه بســبب اعتــداءه وســبه‬\n‫وتعريضــه لــي بالقــذف ‪ ،‬والــذي يــدل علــى صحــة دعــواي هــي األشــعة‬\n‫الســينية علــى األنــف الــذي ضربنــي عليــه ‪ ،‬حيــث أثبتــت تلــك األشــعة‬\n‫الصــادرة مــن مجمــع ‪..........‬الطبــي بخميــس مشــيط أنــه يوجــد شــرخان‬\n‫صغيــران بعظمتــي األنــف اليمنــى واليســرى وهــذا يؤكــد صحــة مــا‬\n‫ذكرتــه ‪ ،‬وأمــا اعتداءاتــه الســابقة لــي بالضــرب والتعريــض بالقــذف‬\n‫فليــس بينــي وبينــه يف ذلــك إال اهلل تعالــى ‪ ،‬وإذا لــم يعتــرف بذلــك فإنــي‬\n‫أطلــب ميينــه علــى نفــي صحــة ذلــك االعتــداء الســابق والتعريــض بالقــذف‬\n‫‪ ،‬وأمــا االعتــداء الــذي أوضحتــه األشــعة فإنــه لــو طلبــت ميينــي علــى ذلــك‬\n‫حللفــت ‪ ،‬وكذلــك لــو طلبــت ميينــي علــى االعتــداء الســابق والتعريــض‬\n‫بالقــذف فإنــي أحلــف وأنــا صادقــة ‪ ،‬هكــذا أجابــت وأبــرزت األشــعة‬\n‫التــي ذكرتهــا ومعهــا تقريــر األشــعة بتوقيــع وختــم طبيــب األشــعة‬\n‫مبجمع‪..........‬الطبــي ‪ ،..........‬وقــد تضمــن التقريــر مــا ذكرتــه املدعيــة‬\n‫ووجــدت أصلــة مرفــق علــى اللفتــن ‪ 10,9‬مــن أوراق املعاملــة ‪ ،‬وبعرضــه‬\n‫علــى املدعــى عليــه قــال ال أعلــم عــن هــذا التقريــر ‪ ،‬وقد قامــت بإخراجه‬\n‫وهــي عنــد أهلهــا ‪ ،‬وأمــا أنــا فلــم أضربهــا ‪ ،‬وليســت تلــك اإلصابة بســبب‬\n‫منــي ‪ ،‬ولــو طلبــت ميينــي علــى نفــي صحــة دعواهــا فإنــي ال أحلــف اليمــن‬\n‫إال إذا أثبتــت دعواهــا ضــدي هكــذا أجــاب ‪ ،‬وعنــد وصــول القضيــة‬\n‫إلــى هــذا احلــد مت نصــح الطرفــن ووعظهمــا وبيــان حــق بعضهمــا علــى‬\n‫األخــر وعــدم نســيان الفضــل بينهمــا وكــذا العشــرة ومــا بينهمــا مــن‬\n‫أوالد ‪ ،‬وأن عليهمــا التأنــي والتعقــل ومحاولــة االصطــاح لــرأب الصــدع‬\n\n\n                                                                                      ‫‪60‬‬\n\f     ‫ولــم الشــمل ‪ ،‬هكــذا مت نصحهمــا ‪ ،‬وقــد رأيــت جتاوبــا مــن املدعــى‬\n     ‫عليــه ‪ ،‬ولكــن املدعيــة متــرددة وتكــرر الشــكوى ‪ ،‬وقــد مت إقناعهمــا‬\n     ‫برفــع اجللســة إلــى مــا بعــد عيــد األضحــى املبــارك ‪ ،‬لعــل اهلل يحــدث‬\n     ‫بعــد ذلــك أمــرا ‪ ،‬وأفهمــت املدعيــة مبراجعتنــا بعــد عيــد األضحــى‬\n     ‫إلعطائهــا موعــدا آخــر عنــد مراجعتهــا ‪ ،‬وملعرفــة مــا قــد يســتجد‬\n     ‫بينهمــا بنــاءا علــى مــا مت مــن وعــظ ونصــح ‪ ،‬ففهمــت ذلــك وقنعــت بــه‬\n     ‫‪ ،‬وبــذا رفعــت اجللســة إلــى مــا بعــد عيــد األضحــى لهــذا العــام ‪1432‬ه ـ‬\n     ‫‪ ،‬ويف يــوم الســبت املوافــق ‪1434/6/3‬ه ـ افتتحــت اجللســة الرابعــة يف‬\n     ‫الســاعة العاشــرة ‪ ،‬وفيهــا حضــرت املدعيــة برفقــة شــقيقها ‪..........‬حامــل‬\n     ‫البطاقــة رقــم ‪ ،..........‬وقالــت ليــس لــدي ســوى مــا قدمتــه ســابقا وأنــا‬\n     ‫ال زلــت علــى طلبــي الســابق‪ ،‬وقــد مت فســخ عقــد النــكاح بينــي وبــن‬\n     ‫املدعــى عليــه مبوجــب حكــم شــرعي مــن احملكمــة العامــة بخميــس‬\n     ‫مشــيط وصــدق ذلــك احلكــم مــن محكمــة االســتئناف مبنطقــة عســير‬\n     ‫هكــذا قالــت ‪،‬كمــا حضــر املدعــى عليــه وقــال إننــي أطلــب إيقــاف‬\n     ‫النظــر يف هــذه القضيــة حتــى الفصــل يف قضيــة نفقــة وحضانــة أوالدي‬\n     ‫املرفوعــة مــن قبــل املدعيــة لــدى احملكمــة العامــة بخميــس مشــيط‬\n     ‫وذلــك علــى ضــوء املادة(‪)82‬مــن نظــام املرافعــات الشــرعية والئحتــه‬\n     ‫التنفيذيــة‪ ،‬وإذا انتهــت تلــك القضيــة فــا مــا نــع لــدي مــن إكمــال النظر‬\n     ‫يف هــذه القضيــة بالوجــه الشــرعي ‪ ،‬ألننــي أرى أن إكمــال النظــر يف‬\n     ‫هــذه القضيــة يتوقــف علــى إكمــال النظــر يف القضيــة األخــرى علــى‬\n     ‫ضــوء املــادة‪ 83/1/2‬مــن نظــام املرافعــات الشــرعية ‪ ،‬وصحيــح أنــه مت‬\n     ‫احلكــم بفســخ عقــد النــكاح بينــي وبــن املدعيــة وصــدق احلكــم مــن‬\n     ‫محكمــة االســتئناف ولكننــي ال زلــت غيــر مقتنــع بهــذا الفســخ ولهــذا‬\n\n\n‫‪61‬‬\n\f‫فقــد رفعــت التماســا بهــذا إلــى املجلــس األعلــى للقضــاء هكــذا أجــاب‬\n‫‪ ،‬وبعــرض ذلــك علــى املدعيــة قالــت إننــي أرغــب يف إنهــاء قضيتــي هــذه‬\n‫بالوجــه الشــرعي وعــدم ربطهــا بــأي قضيــة أخــرى ال عالقــة لهــا بهــذه‬\n‫القضيــة هكــذا أجابــت ‪ ،‬ويف هــذه اجللســة متــت احملاولــة مــرة أخــرى‬\n‫ألجــل اإلصــاح بــن الطرفــن ومت عــرض عــدة حلــول بينهمــا إال أن‬\n‫املدعــى عليــه لــم يتجــاوب مــع أي عــرض مــن تلــك احللــول رغــم إبــداء‬\n‫املدعيــة للموافقــة علــى بعــض احللــول املقدمــة ممــا تعــذر معــه الصلــح‬\n‫ولــزم األمــر إنهــاء دعــوى املدعيــة بالوجــه الشــرعي ‪ ،‬ولــم أر وجاهــة‬\n‫لطلــب املدعــى عليــه إيقــاف النظــر يف هــذه القضيــة ‪ ،‬ألنــه ال عالقــة‬\n‫لهــا مباذكــره مــن مطالبــات أخــرى ‪ ،‬فنظــرا إلــى مــا ورد يف الدعــوى ‪،‬‬\n‫وإلــى إجابــة املدعــى عليــه ‪،‬وحيــث أنكــر مــا نســب إليــه إال أن املدعيــة‬\n‫قدمــت مــا يؤيــد دعواهــا وكانــت لهجتهــا قويــة ومطالبتهــا متكــررة‬\n‫وأبــدت تظلمهــا أكثــر مــن مــرة وكانــت تظهــر بــكل قــوة قدرتهــا علــى‬\n‫أداء اليمــن أنهــا صادقــة بــكل مــا أدعــت بــه علــى املدعــى عليــه بينمــا‬\n‫قــرر املدعــى عليــه عــدم قدرتــه علــى بــذل اليمــن لــو طلبــت منــه ممــا‬\n‫توجــه معــه لــدي التهمــة إلــى املدعــى عليــه مبــا أدعــت بــه جتاهــه املدعيــة‬\n‫مــن اعتــداء وســب وشــتم وتعريــض بالقــذف ‪ ،‬ومــا كان ينبغــي للمدعــي‬\n‫ذلــك ألن أصــل احليــاة الزوجيــة إمســاك مبعــروف أو تســريح بإحســان وال‬\n‫يحــل للمســلم أن يعتــدي علــى مــن كان بعيــدا عنــه ومــن بــاب أولــى عــدم‬\n‫االعتــداء علــى مــن هــو قريــب منــه ‪،‬وعندمــا أبــاح اهلل تعالــى للرجــل أن‬\n‫يضــرب زوجتــه فإمنــا ذلــك بشــروط كثيــرة منهــا عــدم ضــرب الوجــه‬\n‫ومنهــا تعــذر جــدوى النصــح واإلعــراض والهجــر ثــم ال يكــون الضــرب‬\n‫بعــد ذلــك إال ضربــا غيــر مبــرح ‪ ،‬ولهــذا قــررت مؤاخــذة املدعــى عليــه‬\n\n\n                                                                                        ‫‪62‬‬\n\f     ‫يف هــذه القضيــة وال ســيما وقــد زاد بــه احلــد إلــى التلفــظ بألفــاظ أدت‬\n     ‫إلــى التعريــض مبــا ال يحــل التعريــض بــه فضــا عــن التصريــح بــه ‪،‬‬\n     ‫ومــا ذكرتــه آنفــا موجــب لتشــديد العقوبــة علــى املدعــى عليــه ‪ ،‬وهــذه‬\n     ‫العقوبــة هــي التعزيــر يف كل مــا نســب إليــه ‪ ،‬إال أنــه ومــع ذكــر‬\n     ‫موجبــات تشــديد العقوبــة فــإن هنــاك موجبــات لتخفيــف العقوبــة يف‬\n     ‫هــذه القضيــة وهــي كــون األدلــة مجــرد قرائــن إضافــة إلــى وجودالقرابة‬\n     ‫بــن الطرفــن ‪ ،‬كمــا أن بينهمــا أوالد وأواصــر الرحــم ال زالــت بينهمــا‬\n     ‫والســيما وقــد قــال اهلل تعالــى بعــد الفــراق «وال تنســوا الفضــل بينكــم»‬\n     ‫‪ ،‬ولهــذا اختــرت التوســط يف العقوبــة بــن اجلانبــن ‪ ،‬وبنــاء علــى كل مــا‬\n     ‫تقــدم فقــد توجهــت لــدي التهمــة إلــى املدعــى عليــه باعتدائــه بالضــرب‬\n     ‫علــى املدعيــة وســبها وشــتمها والتعريــض بقذفهــا ويســجن لقــاء ذلــك‬\n     ‫خمســة عشــر يومــا ‪ ،‬ورددت طلــب املدعــى عليــه يف إيقــاف النظــر يف‬\n     ‫هــذه القضيــة ملــا ذكرتــه يف احليثيــات أعــاه ‪ ،‬ومبــا تقــدم حكمــت‬\n     ‫‪ ،‬وبعــرض احلكــم علــى الطرفــن قــررا عــدم القناعــة بــه وطلبــا رفعــه‬\n     ‫إلــى محكمــة االســتئناف بالئحــة اعتراضيــة ‪ ،‬فأفهمتهمــا أن عليهمــا‬\n     ‫مراجعــة احملكمــة يــوم الثالثــاء املوافــق ‪1434/6/6‬ه ـ الســتالم صــورة‬\n     ‫مــن احلكــم ومــن ثــم تقــدمي االعتــراض عليــه يف غضــون ثالثــن يومــا مــن‬\n     ‫تاريــخ ذلــك االســتالم ‪ ،‬وأن مــن يتأخــر عــن تقــدمي الئحتــه االعتراضيــة‬\n     ‫أثنــاء املــدة النظاميــة فــإن حقــه يف االعتــراض ســوف يســقط ومــن ثــم‬\n     ‫يكــون احلكــم مكتســبا للقطعيــة يف جانبــه ففهمــا ذلــك ‪ ،‬وبــذا‬\n     ‫انتهــت يف الســاعة احلاديــة عشــرة ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/03‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة لتدقيــق‬\n\n\n‫‪63‬‬\n\f‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس مشــيط برقــم‬\n‫‪ 342097209‬وتاريــخ ‪1434/10/11‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيل ــة القاضــي باحملكمــة الشــيخ‪.......... /‬برقــم ‪ 34229637‬وتاريــخ‬\n      ‫‪1434/6/4‬ه ـ اخلــاص بدعــوى ‪.......... /‬ض ـ ـ ـ ـ ــد ‪.......... /‬يف قضيــة‬\n‫( إيــذاء زوجتــه بالضــرب والســب والشــتم ) علــى الصفــة املوضحــة يف‬\n‫القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وحيــث‬\n‫ســبق دراســة القــرار وصــورة ضبطــه والئحتــي االعتــراض وأوراق‬\n‫املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه وأحلقــه بالقــرار وصــورة‬\n‫ـاء علــى قرارنــا رقــم ( ‪ ) 34288368‬وتاريــخ ‪1434/8/6‬ه ـ ‪.‬‬              ‫ضبطــه بنـ ً‬\n‫تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                              ‫وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                         ‫‪64‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":57,"source_page_end":64,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c671bf812c265f38b337df4b6948f870b79f200b0e2c6bf390f912fc098961ff","normalized_text_hash":"a1f229a3d4089e5ad5652d4f2fa80f7787c5562534f79d6c553f30d278737b33","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p57-34229637"},{"id":"046960c5-21f6-51bd-bcea-22eb213fce6c","document_type":"judgment","category":"judicial","subcategory":"general","title":"قذف -إيذاء -تشهير -إساءة سمعة -جرمية معلوماتية يف حق خاص -عدم قبول الرجوع عن اإلقرار يف حق آدمي -قذف من ال يتصور منه الزنا -نسبة الولد لغير أبيه هو قذف ألمه -إقامة حد القذف ثمانن جلدة وعدم قبول شهادة املدعى عليها إال بعد توبتها -التعزير بالسجن واجللد.","document_number":"3459216","case_number":"32560705","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/10","year":"1434","subject":"قذف -إيذاء -تشهير -إساءة سمعة -جرمية معلوماتية يف حق خاص -عدم قبول الرجوع عن اإلقرار يف حق آدمي -قذف من ال يتصور منه الزنا -نسبة الولد لغير أبيه هو قذف ألمه -إقامة حد القذف ثمانن جلدة وعدم قبول شهادة املدعى عليها إال بعد توبتها -التعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3459216 :‬تاريخه‪1434/3/10 :‬هـ‬\n                         ‫رقم الدعوى‪32560705:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 35267898‬تاريخه‪1435/6/7 :‬هـ‬\n\n\n\n     ‫قــذف ‪ -‬إيــذاء ‪ -‬تشــهير ‪ -‬إســاءة ســمعة ‪ -‬جرميــة معلوماتيــة يف حــق‬\n     ‫خــاص ‪ -‬عــدم قبــول الرجــوع عــن اإلقــرار يف حــق آدمــي ‪ -‬قــذف مــن ال‬\n     ‫يتصــور منــه الزنــا ‪ -‬نســبة الولــد لغيــر أبيــه هــو قــذف ألمــه ‪ -‬إقامــة‬\n     ‫حــد القــذف ثمانــن جلــدة وعــدم قبــول شــهادة املدعــى عليهــا إال بعــد‬\n                                            ‫توبتهــا ‪ -‬التعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n     ‫‪-‬قــول اهلل تعالــى‪( :‬فــا وربــك ال يؤمنــون حتــى يحكمــوك فيمــا شــجر‬\n                                                                         ‫بينهــم)‪.‬‬\n     ‫‪-‬جــاء يف كشــاف القنــاع‪« :)91/14( :‬وإن قــذف جماعــة يتصــور الزنــى‬\n                  ‫ا «‪.‬‬\n                     ‫منهــم عــادة بكلمــات حــد لــكل واحــد منهــم حــدا كامـ ً‬\n\n\n\n\n     ‫تقــدم أحــد املواطنــن ألميــر املنطقــة بشــكوى مفادهــا أن شــقيقته‬\n     ‫ُش ـ ِوهت ســمعتها بــكالم بــذيء عــن طريــق إحــدى مواقــع االنترنــت‬\n     ‫واملنتديــات وال يتهــم أحــد ًا بذلــك ‪ ،‬و بإجــراء البحــث والتحــري عــن‬\n     ‫مصــدر التشــهير واإلســاءة ضــد املجنــي عليهــا ظهــر أن امللقم الذي كان‬\n     ‫يســتخدمه اجلانــي لطليــق املدعيــة باحلــق اخلــاص‪ ،‬وباســتجواب املذكــور‬\n     ‫أفــاد أن امللقــم املســتخدم مــن خــال الهاتــف يعــود لــه ويســتخدم هــو‬\n\n‫‪65‬‬\n\f‫وزوجتــه (اجلانيــة)‪ ،‬انتهــى التحقيــق مــع املدعــى عليهــا إلــى اتهامهــا‬\n‫بإســاءة ســمعة امــرأة والتشــهير بهــا يف مواقــع اإلنترنــت‪ ،‬طلــب املدعــي‬\n‫العــام إثبــات مــا أســند إليهــا واحلكــم عليهــا وفــق الفقــرة اخلامســة مــن‬\n‫املــادة الثالثــة مــن نظــام مكافحــة اجلرائــم املعلوماتيــة‪ ،‬بعــرض دعــوى‬\n‫املدعــي العــام علــى املدعــى عليهــا أنكرتهــا جملــة وتفصيــا‪ ،‬وبعــد أن‬\n‫وزانــت احملكمــة بــن أقــوال األطــراف قــررت احلكــم بجلدهــا ثمانــن‬\n‫جلــدة حــد القــذف وبعــدم قبــول شــهادتها إال بعــد توبتهــا كمــا ثبتــت‬\n‫إدانتهــا بجرميــة التشــهير بغيــر وجــه حــق باملدعيــة وإســاءة ســمعتها عبــر‬\n‫املواقــع اإللكترونيــة واحلكــم عليهــا بالســجن ســتة أشــهر وبالغرامــة‬\n‫عشــرة آالف ريــال للحــق العــام وبســجنها ســنة وســتة أشــهر للحــق‬\n‫اخلــاص‪ ،‬وإفهامهــا أال يتكــرر منهــا ذلــك مســتقبال ويكــون هــذا‬\n‫احلكــم شــامال للحقــن اخلــاص والعــام‪ ،‬وبعــرض احلكــم علــى املدعــى‬\n‫عليهــا قــررت عــدم قناعتهــا واالعتــراض بالئحــة وقــرر املدعــون باحلــق‬\n‫اخلــاص االعتــراض كل بالئحــة وقــرر املدعــي العــام واملدعيــة باحلــق‬\n   ‫اخلــاص عــدم املعارضــة وجــرى التصديــق مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n                                                                                     ‫‪66‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنا‪......‬القاضــي باحملكــة اجلزئيــة باملدينــة‬\n     ‫املنــورة والقائــم بعمــل القاضــي ‪ ......‬القاضــي يف احملكمــة اجلزئيــة‬\n     ‫باملدينــة املنــورة إثنــاء إجازتــه وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n     ‫رئيــس احملكمــة اجلزئيــة باملدينــة املنــورة برقــم ‪ 32560705‬وتاريــخ‬\n     ‫‪ 1432/11/26‬ه ـ املقيــدة باحملكمــة برقــم ‪ 321522230‬وتاريــخ‬\n     ‫‪1432/11/26‬ه ـ ففــي يــوم األحــد املوافــق‪ 1433/04/11‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة ‪ 10 : 13‬وفيها ادعى املدعي العام ‪......‬ســعودي مبوجب‬\n     ‫الســجل املدنــي رقــم‪ ......‬والتعميــد رقــم ‪ 17648‬وتاريــخ ‪1432/6/12‬ه ـ‬\n     ‫علــى ‪ ......‬ســعودية مبوجــب الســجل املدنــي رقــم ‪ ......‬محصنــه مطلقــة‬\n     ‫الســراح بالكفالــة احلضوريــة قائــا يف حتريــر دعــواه انــه بتاريــخ‬\n     ‫‪1430/11/7‬ه ـ تقــدم املواطــن ‪ ......‬لصاحــب الســمو امللكــي أميــر‬\n     ‫منطقــة ‪ .....‬مفادهــا أن شــقيقته تعمــل يف جامعــة ‪ .....‬وحتمــل شــهادة‬\n     ‫الدكتــوراه وقــد مت تشــويه ســمعتها بــكالم بــذيء عــن طريــق إحــدى‬\n     ‫مواقــع اإلنترنــت وموقــع منتديــات طــاب وطالبــات جامعــة …‪ .‬واليتهــم‬\n     ‫أحــدا وبإجــراء البحــث والتحــري عــن مصــدر التشــهير واإلســاءة ضــد‬\n     ‫املجنــي عليهــا ظهــر ان امللقــم الــذي كان يســتخدمه اجلانــي تابع للهاتف‬\n     ‫رقــم ‪......‬العائــد للمدعــو‪ ......‬طليــق املذكــورة وباســتجواب ‪ ......‬افــاد ان‬\n     ‫امللقــم املســتخدم مــن خــال الهاتــف رقــم ‪......‬يعــود لــه ويســتخدمه هــو‬\n     ‫وزوجتــه ‪......‬فقــط وباســتجواب املــرأة املدعــى عليهــا ‪......‬اعترفــت انهــا‬\n     ‫هــي مــن قامــت بإســاءة ســمعة الدكتــورة ‪......‬مــن خــال اإلنترنــت‬\n     ‫والتشــهير بهــا وبــررت ذلــك بغيرتهــا منهــا ألن زوجهــا قــرر إرجاعهــا‬\n\n‫‪67‬‬\n\f‫الــى عصمتــه بعــد طالقهــا وذكــرت انــه لــم يشــاركها احــد يف ذلــك‬\n‫وانتهــى التحقيــق الــى اتهــام املــرأة املدعــى عليهــا ‪......‬بإســاءة ســمعت‬\n‫امــرأة والتشــهير بهــا يف مواقــع االنترنــت وذلــك لألدلــة التاليــة ‪-1 :‬‬\n‫اعترافهــا ‪ -2‬مــا ورد يف برقيــة صاحــب الســمو نائــب وزيــر الداخليــة‬\n‫املرفــق وببحــث ســوابقها لــم يعثــر لهــا علــى ســوابق وحيــث ان مــا اقــدم‬\n‫عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرعا اطلــب اثبــات مــا اســند‬\n‫اليهــا واحلكــم عليهــا وفــق املــادة الثالثــة فقــره ‪ 5‬مــن نظــام مكافحــة‬\n‫اجلرائــم املعلوماتيــة وبعــرض دعــوى املدعــي العــام علــى املدعــى عليهــا‬\n‫اجابــت بــأن مــا ذكــره املدعــي العــام غيــر صحيــح جملــة وتفصيــا‬\n‫هكــذا اجابــت ولطلــب البينــة مــن املدعــي العــام علــى مــا ادعــى بــه‬\n‫وانكرتــه املدعــى عليهــا ويف جلســة الحقــة لــدي أنــا ‪......‬حضــرت‬\n‫املتهمــة وبجانبهــا وكيلهــا اخوهــا ‪......‬ســعودي مبوجــب الســجل املدنــي‬\n‫رقــم ‪......‬مبوجــب الوكالــة رقــم ‪ ......‬يف ‪1433/4/26‬ه ـ مــن كتابــة‬\n‫عــدل املدينــة الثانيــة كمــا حضــر وكيــا املدعيــة باحلــق اخلــاص ‪......‬‬\n‫ســعودي مبوجــب الســجل املدنــي رقــم ‪......‬و‪......‬مبوجــب الوكالــة رقــم‬\n‫‪......‬يف ‪1432/12/2‬ه ـ وقــدم وكيــل املتهمــة مذكــرة بدفــاع موكلتــه‬\n‫أكــد فيهــا نفــي االتهــام املوجــه اليهــا وأن طليقها ‪......‬هــو الذي اجبرها‬\n‫علــى االعتــراف امــام هيئــة التحقيــق واالدعــاء العــام وســلمت صــورة مــن‬\n‫املذكــرة لوكيلــي املدعيــة وإلحضــار طليــق املتهــم ‪......‬رفعــت اجللســة‬\n‫فحضــر وكيــل املدعيــة كمــا حضــر طليقهــا ‪ ......‬ســعودي مبوجــب‬\n‫الســجل املدنــي رقــم ‪......‬كمــا حضــر وكيــل ‪......‬و ‪......‬و‪......‬الســابق‬\n‫حضوره وبسؤال احلاضر ‪......‬عما جاء بإفادة املدعى عليها ووكيلها‬\n‫مــن أنــه اجبرهــا علــى االدالء بأقوالهــا امــام هيئــة التحقيــق واالدعــاء‬\n\n\n                                                                                   ‫‪68‬‬\n\f     ‫العــام وغيرهــا مــن االقــرارات اجــاب مــا ذكرتــه املدعــى عليهــا‬\n     ‫ووكيلهــا غيــر صحيــح وبســؤال املدعــى عليهــا ووكيلهــا هــل توجــد‬\n     ‫بينــه علــى االكــراه فيمــا ادليــت بــه اجابــت هددنــي بابنــي ‪......‬وتقريــر‬\n     ‫املستشــفى املرفــق انــه ضربنــي وبعــرض ذلــك علــى طليقهــا اجــاب كل‬\n     ‫مــا ذكرتــه غيــر صحيــح فتــم حجــز القضية للدراســة وســمح لألطراف‬\n     ‫بتقــدمي مذكــرات وتبــادل بينهــم خــال االجــل ويف املوعــد احملــدد‬\n     ‫حضــرت املدعــى عليهــا ‪ ......‬وحضــر بجانبهــا وكيلهــا كمــا حضــر‬\n     ‫وكيــل املدعيــة كذلــك حضــر وكيــل كل مــن ‪......‬و‪ ......‬و‪ ......‬أبنــاء‬\n     ‫‪......‬وقــدم وكيــل املدعيــة مذكــرة طلــب فيهــا تعديــل االتهــام بحيــث‬\n     ‫يشــمل األمــر الــذي جرمتــه املــادة السادســة مــن نظــام مكافحــة اجلرائم‬\n     ‫املعلوماتيــة ســلمت نســخة عنهــا لوكيــل املدعــى عليهــا ونســخة للمدعــي‬\n     ‫العــام كمــا قــدم وكيــل املدعــى عليهــا مذكــرة بدفاع موكلته ســلمت‬\n     ‫نســخة عنهــا لوكيــل املدعيــة ولوكيــل كل مــن ‪......‬و‪ ......‬و‪ ......‬وطلــب‬\n     ‫وكيــل املدعيــة إعطــاءه مهلــة لتقــدمي طلبــات موكلتــه ويف املوعــد‬\n     ‫حضــرت املتهمــة وبجانبهــا وكيلهــا ‪......‬كمــا حضــر وكيــل املدعيــة‬\n     ‫باحلــق اخلــاص ‪......‬كمــا حضــر ‪......‬اصيــا عــن نفســه ووكيــا عــن‬\n     ‫والــده ‪ ......‬و‪ ......‬و‪ ......‬و‪ ......‬و‪......‬و‪ ......‬و‪ ......‬و‪......‬و‪ ......‬و‪......‬ابنــاء ‪......‬‬\n     ‫مبوجــب التوكيــل رقــم ‪......‬يف ‪1429/11/25‬ه ـ والوكالــة رقــم ‪......‬يف‬\n     ‫‪1433/11/24‬ه ـ وبســؤاله عــن دعــواه ودعــوى موكليــه اجــاب اننــا‬\n     ‫نطالــب مبــا يســتحق لنــا شــرعا نظيــر قــذف اختنــا ‪......‬والتشــهير بهــا‬\n     ‫باســم العائلــة وقــدم مذكــرة ســلمت نســخة عنهــا حملامــي املتهمــة الــذي‬\n     ‫طلــب اجــا للــرد وقــدم وكيــل املتهمــة مذكــرة ردا علــى مذكــرة‬\n     ‫محامــي املدعيــة ولتبــادل املذكــرات ترفــع اجللســة ويف املوعــد احملــدد‬\n\n\n‫‪69‬‬\n\f‫حضــر األطــراف قــدم كل طــرف مــا لديــه ومتســك بــه وعليــه وبنــاء علــى‬\n‫مــا جــاء بالئحــة االتهــام والتــي انتهــى فيهــا التحقيــق إلــى توجيــه االتهــام‬\n‫إلــى ‪ 27 ......‬ســنة ســعودي اجلنســية بإســاءة ســمعة امــرأة والتشــهير بهــا‬\n‫يف مواقــع اإلنترنــت ولكــون مــا أقدمــت عليــه فعــل محــرم ومعاقــب عليــه‬\n‫شــرعا طلــب املدعــي العــام إثبــات مــا أســند إليهــا واحلكــم عليهــا وفــق‬\n‫املــادة الثانيــة فقــرة (‪ )5‬مــن نظــام مكافحــة جرائــم املعلوماتيــة وبنــاء‬\n‫علــى الدعــوى التــي تقدمــت بهــا املدعيــة ‪......‬التــي تعمــل عضــو هيئــة‬\n‫تدريــس بجامعــة طيبــة بواســطة شــقيقها ‪......‬ضــد املتهمــة املذكــورة‬\n‫ذلــك أنهــا شــهرت بهــا عــن طريــق اإلنترنــت ورميهــا بــكالم بــذيء‬\n‫وقذفهــا بالزنــا صراحـ ًة طبقــا ملــا هــو موجــود يف مواقــع اإلنترنــت ومواقع‬\n‫منتديــات طــاب وطالبــات جامعــة طيبــة وبنــاء علــى املذكــرة املقدمــة‬\n‫مــن محاميهــا ‪......‬الــذي شــرح فيهــا دعــوى موكلتــه وطلــب فيهــا احلكــم‬\n‫بحــد القــذف وبتعزيرهــا تعزيــرا بليغــا بالســجن واجللــد لســبها وشــتمها‬\n‫موكلتــه واحلكــم بتعزيرهــا بالســجن واجللــد لتوزيعهــا ونشــرها رقــم‬\n‫جــوال موكلتــه ودعوتهــا إقامــة عالقــات معهــا واحلكــم بســجنها‬\n‫وجلدهــا لتصويــر موكلتــه ودبلجتهــا وتركيبهــا علــى أشــكال مخلــة‬\n‫بالشــرف وســجنها وجلدهــا إلســاءة ســمعة موكلتــه وباألخــص يف‬\n‫محيــط اجلامعــة وانتهــى إلــى طلــب تعويــض قــدره مليــون ريــال لقــاء مــا‬\n‫حلقهــا مــن ضــرر واحلكــم عليهــا بــأن تقــدم اعتــذارا ملوكلتــه يف املواقــع‬\n‫اإللكترونيــة التــي اســتخدمتها ويف اجلريــدة الرســمية وبنــاء علــى‬\n‫الدعــوى التــي تقــدم بهــا وكيــل أســرة املجنــي عليهــا ‪......‬وهــم والدهــا‬\n‫وإخوانهــا وأخواتهــا يطلــب فيهــا رد اعتبارهــم مــن املدعــى عليهــا وبنــاء‬\n‫علــى دعــوى كل مــن املدعيــن ‪......‬و‪ ......‬و‪ ......‬أبنــاء‪ ......‬بــأن املتهمــة‬\n\n\n                                                                                         ‫‪70‬‬\n\f     ‫تلفظــت عليهــم بالقــذف الصريــح وطعنــت يف نســبهم ألبيهــم كمــا جــاء‬\n     ‫علــى لســان موكلهــم ‪......‬الــذي طلــب يف نهايــة دعــواه احلكــم عليهــا‬\n     ‫بحــد القــذف وبنــاء علــى مــا أجابــت بــه املتهمــة حيــث أنكــرت مــا جــاء‬\n     ‫بالئحــة االتهــام ودعــاوى املدعيــن باحلــق اخلــاص وحيــث مت االطــاع على‬\n     ‫أقوالهــا لــدى هيئــة التحقيــق واالدعــاء العــام فوجــدت معترفــة صراحــة‬\n     ‫بقــذف املدعيــة بالزنــا وفعــل الفواحــش وكالم بــذيء ميــس شــرفها‬\n     ‫وشــرف أوالدهــا مــن الدكتــور ‪......‬زوجهــا الســابق عــن طريــق املوقــع‬\n     ‫اإللكترونــي الــوارد يف األوراق وملــا ووجهــت بــه قالــت أن زوجهــا ‪......‬‬\n     ‫املذكــور أجبرهــا علــى هــذا االعتــراف حتــت التهديــد لكنهــا لــم تقــدم‬\n     ‫دليــا علــى ذلــك وكل الــذي تذرعــت بــه تهديدهــا ونــزع ابنهــا ‪......‬مــن‬\n     ‫يدهــا وضربهــا الضــرب الــوارد باالســتمارة الطبيــة لكــن ذلــك ال يبــرر‬\n     ‫مــا أدلــت بــه وبالتالــي فــإن هــذا اإلقــرار حجــة عليهــا تعامــل مبقتضــاه‬\n     ‫شــرعا ألنــه أخــذ أمــام جهــة رســمية مخولــة بأخــذه وهــو إقــرار يف حــق‬\n     ‫آدمــي معصــوم ال يجــوز الرجــوع فيــه وممــا تقــدم يتضــح أن الدعــوى ذات‬\n     ‫شــقني شــق يتعلــق بحــد القــذف وشــق يتعلــق بدعــوى التشــهير ويجانــب‬\n     ‫هذين الشــقني مطالبة باحلق اخلاص وفيما يتعلق بالشــق االول فســيطبق‬\n     ‫فيهــا حــد القــذف الشــرعي ومــا يتعلــق بالشــق الثانــي ففيــه التعزيــر‬\n     ‫املناســب فيمــا ال يتعــارض مــع نظــام مكافحــة اجلرائــم املعلوماتيــة ومبــا‬\n     ‫أن تعــدد املقذوفــن يوجــب حــدا بقــدر تعددهــم كمــا نــص علــى ذلــك‬\n     ‫صاحــب كشــاف القنــاع ص‪ 91‬ج‪ 41‬حيــث قــال»وإن قــذف جماعــة‬\n     ‫يتصــور الزنــى منهــم عــادة بكلمــات حــد لــكل واحــد منهــم حــدا‬\n     ‫كامــا» ومبــا أن املطالبــن بحــد القــذف هــم كل مــن ‪ ......‬و‪......‬مــن‬\n     ‫مواليــد ‪1419/07/03‬ه ـ و‪......‬مــن مواليــد ‪1422/07/03‬ه ـ و‪......‬مــن‬\n\n\n‫‪71‬‬\n\f‫مواليــد ‪1425/3/4‬ه ـ لكــن هــؤالء األبنــاء نســبتهم إلــى غيــر أبيهــم هــو‬\n‫يف احلقيقــة قــذف ألمهــم املذكــورة وقــد حركــت الدعــوى بذلــك وبحــد‬\n‫واحــد يظهــر كــذب القــاذف وتــزول املعــرة فوجــب أن يكتفــي بذلــك‬\n‫أمــا دعــوى أســرتها والدهــا واخوتهــا بــرد اعتبارهــم فــإن يف عقوبــة حــد‬\n‫القــذف والتشــهير جبــرا لــكل األضــرار التــي ذكروهــا وردا العتبارهم‬\n‫وشــفاء ملــا يف النفــوس وعلــى املؤمــن أن يذعــن حلكــم اهلل عــز وجــل‬\n‫ورســوله صلــى اهلل وعليــه وســلم قــال تعالى(فــا وربــك ال يؤمنــون حتــى‬\n‫يحكمــوك فيمــا شــجر بينهــم) اآليــة وفيمــا يخــص طلــب التعويــض‬\n‫املــادي املقــدر مبليــون ريــال فــإن الشــريعة اإلســامية ال جتعــل شــرف‬\n‫اإلنســان وســمعته مــاال متقومــا وأيضــا فهــو أمــر معنــوي ال ميكــن تقديره‬\n‫وحتديــده وليــس لــه ضابــط والضــرر األدبــي املعنــوي ال يجيــره التعويــض‬\n‫املــادي وإمنــا شــرعت فيــه العقوبــة باحلــد واألدب وهــو أمــر مناســب جلبــر‬\n‫الضــرر وســيكون احلكــم شــامال للحقــن اخلــاص والعــام مــن أجــل مــا‬\n‫تقــدم حكمــت بإدانــة املتهمــة بجرميــة قــذف املدعيــة ‪......‬واحلكــم‬\n‫بجلدهــا ثمانــن جلــدة حــد القــذف وبعــدم قبــول شــهادتها إال بعــد توبتهــا‬\n‫وبإدانتهــا بجرميــة التشــهير بغيــر وجــه حــق باملدعيــة واســاءة ســمعتها عبر‬\n‫املواقــع اإللكترونيــة واحلكــم عليهــا بالســجن ســنتني وبالغرامــة عشــر‬\n‫آالف ريــال وأفهمتهــا بــأال يتكــرر منهــا ذلــك مســتقبال حكمــا شــامال‬\n‫للحقــن اخلــاص والعــام بــذا صــدر احلكــم وأفهــم حســب األصــول‬\n‫فقــررت املتهمــة عــدم قناعتهــا واالعتــراض بالئحــة وقــرر املدعــون باحلــق‬\n‫اخلــاص االعتــراض كل بالئحــة وقــرر املدعــي العــام عــدم املعارضــة‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                   ‫وسلم ‪ .‬حرر يف ‪1434/3/3‬هـ‬\n\n\n                                                                                    ‫‪72‬‬\n\f     ‫احلمــد اهلل وحــده وبعــد لــدي أنــا ‪ ......‬القاضــي باحملكمــة اجلزائيــة‬\n     ‫باملدينــة املنــورة ففــي يــوم الثالثــاء املوافق‪1434/06/27‬ه ـ افتتحــت‬\n     ‫اجللســة وفيهــا جــرى االطــاع علــى القــرار رقــم ‪ 34236414‬وتاريــخ‬\n     ‫‪1434/06/11‬ه ـ الصــادر مــن محكمــة االســتئناف الدائــرة اجلزائيــة‬\n     ‫الثانيــة مبكــة املكرمــة بتصديــق احلكــم الصــادر عنــا بالقــرار‬\n     ‫رقــم ‪ 3459216‬وتاريــخ ‪1434/03/10‬ه ـ ولكــي ال يخفــى جــرى‬\n     ‫التهميــش وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n     ‫حــرر يف ‪1434/06/27‬ه ـ احلمــد هلل وحــده وبعــد فلــدي أنــا ‪......‬‬\n     ‫القاضــي يف احملكمــة اجلزائيــة باملدينــة املنــورة ففــي يــوم األحــد‬\n     ‫املوافق‪1434/09/20‬ه ـ افتتحــت اجللســة الســاعة وفيها حضــر‪......‬و‪......‬‬\n     ‫الســابق حضورهمــا‪ .‬بنــاء علــى خطــاب مديــر مركــز شــرطة ‪......‬رقــم‬\n     ‫‪22/6709/22‬وتاريــخ ‪1434/9/7‬ه ـ بشــأن االستفســار عــن العقوبــة‬\n     ‫املوقعــة علــى احملكــوم عليهــا ‪ ......‬لتحديــد احلكــم للحــق العــام‬\n     ‫ليتســنى للجنــة دراســة أوراقهــا علــى ضــوء تعليمــات العفــو وعليــه مت‬\n     ‫اعــادة الدعــوى للمرافعــة واســتدعاء احملكــوم عليهــا واحملكــوم لهــا‬\n     ‫واملدعــي العــام فحضــر ‪ ......‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n     ‫رقــم ‪ .....‬مبوجــب الوكالــة رقــم ‪ 70904‬يف‪1432/12/2‬ه ـ وكيــا عــن‬\n     ‫املدعيــة ‪ ......‬كمــا حضــر ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n     ‫رقــم …… وكيــا عــن احملكــوم عليهــا بدريــة مبوجــب التوكيــل رقــم‬\n     ‫‪29672‬وتاريــخ ‪1433/04/26‬ه ـ وبعــد االطــاع علــى كامــل األوراق‬\n     ‫فقــد تقــرر جعــل عقوبــة احلــق العــام ســتة أشــهر والغرامــة املذكــورة‬\n     ‫وابقــاء احلكــم فيمــا عــدا ذلــك للحــق اخلــاص بالنســبة حلــد القــذف‬\n     ‫والســجن ســنه وســتة أشــهر فقــرر وكيــل املدعيــة قناعتــه وقــرر وكيــل‬\n\n\n‫‪73‬‬\n\f‫احملكــوم عليهــا اعتراضــه بالئحــة فأفهــم بتعليمــات االســتئناف وقــرر‬\n‫املدعــي العــام االعتــراض بــدون الئحــة‪ ... .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/9/20‬ه ـ‬\n   ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪-:‬‬\n‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثانيــة يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪321522230‬‬\n‫وتاريــخ ‪1434/5/21‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ‪/‬‬\n‫…‪ .‬القاضــي باحملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪3459216‬‬\n‫وتاريــخ ‪1434/3/10‬ه ـ ‪ ،‬املتضمــن دعــوى املدعــي العــام ضد‪، …… /‬‬\n‫املتهمــة يف قضيــة تشــهير ‪ ،‬احملكــوم فيــه مبــا دون باطنــه ‪ .‬وبدراســة‬\n‫القــرار وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق‬\n                 ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪74‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":65,"source_page_end":74,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ae2c671f90d114864283bd0efcff2c87e3fa08937e6e9ab29a4936c58c80f356","normalized_text_hash":"7eabec09f4840454a1dc0e67021f92b9dd0052d85cdd6503124100041c8ce3b0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p65-3459216"},{"id":"8befe02a-fb6c-572d-b74a-da2f7b2dd028","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -ضرب الزوج لزوجته -إنكار الزوج ضرب زوجته -حلف الزوجة اليمن على قيام الزوج بضربها -اليمن تشرع يف جانب أقوى املتداعين -تعزير الزوج بالسجن واجللد لقاء ضربه","document_number":"33327938","case_number":"33172110","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/5","year":"1434","subject":"اعتداء -ضرب -ضرب الزوج لزوجته -إنكار الزوج ضرب زوجته -حلف الزوجة اليمن على قيام الزوج بضربها -اليمن تشرع يف جانب أقوى املتداعين -تعزير الزوج بالسجن واجللد لقاء ضربه","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 33327938 :‬تاريخه‪1433/7/5 :‬هـ‬\n                         ‫رقم الدعوى‪33172110:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34165875‬تاريخه‪1434/3/18 :‬هـ‬\n\n\n\n     ‫اعتــداء ‪ -‬ضــرب ‪ -‬ضــرب الــزوج لزوجتــه ‪ -‬إنــكار الــزوج ضــرب زوجتــه‬\n     ‫‪ -‬حلــف الزوجــة اليمــن علــى قيــام الــزوج بضربهــا ‪ -‬اليمــن تشــرع يف‬\n     ‫جانــب أقــوى املتداعيــن ‪ -‬تعزيــر الــزوج بالســجن واجللــد لقــاء ضربــه‬\n                                                                     ‫لزوجتــه ‪.‬‬\n\n\n\n\n     ‫‪-1‬جتــاوز احلــد الشــرعي فيمــن لــه واليــة التأديــب أمــر محــرم ومعصيــة‬\n                                                                   ‫توجــب التعزير‪.‬‬\n     ‫‪-2‬قــول صاحــب شــرح منتهــى اإلرادات‪ (:‬ولــه ‪ -‬أي‪ :‬الــزوج واألب والســيد‬\n     ‫‪ -‬تأديــب زوجــة وتأديــب ولــد لــو كان الولــد مكلفـ ًا مزوجـ ًا بضــرب غيــر‬\n                                                                ‫مبــرح ) ( ‪.)686 /5‬‬\n     ‫‪-3‬قولــه يف كشــاف القناع‪(:‬ويحــرم ضــرب الوجــه ويف اآلدمــي أشــد‬\n                                              ‫ألنــه أعظــم حرمــة) (‪.)2846 /4‬‬\n                              ‫‪ -4‬اليمني تشرع يف جانب األقوى من املتداعيني‪.‬‬\n\n\n\n\n     ‫تقدمــت املدعيــة بدعــوى ضــد زوجهــا املدعــى عليــه بأنــه أســاء عشــرتها‬\n     ‫وقــام بضربهــا وســعى يف الشــروع بقتلهــا ممــا تركهــا يف حالــة نفســية‬\n     ‫عصيبــة وتطلــب تعزيــره علــى ذلــك‪ ،‬أقــر املدعــى عليــه بــأن املدعيــة ‪-‬‬\n\n‫‪75‬‬\n\f‫زوجتــه ‪ -‬وينكــر ضربهــا واالعتــداء عليهــا وشــروعه يف قتلهــا‪ ،‬بســؤال‬\n‫وكيــل املدعيــة عــن البينــة قــرر بــأن بينتــه التقريــر الطبــي الصــادر مــن‬\n‫أحــد املجمعــات الطبيــة املتضمــن ظهــور آثــار كدمــات متفرقــة باجلســم‬\n‫وكدمتــن بالــذراع األعلــى األميــن وكدمــة بأعلــى الــذراع األيســر‬\n‫وكدمتــن بالســاق األميــن وكدمــة بالســاق األيســر وجــرح عميــق صغير‬\n‫خلــف الكعــب األيســر وجــرح بســيط بالشــفة الســفلية ومــدة الشــفاء‬\n‫أســبوعني مــا لــم حتــدث مضاعفــات‪ ،‬كمــا قــرر املدعــي وكالــة بــأن‬\n‫بينتــه األوراق املرفقــة باملعاملــة ‪ ،‬فجــرى الرجــوع لهــا واالطــاع علــى‬\n‫محضــر االســتجواب للمدعــى عليــه املتضمــن إقــراره بأنــه قــام بســحب‬\n‫املدعيــة مــن رأســها فقــط ‪ ،‬كمــا جــرى االطــاع علــى تقريــر احلالــة‬\n‫األســرية الصــادر مــن مركــز التنميــة األســرية املتضمــن بــأن املدعــى‬\n‫عليــه اعتــرف بشــد رأس املدعيــة وكســر جوالهــا‪ ،‬وبعرضــه علــى‬\n‫املدعــى عليــه أقــر بأنــه قــام بشــد شــعر رأســها وكســر جوالهــا وأنكــر‬\n‫قيامــه بإحلــاق إصابــة بهــا‪ ،‬جــرى توجيــه اليمــن للمدعيــة بنــاء علــى مــا‬\n‫قــرره الفقهــاء مــن أن اليمــن تشــرع يف جانــب األقــوى مــن املتداعيــن‬\n‫فحلفــت املدعيــة اليمــن بــأن املدعــى عليــه قــام بضربهــا علــى وجههــا‬\n‫وشــد شــعر رأســها وضربهــا مــع ذراعيهــا وســاقها ممــا أدى حلــدوث‬\n‫ـاء علــى جميــع مــا ســبق فقــد قــررت‬    ‫اإلصابــة التــي حلقــت بهــا‪ ،‬بنـ ً‬\n‫احملكمــة ثبــوت قيــام املدعــى عليــه بضــرب املدعيــة وتعزيــر املدعــى‬\n‫عليــه بالســجن شــهر ًا حتتســب منهــا مــدة إيقافــه وجلــده خمســن جلــدة‬\n‫دفعــة واحــدة ‪ ،‬وبعــرض احلكــم علــى الطرفــن قــررا االعتــراض عليــه‬\n‫وطلبــا اســتئنافه بالئحــة فأفهمــا بتعليمــات االســتئناف‪ ،‬صــدق احلكــم‬\n                                                    ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n                                                                                     ‫‪76‬‬\n\f     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n     ‫أنــا ‪ ........‬القاضــي باحملكمــة اجلزئيــة بالدمــام بنــاء علــى املعاملــة‬\n     ‫املقيــدة لــدى احملكمــة برقــم ‪33453450‬وتاريــخ ‪1433/03/09‬ه ـ‬\n     ‫واحملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزئيــة بالدمــام‬\n     ‫برقم‪33172110‬وتاريخ‪1433/03/09‬ه ـ افتتحــت اجللســة يف يــوم‬\n     ‫االثنــن ‪1433/04/19‬ه ـ الســاعة احلاديــة عشــرة وفيهــا حضــر‪........‬‬\n     ‫الوكيــل الشــرعي عــن ‪........‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n     ‫عــدل الدمــام الثانيــة برقــم يف ‪1433/04/12‬ه ـ املتضمنــة حــق املرافعــة‬\n     ‫واملدافعــة واملطالبــة والصلــح والتنــازل وطلــب اليمــن ورده أ‪.‬ه ـ وحضــر‬\n     ‫ا إن‬  ‫حلضــوره ‪........‬مبوجــب الســجل املدنــي ‪........‬وادعــى األول قائ ـ ً‬\n     ‫املدعــى عيلــه هــو زوج ملوكلتــي ابنتــي ‪........‬وقــد أســاء عشــرتها وقــام‬\n     ‫بضربهــا وكذلــك حــاول الشــروع يف قتلهــا ممــا أدى بهــا إلــى حالــة‬\n     ‫نفســية عصبيــة لــذا أطلــب تعزيــره علــى ذلــك هكــذا ادعــى‪ ،‬وبعــرض‬\n     ‫الدعــوى علــى املدعــى عليــه قــال ما ذكــره املدعي مــن زواجي مبوكلته‬\n     ‫فذلــك صحيــح وأمــا ضربــي لهــا ومحاولــة الشــروع يف قتلهــا فذلــك غيــر‬\n     ‫صحيــح كلــه ولــم أقــم باالعتــداء عليهــا هكــذا أجــاب وبعــرض ذلــك‬\n     ‫علــى املدعــي وكالــة قــال مــا ذكــره املدعــى عليــه مــن عــدم ضربــه لهــا‬\n     ‫ومحاولــة الشــروع يف قتلهــا فذلــك غيــر صحيــح والصحيح ما ذكرت يف‬\n     ‫دعــواي هكــذا أجــاب وبســؤال املدعــي وكالــة البينــة علــى دعــواه قــال‬\n     ‫بينتــي التقريــر الطبــي وأطلــب مهلــة إلحضــاره ولــذا رفعــت اجللســة ويف‬\n     ‫يــوم الثالثــاء ‪1433/05/25‬ه ـ الســاعة احلاديــة عشــرة افتتحــت اجللســة‬\n\n‫‪77‬‬\n\f‫وفيهــا حضــر الطرفــان وبســؤال املدعــي وكالــة البينــة علــى دعــواه قــال‬\n‫بينتــي مــا جــاء يف التقريــر الطبــي املرفــق بخطــاب رئيــس دائــرة التحقيــق‬\n‫يف قضايــا االعتــداء علــى النفــس رقــم (‪ )........‬وتاريــخ ‪1433/05/05‬ه ـ‬\n‫هكــذا أجــاب ثــم جــرى االطــاع علــى التقريــر الطبــي فوجدتــه صــادر‬\n‫مــن مجمــع الدمــام الطبــي برقــم ‪........‬يف ‪1432/12/02‬ه ـ املتضمــن مــا‬\n‫نصــه (بالكشــف علــى املذكــورة أعــاه بتاريــخ ‪1432/12/02‬ه ـ تبــن‬\n‫وجــود آثــار كدمــات متفرقــة باجلســم كدمتــن بالــذراع األعلــى األميــن‬\n‫كدمــه بأعلــى الــذراع األيســر وكدمتــن بالســاق األميــن وكدمــه‬\n‫بالســاق األيســر وجــرح عميــق صغيــر ‪1 2/1‬ســم خلــف الكعــب األيســر‬\n‫جــرح بســيط بالشــفة الســفلية ومــدة الشــفاء أســبوعني مــا لــم حتــدث‬\n‫مضاعفــات) كمــا جــرى ســؤال املدعــي وكالــة هــل يوجــد لديــه زيــادة‬\n‫بينــة فقــال توجــد لــدي زيــادة بينــة وأطلــب الرجــوع إلــى املعاملــة هكــذا‬\n‫أجــاب ثــم جــرى الرجــوع إلــى املعاملــة فوجــدت علــى لفــة رقــم (‪ )1‬تقريــر‬\n‫األحــوال األمنيــة ص (‪ )11‬محضــر اســتجواب املدعــى عليــه املتضمــن‬\n‫إقــراره بأنــه قــام بســحبها مــن رأســها فقــط كمــا وجــدت علــى لفــه رقــم‬\n‫(‪ )37-31‬تقريــر حالــة أســرية صــادر مــن مركــز التنميــة األســرية حيــث‬\n‫وجــدت علــى لفــه رقــم (‪ )35‬أن الــزوج اعتــرف بشــد شــعرها وتكســير‬\n‫جوالهــا وبعــرض ذلــك علــى املدعــى عليــه قــال صحيــح أننــي ســحبتها مــن‬\n‫رأســها وقمــت بشــد شــعرها وتكســير جوالهــا لكــن لــم أصبهــا بــأي‬\n‫إصابــة هكــذا أجــاب ثــم طلبــت مــن املدعــي وكالــة إحضــار املدعيــة‬\n‫أصالــة ولــذا رفعــت اجللســة ويف يــوم الســبت ‪1433/07/05‬ه ـ الســاعة‬\n‫الثانيــة عشــرة افتتحــت اجللســة وفيهــا حضــرت املدعية‪........‬ســعودية‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬املعــرف بهــا مــن قبــل وكيلها‬\n\n\n                                                                                     ‫‪78‬‬\n\f     ‫والداهــا ‪........‬كمــا حضــر املدعــى عليــه وبعــد التأمــل يف الدعــوى ومبــا‬\n     ‫أن اليمــن تشــرع يف جانــب أقــوى املتداعيــن كمــا ذكــر ذلــك الفقهــاء‬\n     ‫لــذا جــرى عــرض اليمــن علــى املدعيــة فاســتعدت باحللــف فأذنــت لهــا‬\n     ‫فحلفــت قائلــة ( واهلل العلــي العظيــم عالــم الغيــب والشــهادة أن زوجــي‬\n     ‫املدعــى عليــه ‪........‬قــام بضــرب وجهــي وشــد شــعر رأســي وضربــي مــع‬\n     ‫ذراعــي وســاقي ممــا أدى إلــى حــدوث اإلصابــة التــي حلقــت بــي ) هكــذا‬\n     ‫حلفــت فبنــاء علــى مــا تقــدم مــن دعــوى املدعيــة وإجابــة املدعــى عليــه‬\n     ‫وإقــراره بشــد شــعر املدعيــة وســحب رأســها وإنــكار حــدوث اإلصابــة‬\n     ‫بهــا وبنــاء علــى التقريــر الطبــي ومبــا أن اليمــن تشــرع يف جانــب أقــوى‬\n     ‫املتداعيــن وجانــب املدعيــة تقــوى بالتقريــر الطبــي ومبــا أن املدعيــة‬\n     ‫حلفــت اليمــن كمــا طلبــت منهــا ومبــا أن املدعــى عليــه جتــاوز حــد‬\n     ‫التأديــب ممــا أدى إلــى إصابــة املدعــى عليهــا وهــذا الفعــل موجــب‬\n     ‫للتعزيــر فقــد ورد يف شــرح منتهــى اإلرادات (‪ )254/10‬مــا نصــه‪( :‬ولــه‬\n     ‫‪ -‬أي‪ :‬الــزوج واألب والســيد ‪ -‬تأديــب زوجــة وتأديــب ولــد لــو كان الولــد‬\n     ‫مكلفـ ًا مزوجـ ًا بضــرب غيــر مبــرح ) كمــا ورد يف كشــاف القنــاع عــن‬\n     ‫مــن اإلقنــاع (‪ )463/19‬مــا نصــه‪( :‬ويحــرم ضــرب الوجــه ويف اآلدمــي‬\n     ‫أشــد ألنــه أعظــم حرمــة) لــذا كلــه فقــد ثبــت لــدي قيــام املدعــى عليــه‬\n     ‫بضــرب زوجتــه املدعيــة ممــا ادى إلــى حــدوث اإلصابــة التــي حلقــت بهــا‬\n     ‫يف التقريــر وقــررت تعزيــر املدعــى عليــه بالســجن ملــدة شــهر حتتســب‬\n     ‫منهــا مــدة إيقافــه وجلــده خمســن جلــدة تعزيــر ًا دفعــة واحــدة وبعــرض‬\n     ‫احلكــم علــى الطرفــن قــررا االعتــراض علــى احلكــم وطلبــا االســتئناف‬\n     ‫بالئحــة يقدمانهــا فأفهمتهمــا بأنــه ســوف يجــري بعــد قليــل تســليمهما‬\n     ‫نســخة مــن احلكــم ليقدمــا اعتراضهمــا خــال ثالثــن يوم ـ ًا مــن اآلن‬\n\n\n‫‪79‬‬\n\f‫يكــون حقهمــا يف االســتئناف بعــد مضــي هــذه املــدة ســاقط ًا ففهمــا‬\n‫ذلــك وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر يف‬\n                                                                 ‫‪1433/07/05‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت ‪1434/03/28‬ه ـ الســاعة‬\n‫العاشــرة إال ربــع افتتحــت اجللســة وفيهــا وردتنــا املعاملــة مــن محكمــة‬\n‫االســتئناف باملنطقــة الشــرقية وبرفقهــا القــرار الصــادر مــن الدائــرة‬\n‫اجلزائيــة الثانيــة برقــم ‪34165875‬يف ‪1434/03/18‬ه ـ املتضمــن‬\n‫املصادقــة علــى احلكــم وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                                            ‫محمــد ‪ .‬حــرر يف ‪1434/03/28‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/34/521772‬ج‪ 2‬وتاريــخ ‪1434/3/1‬ه ـ الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام املكلــف برقــم‬\n‫‪ 33/2039747‬وتاريــخ ‪1434/2/30‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ ‪......../‬املســجل برقــم ‪33327938‬‬\n‫وتاريــخ ‪1433/7/5‬ه ـ اخلــاص بدعوى‪......../‬ضــد‪......../‬يف قضيــة عنــف‬\n‫ضــد املــرأة وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه والالئحتــن االعتراضيتــن‬\n‫وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه علــى قرارنــا‬\n‫رقــم ‪/33407761‬ج‪/2‬ب وتاريــخ ‪1433/9/11‬ه ـ قررنــا املصادقــة علــى‬\n‫احلكــم بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمد‬\n                                ‫وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/3/18‬ه ـ‬\n\n\n\n                                                                                         ‫‪80‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":75,"source_page_end":80,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d2dc3422a4f75f181baeaacabd8afe8de8eef13efaeda0931660f5c6b3dd9422","normalized_text_hash":"4f02fcf03f1f185c8a9bf3a0e01cf17bed185e7882b1c0bb7cb3da4187843016","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p75-33327938"},{"id":"32dad764-2b14-59f1-a2ad-968c9a952242","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء-ضرب -شرب مسكر -رجوع عن إقرار حتقيق ا -احلدود تدرأ بالشبهات -التعزير بالسجن واجللد وأخذ التعهد.","document_number":"3416887","case_number":"33254614","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/19","year":"1434","subject":"اعتداء-ضرب -شرب مسكر -رجوع عن إقرار حتقيق ا -احلدود تدرأ بالشبهات -التعزير بالسجن واجللد وأخذ التعهد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 3416887 :‬تاريخه‪1434/1/19 :‬هـ‬\n                        ‫رقم الدعوى‪33254614:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34235036‬تاريخه‪1434/6/10 :‬هـ‬\n\n\n\n     ‫اعتداء‪-‬ضــرب ‪ -‬شــرب مســكر ‪ -‬رجــوع عــن إقــرار حتقيق ـ ًا ‪ -‬احلــدود‬\n               ‫تــدرأ بالشــبهات ‪-‬التعزيــر بالســجن واجللــد وأخــذ التعهــد‪.‬‬\n\n\n\n\n     ‫‪-1‬قــول اهلل تعالــى‪« :‬وتعاونــوا علــى البــر والتقــوى وال تعاونــوا علــى‬\n                                                             ‫اإلثــم والعــدوان»‪.‬‬\n     ‫‪-2‬عــن ابــن عبــاس ‪-‬رضــي اهلل عنهمــا‪ -‬قــال‪ :‬قــال رســول اهلل صلــى اهلل‬\n                ‫عليــه وســلم‪« :‬ادرؤوا احلــدود بالشــبهات» أخرجــه ابــن عــدي‪.‬‬\n     ‫‪-3‬عــن ابــن عمــر ‪-‬رضــي اهلل عنهمــا‪ -‬عــن النبــي صلــى اهلل عليــه وســلم‬\n                 ‫قــال‪« :‬كل مســكر خمــر وكل خمــر حــرام» أخرجــه مســلم‪.‬‬\n\n\n\n\n     ‫جــرى توجيــه االتهــام مــن االدعــاء العــام للمدعــى عليهمــا أحدهمــا‬\n     ‫وهــو األول لــم يحضــر كونــه مطلــق الســراح باالجتمــاع علــى مفســدة‬\n     ‫شــرب املســكر وتوجيــه االتهــام للثانــي بشــرب املســكر وطلــب إثبــات‬\n     ‫مــا أســند إليهمــا وإيقــاع العقوبــة التعزيريــة لهمــا وإقامــة حــد املســكر‬\n     ‫علــى الثانــي حيــث قبــض عليهمــا علــى إثــر مضاربــة فلوحــظ انبعــاث‬\n     ‫رائحــة املســكر مــن جوفهمــا ‪ ،‬أفــاد املدعــى عليــه الثانــي أن إقــراره‬\n     ‫انتــزع منــه بالقــوة وألن احلــدود تــدرأ بالشــبهات إرتــأت احملكمــة عــدم‬\n\n‫‪81‬‬\n\f‫ـاء عليــه قــررت احملكمــة احلكــم علــى‬     ‫إدانــة املدعــى عليــه الثانــي وبنـ ً‬\n‫املدعــى عليــه الثانــي للشــبهة مبــا يلــي‪ :‬أوال‪ /‬الســجن ملــدة أســبوع يحســب‬\n‫منهــا الفتــرة التــي أمضاهــا يف الســجن ألجــل هــذه القضيــة وجلــده‬\n‫ثالثــون جلــدة دفعــة واحــدة للشــبهة يف اجتماعــه علــى مفســدة‪ .‬ثانيــا‪/‬‬\n‫جلــده ســبعون جلــدة دفعــة واحــدة وأخــذ التعهــد الشــديد بلــزوم طريــق‬\n‫االســتقامة والبعــد عــن احملرمــات وأال يعــود ملثــل مــا بــدر منــه وذلــك‬\n‫للشــبهة يف شــربه املســكر ويكــون بــن اجللــد وســابقه مــدة ال تقــل عــن‬\n‫خمســة عشــر يوما‪،‬جــرى تأجيــل النظــر يف الدعــوى املقامــة علــى املدعى‬\n‫عليــه األول حلــن إحضاره‪،‬بعــرض احلكــم علــى الطرفــن قــرر املدعــى‬\n‫عليــه القناعــة بينمــا قــرر املدعــي العــام االعتــراض طالبــا متكينــه مــن‬\n‫تقــدمي الئحــة اعتراضيــة فأفهــم بتعليمــات االســتئناف‪ ،‬صــدق احلكــم‬\n                                                     ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــد هــو بعــد فلــدي أنــا ‪...........‬القاضــي يف احملكمة اجلزائية‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪ .....‬وتاريــخ‬\n‫‪1433/04/12‬ه ــاملقيدة باحملكمــة برقــم وتاريــخ ‪1433/04/10‬ه ـ‬\n‫ففــي يــوم الثالثــاء املوافق‪1433/05/25‬ه ـ افتتحــت اجللســة الســاعة ‪24‬‬\n‫‪ 11 :‬وفيهــا حضــر املدعــي العــام ‪...........‬نيابــة عــن املدعــي العــام مبوجــب‬\n‫خطــاب التعميــد رقــم ‪...........‬وتاريــخ ‪1432/08/15‬ه ـ وادعــى علــى‬\n‫ال مــن ‪ )21( ........... -1‬عام ـ ًا ســعودي اجلنســية ســجل مدنــي رقــم‬      ‫ك ً‬\n‫(‪ )...........‬مفــرج عنــه بالكفالــة احلضوريــة ‪ )23(........... -2‬ســعودي‬\n\n                                                                                        ‫‪82‬‬\n\f     ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )...........‬مفــرج عنــه بضمــان مقــر‬\n     ‫ا بدعــواه أنــه بتاريــخ ‪1431/12/14‬ه ـ قبــض علــى املدعــى‬               ‫عملــه قائ ـ ً‬\n     ‫عليهمــا األول والثانــي إثــر قضيــة مضاربــة وباستشــمام املدعــى عليــه‬\n     ‫الثانــي اتضــح انبعــاث رائحــة املســكر مــن جوفــه وباســتجواب املدعــى‬\n     ‫عليــه األول أفــاد أن املدعــى عليــه األول واملتهــم ‪ ...........‬واملتهــم ‪...........‬‬\n     ‫كانــوا يف حالــة ســكر بداخــل الشــقة (فــرزت بحقهمــا أوراق مســتقلة‬\n     ‫حملاكمتهمــا مبقــر إقامتهمــا يف قضيــة شــرب املســكر كمــا فصلــت‬\n     ‫أوراق مســتقلة لقضيــة املضاربــة) وباســتجواب املدعــى عليــه الثانــي أفــاد‬\n     ‫أنــه حضــر إلــى الشــقة ووجــد فيهــا املدعــى عليــه األول واملتهــم ‪...........‬‬\n     ‫واملتهــم ‪...........‬يتناولــون املســكر وشــرب معهــم املســكر وقــد انتهــى‬\n     ‫التحقيــق إلــى توجيــه االتهــام إلى املدعى عليهما األول والثاني باالجتماع‬\n     ‫علــى مفســدة الشــرب وشــرب الثانــي للمســكر وذلــك لألدلــة والقرائــن‬\n     ‫التاليــة‪ :‬مــا جــاء بأقــوال املدعــى عليهمــا ص ‪ 10‬والثانــي ص ‪ 13‬مــن‬\n     ‫دفتــر التحقيــق لفــة (‪ )13.7‬ومــا جــاء مبحضــر االستشــمام ص ‪ 12‬مــن‬\n     ‫دفتــر التحقيــق لفــة (‪ )13‬وبالبحــث عــن ســوابقهما لــم يعثــر لهمــا علــى‬\n     ‫ســوابق مســجلة وحيــث إن مــا أقــدم عليــه املدعــى عليهمــا وهمــا بكامــل‬\n     ‫أهليتهمــا املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا اطلــب‬\n     ‫إثبــات إدانتهمــا مبــا اســند إليهمــا واحلكــم علــى املدعــى عليــه الثانــي‬\n     ‫بحــد املســكر واحلكــم عليهمــا بعقوبــة تعزيريــة لقــاء بقيــة مــا أســند‬\n     ‫إليهمــا وأســألهما اجلــواب ويف هــذه اجللســة حضــر املدعــى عليــه الثانــي‬\n     ‫‪...........‬ولــم يحضــر املدعــى عليــه األول ‪...........‬كونــه مطلــق ســراح‬\n     ‫وســيتم النظــر يف شــأنه حــن حضــوره وبســؤال املدعــى عليــه الثانــي‬\n     ‫‪ ...........‬عــن دعــوى املدعــي العــام قــال مــا ذكــره املدعــي العــام مــن أنــه‬\n\n\n‫‪83‬‬\n\f‫قبــض علينــا بتاريــخ ‪1431/12/14‬ه ـ فصحيــح وأنــا لــم أقــم باملضاربــة‬\n‫ولــم أقــم بشــرب املســكر معهــم وكنــت معهــم بالشــقة وبحمــد اهلل ال‬\n‫توجــد علــي أي ســوابق مســجلة هكــذا أجــاب وبســؤال املدعــي العــام‬\n‫عــن بينتــه قــال لــدي بينــة اطلــب إمهالــي إلحضارهــا لــذا رفعــت اجللســة ‪.‬‬\n‫ويف اجللســة املقــررة يــوم الســبت املوافــق‪ 1433/06/14‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 11: 15‬لســماع دعــوى املدعــي العام ضــد‪ ...........‬وحضر‬\n‫املدعــي العــام وحضــر املدعــى عليــه وبســؤال املدعــي العــام عــن بينتــه‬\n‫قــال لــم حتضــر وأطلــب إمهالــي إلحضارهــا لــذا رفعــت اجللســة ‪ .‬ويف‬\n‫اجللســة املقــررة يــوم الســبت املوافــق‪ 1433/07/05‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 12 : 15‬لســماع دعوى املدعي العام ضد‪...........‬وحضر املدعي‬\n‫العــام وحضــر املدعــى عليــه وبســؤال املدعــي العــام عــن بينتــه قــال لــم‬\n‫حتضــر وأطلــب إمهالــي إلحضارهــا لــذا رفعــت اجللســة ‪ .‬ويف اجللســة‬\n‫املقــررة يــوم الســبت املوافــق ‪ 1433/08/03‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪01 : 15‬لســماع دعــوى املدعــي العــام ضد‪...........‬وحضــر املدعــي العــام‬\n‫ولــم يحضــر املدعــى عليــه وبســؤال املدعــي العــام عــن بينتــه قــال لــم‬\n‫حتضــر وأطلــب إمهالــي إلحضارهــا وبعــد انتهــاء اجللســة يف متــام الســاعة‬\n‫الواحــدة ظهــر ًا حضــر املدعــى عليــه وجــرى إفهامــه بااللتــزام باحلضــور‬\n‫يف املوعــد احملــدد وذلــك يف يــوم االثنــن املوافــق ‪1433/08/12‬ه ـ‬\n‫الســاعة ‪ 10 : 15‬وأقفلت هذه اجللســة يف متام الســاعة الواحدة والنصف‬\n‫‪ .‬ويف اجللســة املقررة يوماإلثنيناملوافق‪ 1434/01/19‬هـ افتتحت اجللســة‬\n‫الســاعة ‪ 10 :00‬لســماع دعــوى املدعــي العــام ضــد‪ ...........‬و‪.........../‬‬\n‫وفيهــا حضراملدعــي العــام وجــري إحضــار املدعــى عليــه وبســؤال املدعي‬\n‫العــام عــن بينتــه التــي أســتمهل إلحضارهــا اجــاب قائــا لقــد طلبــت‬\n\n\n                                                                                     ‫‪84‬‬\n\f     ‫البينــة ولكنهــا لــم حتضــر أطلــب الرجــوع إلــي أوراق املعاملــة والنظــر‬\n     ‫مبــا فيهــا مــن أدلــة وقرائــن هكــذا أجــاب هــذا وقــد جــري اطالعــي‬\n     ‫علــى أوراق املعاملــة وعلــى طلبــات إحضــار البينــة املرفقــة باملعاملــة‬\n     ‫فوجدتهــا كمــا يلــي الطلــب األول برقــم ‪...........‬وتاريــخ ‪1433/6/2‬ه ـ‬\n     ‫للحضــور يف يــوم الســبت املوافــق ‪1433/6/14‬ه ـ والطلــب الثانــي‬\n     ‫برقم‪...........‬وتاريــخ ‪1433/10/24‬ه ـ للحضــور يف يــوم األثنــن املوافــق‬\n     ‫‪1433/11/8‬ه ـ والطلــب الثالــث برقــم ه ـ م م ‪ 49/2/‬وتاريــخ‬\n     ‫‪1433/1/6‬ه ـ للحضــور يف يــوم األثنــن املوافــق ‪1433/1/19‬ه ــوحيث‬\n     ‫جــرى إمهــال املدعــي العــام إلحضــار بينتــه مــرات ولكنهــا لــم حتضــر‬\n     ‫فقــد قــررت الســير يف نظــر القضيــة هــذا وقــد اطلعــت علــى إقــرار‬\n     ‫املدعــى عليــه الثانــي خالــد املرفــق باملعاملــة باللفــة (‪ )13‬صحيفــة رقــم‬\n     ‫(‪ )15‬واملتضمــن مــا نصــه أقــر وأعتــرف انــا‪........... /‬ســعودي اجلنســية‬\n     ‫وأنــا بكامــل قــواي العقليــة املعتبــره شــرعا بــدون إكــراه وال إجبــار مــن‬\n     ‫أحــد باننــي حضــرت إلــي الشــقة ووجــدت بهــا كال مــن ‪........... /1‬‬\n     ‫ســعودي اجلنســية ‪........... /2‬ســعودي اجلنســية ‪ ........... /3‬ســعودي‬\n     ‫اجلنســية وكانــوا جالســن بالغرفــة يتناولــون مــادة العــرق املســكر‬\n     ‫وقمــت بتنــاول املســكر معهــم يف الشــقة وقــد ذهبــت إلــي أحــد الغــرف‬\n     ‫وبعدهــا منــت وال أعلــم ماحــدث بعــد ذلــك وهــذا إقــراري وعليــه أوقــع‬\n     ‫كمــا جــري منــي الرجــوع إلــي أقــوال املدعــى عليــه املرفــق باملعاملــة لفــة‬\n     ‫رقــم (‪ )13‬صحيفــة رقــم (‪ )14/13‬واملتضمنــة ســؤال املدعــى عليــه وضــح‬\n     ‫لنــا مفصــا عــن مــا حــدث بينكــم بالشــقة التــي كنتــم جالســن بهــا ج‪/‬‬\n     ‫لقــد حضــرت إلــى الشــقة يف الســاعة الثانيــة عشــر ليــا مــن يــوم اجلمعــة‬\n     ‫‪1431/12/14‬ه ـ وعنــد وصولــي إلــى الشــقة وجــدت جالــس بالشــقة‬\n\n\n‫‪85‬‬\n\f‫كال مــن ‪.........../3.........../2........... /1‬وكانــوا جالســن بغرفــة‬\n‫وكانــوا يتناولــون املســكر وقمــت بشــرب املســكر معهــم ثــم ذهبــت‬\n‫إلــي الغرفــة ومنــت وال أعلــم مــا حــدث بعــد ذلــك س‪ /‬ماهي مادة املســكر‬\n‫التــي قمــت بتناولهــا ج‪ /‬مــادة العــرق املســكر يف قــارورة مــاء صحــه س‪/‬‬\n‫مــن الــذي احضــر املســكر ج‪ /‬ال أعلــم وجدتــه يف الشــقة كمــا جــري‬\n‫اطالعــي علــى محضــر االستشــمام املرفــق باملعاملــة لفــه رقــم (‪)13‬‬\n‫صحيفــة رقــم (‪ )12‬مــن دفتــر التحقيــق واملتضمنــه مــا نصــه وبحضورنــا‬\n‫نحــن املوقعــن ادنــاه بالتاريــخ أعــاه جــري إشــمام كال مــن ‪.........../1‬‬\n‫ســعودي ‪.........../2‬ســعودي ‪.........../3‬ســعودي وأتضــح انبعــاث رائحــه‬\n‫املســكر تفــوح مــن أفواههــم وجــري تدويــن احملضــر حفظــا للواقعــة‬\n‫وعليــه جــري التوقيــع وبالبحــث عــن صحيفــة ســوابق للمدعــى عليــه‬\n‫باملعاملــة لــم أجــد شــيئا وبســؤال املدعــى عليــه عــن إقــراره يف دفتــر‬\n‫التحقيــق وأقوالــه أجــاب قائــا لقــد ضربــت حتــى أوقــع علــى ذلــك‬\n‫وبســؤاله هــل لديــه بينــه علــى ذلــك قــال ال هكــذا أجــاب فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوي واإلجابــة وإلنــكار املدعــى عليــه للدعــوي يف مجلــس‬\n‫احلكــم وإقــراره حتقيقــا بذلــك ولعجــز املدعــي العــام عــن إحضــار بينتــه‬\n‫ومبــا أن احلــدود تــدرأ بالشــبهات لقــول النبــي صلــى اهلل عليــه وســلم‬\n‫(ادرؤوا احلــدود بالشــبهات ) وإلنــكار املدعــى عليــه ملــا نســب إليــه بعــد‬\n‫إقــراره حتقيقــا شــبهة يــدرأ بهــا احلــد وملــا جــاء يف محضــر القبــض‬\n‫ومحضــر االستشــمام وهــذه قرائــن تعضــد دعــوى املدعــي العــام فلمــا‬\n‫ســبق لــم يثبــت لــدي إدانــة املدعــى عليــه الثانــي‪ ...........‬مبــا نســب إليــه يف‬\n‫الدعــوي يف اجتماعــه علــى مفســدة وشــربه للمســكر مــع توجيه الشــبهة‬\n‫القويةلــه بذلــك ومبــا ان تعاطــي املســكر واالجتمــاع والتعــاون علــى‬\n\n\n                                                                                            ‫‪86‬‬\n\f     ‫شــربه فعــل محــرم يســتحق فاعلــه العقــاب عليــه واهلل تعالــى يقول(يــا‬\n     ‫أيهــا الذيــن ءامنــوا إمنــا اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن‬\n     ‫عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) ولقولــه صلــى اهلل عليــه‬\n     ‫وســلم ( كل مســكر خمر وكل خمر حرام)فلما ســبق فقد حكمت‬\n     ‫علــى املدعــى عليــه للشــبهة مبــا يلــي أوال‪ /‬يســجن املدعــى عليــه الثانــي‬\n     ‫‪...........‬ملــدة اســبوع يحتســب منهــا مــا امضــاه موقوفــا يف هــذه القضيــة‬\n     ‫ويجلــد ثالثــون جلــدة دفعــه واحــده وذلــك لقــاء االشــتباه لــه الجتماعــه‬\n     ‫علــى مفســدة ‪ .‬ثانيــا‪ /‬يجلــد املدعــى عليــه الثانــي ‪...........‬ســبعون جلــدة‬\n     ‫دفعــه واحــدة ويؤخــذ عليــه التعهــد الشــديد بلــزوم طريــق االســتقامة‬\n     ‫والبعــد عــن احملرمــات وأال يعــود ملثــل مــا بــدر منــه وذلــك لقــاء االشــتباه‬\n     ‫بــه لشــربه املســكر ويكــون بــن هــذا اجللــد وســابقه مــدة ال تقــل عــن‬\n     ‫خمســة عشــر يومــا علمــا بــأن املدعــى عليــه األول‪ ...........‬ســيتم النظــر يف‬\n     ‫شــأنه حــال حضــوره وبعــرض احلكــم علــى الطــريف نقــرر املدعــي العــام‬\n     ‫معارضتــه علــى احلكــم مــع تقــدمي الئحــة اعتراضيــة عليــه فأفهمتــه‬\n     ‫باحلضــور يف يــوم األربعــاء املوافــق ‪1434/1/21‬ه ـ الســتالم نســخه مــن‬\n     ‫قــرار احلكــم لتقــدمي اعتراضــه عليــه خــال مــدة ثالثــن يــوم اعتبــارا مــن‬\n     ‫التاريــخ املشــار إليــه فــإن مضــت املــدة ولــم يســتلم نســخه مــن احلكــم‬\n     ‫أولــم يقــدم اعتراضــه عليــه خاللهــا فــإن حقــه يف تقــدمي الئحــة االعتراض‬\n     ‫يكــون ســاقطا كمــا قــرر املدعــى عليــه قناعتــه بــه وجــري النطــق‬\n     ‫باحلكــم يف األثنــن املوافــق ‪1434/1/19/‬ه ـ الســاعة ‪ 10 : 30‬وبــه‬\n     ‫أقفلــت اجللســة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد والــه‬\n     ‫وصحبــه اجمعــن حــرر يف ‪1434/01/19‬ه ــاحلمد هلل وحــده والصــاة‬\n     ‫والســام علــى مــن ال نبــي بعــده وبعــد فلــدي أن ‪...........‬القاضــي‬\n\n\n‫‪87‬‬\n\f‫باحملكمــة اجلزائيــة بجــدة ففــي يــوم االثنــن املوافــق ‪1434/01/26‬ه ـ‬\n‫وبعــد ورود الالئحــة االعتراضيــة مــن املدعــي العــام املتعلقــة بدعــواه ضــد‬\n‫‪...........‬و‪ ...........‬املكونــة مــن ثــاث صفحــات وبعــد االطــاع عليهــا لــم‬\n‫أجــد فيهــا مــا يؤثــر علــى مــا حكمــت بــه وقــررت رفــع املعاملــة مــع القرار‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة حملكمــة االســتئناف مبكــة‬\n‫املكرمــة لتدقيــق احلكــم كاملتبــع وعليــه حصــل التوقيــع وبــاهلل‬\n‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آله وصحبــه أجمعني‬\n‫حــرر يف ‪1434/01/26‬ه ــاحلمد هلل وحــده والصــاة والســام علــى مــن‬\n‫ال نبــي بعــده وبعــد ‪ :‬فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة‬\n‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة‬\n‫الــواردة إلينــا شــفع خطــاب فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة‬\n‫جــدة رقــم ‪ 34/555032‬وتاريــخ ‪1434/5/20‬ه ــاملشتملةعلى القــرار‬\n‫الصــادر مــن فضيلــة الشــيخ‪........... /‬القاضــي باحملكمــة اجلزائيــة بجــدة‬\n‫املــؤرخ يف ‪1434/1/19‬ه ــواملسجل بعــدد ‪ ،3416887‬املتضمــن دعــوى‬\n‫املدعــي العــام ضــد‪........... /‬ورفيقــه املتهمــن باالجتمــاع علــى مفســدة‬\n‫الشــرب وشــرب الثانــي للمســكر احملكــوم فيــه مبــا ّدون بباطــن القــرار‬\n‫وبدراســة القــرار وصــورة ضبــط والالئحــة االعتراضيــة تقــررت املوافقــة‬\n‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                   ‫وصحبه وسلم ‪.‬‬\n\n\n\n\n                                                                                         ‫‪88‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":81,"source_page_end":88,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4b4524fc1107650e9e88c2681c0e6886728afd296662af12c5763b3aa1bbf600","normalized_text_hash":"ee924c0b1f3aee1d254951bb79e19c16dc097b4ad31886bbfd8b548b94f076eb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p81-3416887"},{"id":"51f3784e-93ef-5edb-9940-f07ce8bd5719","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -مطاردة بسيارة وتسبب يف إصابة -عدم قبول شهادة من عرف بعصبية وإفراط يف حمية -تقرير طبي -سجن -جلد -","document_number":"33263784","case_number":"33261681","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بشروره بشأن استخالفهم يف سماع شهادة من حضر الواقعة فوردنا كتاب رئيس المحكمة العامة بشروره ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/23","year":"1434","subject":"اعتداء -مطاردة بسيارة وتسبب يف إصابة -عدم قبول شهادة من عرف بعصبية وإفراط يف حمية -تقرير طبي -سجن -جلد -","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 33263784 :‬تاريخه‪1433/11/23:‬هـ‬\n                         ‫رقم الدعوى‪33261681:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3421337‬تاريخه‪1434/1/25 :‬هـ‬\n\n\n\n     ‫اعتــداء ‪ -‬مطــاردة بســيارة وتســبب يف إصابــة ‪ -‬عــدم قبــول شــهادة مــن‬\n     ‫عــرف بعصبيــة وإفــراط يف حميــة ‪ -‬تقريــر طبــي ‪ -‬ســجن ‪ -‬جلــد ‪-‬‬\n                                                                         ‫تهمــة‪.‬‬\n\n\n\n     ‫‪-‬نــص أهــل العلــم أن ال تقبــل شــهادة مــن عــرف بعصبيــة وإفــراط يف‬\n     ‫حميــة كتعصــب قبيلــة علــى قبيلــة وإن ملتبلــغ رتبــة العــداوة (الــروض‬\n                                                                   ‫املربــع ‪.)605/7‬‬\n\n\n\n\n     ‫اتهــام املدعــي العــام للمدعــى عليــه بقيامــه باالعتــداء بســيارته علــى‬\n     ‫مواطنني يســيران على أقدامهما مبطاردتهما بقصد إصابتهما وتســببه‬\n     ‫يف إصابــة أحدهمــا عمــد ًا والهــروب مــن املوقــع يطلــب إثبــات إدانتــه مبــا‬\n     ‫أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة والنظــر يف عقوبــات بديلة عن‬\n     ‫الســجن اســتناد ًا للفقــرة اخلامســة م قــرار مجلــس الــوزراء رقــم (‪)169‬‬\n     ‫وتاريــخ ‪ ،1429/6/19‬أقــر املدعــى عليــه بالصــدم خطــأ وإنــكاره‬\n     ‫العمدية‪،‬احضــر املدعــي العــام شــهود ًا تضمنــت شــهادتهم صحــة‬\n     ‫الدعــوى ‪،‬أجــاب املدعــى عليــه عــن الشــهادة بأنهــا ليســت صحيحــة وهــم‬\n     ‫أبنــاء قبيلــة واحــدة ‪،‬حضــر املدعــي يف احلــق اخلــاص وكالــة عــن املجنــي‬\n\n‫‪89‬‬\n\f‫عليــه الثانــي وقــرر إن املدعــى عليــه قــام بصــدم موكلــه عمــدا ويطلــب‬\n‫مجازاتــه ‪،‬أنكــر املدعــى عليــه العمديــة وطلــب مــن املدعــي البينــة‬\n‫وذكــر أن هــا بينــة لــه و ال يرغــب ميــن املدعــى عليــه ‪،‬توجــه الشــبهة‬\n‫واحلكــم مبــا يلــي ‪،‬إيقافــه ملــدة شــهرين‪ ،‬بجلــده ثمانــن جلــدة مفرقــة‬\n‫علــى دفعتــن كل دفعــة أربعــون جلــدة وهــذا احلكــم للحــق العــام‪ ،‬قــرر‬\n‫املدعــي العــام االعتــراض وطلــب االســتئناف بــدون الئحــة وقــرر املدعــى‬\n‫يف احلــق اخلــاص االعتــراض وطلــب االســتئناف بالئحــة وقــرر املدعــى‬\n              ‫عليــه القناعــة ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة‬\n‫اجلزئيــة بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزئيــة بنجــران برقــم ‪ 33261681‬وتاريــخ ‪1433/04/14‬‬\n‫ه ـ املقيــدة باحملكمــة برقــم ‪ 33704997‬وتاريــخ ‪ 1433/04/14‬ه ـ‬\n‫ففــي يــوم الســبت املوافــق‪ 1433/04/17‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪ 10 : 24‬وفيهــا حضــر املدعــي العام‪.......‬مبوجــب التكليــف الصــادر‬\n‫مــن هيئــة التحقيــق واالدعــاء العــام بنجــران رقــم ه ـ ن ‪11178/2/1‬‬\n‫بتاريــخ ‪1430/12/29‬ه ـ وادعــى علــى احلــدث ‪...... /‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ ).....‬قائــا يف دعــواه عليــه أنــه بتاريــخ‬\n‫‪1433/3/21‬هـ ورد يف احملضر املعد من قبل مدير شــعبة مرور شــرورة‬\n‫ورود بــاغ للعمليــات عــن وجــود حــادث دهــس وهــروب مــن قبــل ســيارة‬\n‫نــوع ‪ ........‬اللــون ‪ .....‬وباالنتقــال للمستشــفى اتضــح وجــود املصــاب ‪/‬‬\n‫‪.......‬بكســر مضاعــف يف رجلــه منــوم باملستشــفى والــذي أفــاد أن املتهــم‬\n\n                                                                                  ‫‪90‬‬\n\f     ‫هــو مــن قــام بصدمــه بالســيارة املشــار إليهــا ‪ .‬ويضبــط إفــادة املصــاب ‪/‬‬\n     ‫‪........‬ذكــر أن املتهــم قــام بصدمــه عمــد ًا بعــد أن حــاول الهــرب حيــث‬\n     ‫كان يســير علــى قدميــه برفقــة زميلــه ‪...... /‬أمــام مدرســة ‪ ............‬بحــي‬\n     ‫‪ ............‬وكان املتهــم يقــود ســيارة نــوع ‪ ..........‬ويحــاول صــدم ‪......‬الــذي‬\n     ‫هــرب ثــم انحرفــت ســيارة املتهــم مــرة أخــرى واجتــه لهمــا ليصدمهمــا‬\n     ‫فتمكــن ‪....‬مــن الهــرب وعنــد محاولــة ‪......‬الهــرب أصابــه املتهــم وصدمــه‬\n     ‫مبقدمــة الســيارة ‪ ......‬وتســبب يف إصابــة رجلــه اليســرى ثــم هــرب املتهــم‬\n     ‫علــى الســيارة املشــار إليهــا ‪ .‬وبضبــط أقوال‪...... /‬أفــاد أنه أثناء خروجهم‬\n     ‫مــن مدرســة ‪ ............‬كان يســير علــى قدميــه برفقــة ‪.... /‬فقــام املتهــم‬\n     ‫بقيــادة الســيارة املشــار إليهــا مبطاردتــه محــاو ًال صدمــه فهــرب منــه ثــم‬\n     ‫عــاد املتهــم مــرة أخــرى وصــدم ‪.......‬ممــا أدى إلــى إصابتــه واحتجــازه بــن‬\n     ‫ســيارة ‪ .....‬وســيارة ‪ ....‬أخــرى وذكــر إن املتهــم يــدرس معهــم يف نفــس‬\n     ‫املدرســة وإن بينهمــا مشــكلة ســابقة قبــل ســنة وانتهــت بالصلــح مــن‬\n     ‫قبــل شــرطة شــرورة واملشــايخ ‪ .‬وباســتجواب احلــدث ‪..... /‬أقــر بقيادتــه‬\n     ‫الســيارة املشــار إليهــا والعائــدة ملكيتهــا جلــده املواطــن ‪....... /‬أثنــاء‬\n     ‫خروجــه مــن مدرســة ‪ ..............‬وتلفــظ عليــه مجموعــة مــن الطــاب وهــم‬\n     ‫كل مــن ‪....../‬و‪......‬و‪ ......‬وحذفــوه باألحذيــة والكتــب ( مت مخاطبــة‬\n     ‫الشــرطة إلكمــال اإلجــراءات األوليــة حيــال دعــواه باخلطــاب رقــم ( ه ـ‬\n     ‫ن ‪ ) 639/3/2‬وتاريــخ ‪1433/3/22‬ه ـ وســيتم إحالتهــم إذا ثبــت االتهــام‬\n     ‫حملكمــة شــرورة العامــة بالقضيــة املفــرزة ) فهــرب منهــم وصــدم ســيارة‬\n     ‫نــوع ‪ ......‬ممــا أدى إلصابــة ‪.....‬فشــاهده وعــرف أنــه مصــاب وهــرب خوفـ ًا‬\n     ‫علــى نفســه ‪ .‬وبســماع شــهادة املواطنــن ‪...... /‬و‪ .......‬أفــادا أنهمــا شــاهدا‬\n     ‫صاحــب ســيارة نــوع ‪ ... .....‬كان يطــارد ‪ .......‬بســرعة عاليــة ليصدمــه‬\n\n\n‫‪91‬‬\n\f‫لكــن ‪...‬هــرب فعــاد صاحــب الســيارة ‪ ....‬مــرة أخــرى بعــد أن أخــذ‬\n‫الــدوران والتوجــه إلــى ‪....‬مــرة أخــرى يريــد صدمــه فتمكــن مــن الهــرب‬\n‫ثــم شــاهد ‪.....‬يحــاول الهــرب فاجتــه إليــه وصدمــه فانحشــرت رجلــه‬\n‫اليســرى بــن مقدمــة الســيارة ‪ ......‬ومؤخــرة ســيارة نــوع ‪ ....‬كانــت واقفــة‬\n‫جانــب الطريــق ثــم هــرب مــن املوقــع ‪ .‬وقــد اثبــت التقريــر الطبــي الصــادر‬\n‫من مستشــفى شــرورة العام برقم ( بدون ) وتاريخ ‪1433/4/5‬هـ إصابة‬\n‫‪....... /‬بكســر يف الركبــة اليســرى وســحجات واســعة االمتــداد علــى‬\n‫الفخــذ األيســر مــع جــروح قطعيــة متعــددة ( ‪ 4‬جــروح ) ومــدة الشــفاء‬\n‫مــن ( ‪ ) 6-3‬أشــهر مــا لــم حتــدث مضاعفــات ‪ .‬وانتهــى التحقيــق لتوجيــه‬\n‫االتهــام للحــدث ‪........ /‬باالعتــداء بســيارته علــى مواطنــن يســيران علــى‬\n‫أقدامهمــا مبطاردتهمــا بقصــد إصابتهمــا وتســببه يف إصابــة أحدهمــا‬\n                                                   ‫عمــد ًا والهــروب مــن املوقــع ‪.‬‬\n                                                 ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n‫‪ -1‬إقــراره املنــوه عنــه واملــدون علــى ص ( ‪ ) 4‬مــن ملــف التحقيــق املرفــق‬\n           ‫رقــم ( ‪ ) 6‬وص ( ‪ ) 4 ، 3‬مــن ملــف التحقيــق املرفــق لفــة ( ‪.) 2‬‬\n‫‪ -2‬شــهادة الشــهود املنــوه عنهــا املدونــة علــى الصفحــات ( ‪ ) 12 ، 11‬مــن‬\n                                               ‫دفتــر التحقيــق املرفــق رقــم ( ‪.) 2‬‬\n‫‪ -3‬مــا جــاء يف إفــادة املصــاب املنــوه عنهــا واملرفقــة لفــة ( ‪ ) 9‬واملدونــة‬\n‫علــى ص ( ‪ ) 7 ، 2‬مــن ملــف التحقيــق املرفــق رقــم ( ‪ ) 1‬وص ( ‪ ) 10‬مــن‬\n                                            ‫ملــف التحقيــق املرفــق رقــم ( ‪. ) 2‬‬\n‫‪ -4‬مــا جــاء يف أقــوال ‪ ............‬املنــوه عنهــا واملدونــة ص ( ‪ ) 9‬مــن ملــف‬\n                                                   ‫التحقيــق املرفــق رقــم ( ‪. ) 2‬‬\n                             ‫‪ -5‬التقرير الطبي املنوه عنه واملرفق لفة ( ‪. ) 6‬‬\n\n\n                                                                                        ‫‪92‬‬\n\f     ‫وحيــث أن مــا أقــدم عليــه املتهــم وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n     ‫فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات إدانتــه مبــا أســند إليــه‬\n     ‫واحلكــم عليــه بعقوبــة تعزيريــة والنظــر يف عقوبــات بديلــة عــن الســجن‬\n     ‫اســتناد ًا للفقــرة اخلامســة مــن قــرار مجلــس الــوزراء رقــم ( ‪ ) 169‬وتاريــخ‬\n                                                                     ‫‪1429/6/19‬هــ‪..‬‬\n     ‫( علم ـ ًا بــأن احلــق اخلــاص مــا زال قائم ـ ًا ) هــذه دعــواي وبعــرض دعــوى‬\n     ‫املدعــي العــام علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي العــام‬\n     ‫يف دعــواه مــن اعتدائــي بالســيارة علــى مواطنــن يســيران علــى أقدامهمــا‬\n     ‫بقصــد إصابتهمــا وتســببي يف إصابــة أحدهمــا عمــدا و الهــروب مــن‬\n     ‫املوقــع هــذا غيــر صحيــح والصحيــح أننــي كنــت خــارج مــن املدرســة‬\n     ‫وركبــت ســيارتي مــن نــوع ‪ ..........‬إنتــاج ‪2006‬م و كان قــد تلفــظ علـ ّـي‬\n     ‫بعــض الطــاب بألفــاظ نابيــة وكانــوا يريدون ضربي فركبت ســيارتي‬\n     ‫وصدمــت أحدهــم مــن دون شــعور ولــم أكــن أتعمــد ذلــك ثــم هربــت مــن‬\n     ‫املوقــع خوفــا علــى نفســي هــذه إجابتــي وبســؤال املدعــي العــام عــن ذلــك‬\n     ‫قــال غيــر صحيــح والصحيــح مــا ذكــرت وبســؤاله عــن مــا لديــه مــن بينــة‬\n     ‫قــال بينتــي مــا جــاء يف أوراق املعاملــة ثــم رفعــت اجللســة لالطــاع عليهــا‬\n     ‫وتأمــل مــا جــاء فيهــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                            ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/04/17‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء املوافــق ‪1433/11/16‬ه ـ فتحت‬\n     ‫اجللســة يف متــام الســاعة احلاديــة عشــر صباحــا وفيهــا حضــر املدعــي‬\n     ‫العــام كمــا حضــر املدعــى عليــه وقــد متــت الكتابــة إلــى احملكمــة‬\n     ‫العامــة بشــروره بشــأن اســتخالفهم يف ســماع شــهادة مــن حضــر الواقعــة‬\n     ‫فوردنــا كتــاب رئيــس احملكمــة العامــة بشــروره برقــم ‪1684/3/916‬‬\n\n\n‫‪93‬‬\n\f‫وتاريــخ ‪1433/10/22‬ه ـ واملتضمــن صــورة مــن الشــهادة واملعدلــة شــرعا‬\n‫واملتضمــن مــا يلــي (وفيهــا حضــر كال مــن ‪......‬ســعودي بالســجل املدنــي‬\n‫رقــم (‪ )........‬و‪ .............‬ســعودي بالســجل املدنــي رقــم (‪ )......‬وبســؤال‬\n‫كل واحــد منهمــا عمــا لديــه مــن شــهادة أجــاب قائــا إننــي شــاهدت‬\n‫املدعــو ‪.......... /‬يســتقل ســيارة نــوع ‪ ..........‬موديــل ‪2006‬م عنــد مدرســة‬\n‫‪ ............‬واجتــه نحــو املدعــو ‪....... /‬يريــد صدمــه بالســيارة فقــام ‪....‬‬\n‫بالهــروب مــن أمــام الســيارة وطلــع علــى الرصيــف فقــام املدعــو ‪......./‬‬\n‫بالــدوران مــرة أخــرى واجتــه نحــو ‪.......‬لكنــه لــم يســتطع اللحــاق بــه‬\n‫فقــام باالجتــاه نحــو املدعــو ‪.......... /‬والــذي كان قائمــا عنــد ركــن‬\n‫املدرســة ومســتندا إلــى ســيارة ‪ ......‬فصدمــه بالســيارة يف رجلــه اليســرى‬\n‫واصطــدم يف الســيارة ‪ .......‬ثــم قــام بعدهــا بالهــروب هــذا مــا لــدي مــن‬\n‫شــهادة وقــد جــرى تعديلهمــا مــن قبــل كال مــن‪.......‬و‪ )...........‬وبعرضهــا‬\n‫علــى املدعــى عليــه احلاضــر يف مجلــس احلكــم أجــاب بقولــه غيــر‬\n‫صحيــح جملــة وتفصيــا وأنــا أطعــن يف الشــهود لكونهــم مــن قبيلــة‬\n‫واحــدة هكــذا أجــاب وقــد حضــر يف هــذه اجللســة ‪.......‬ســعودي بالســجل‬\n‫املدنــي رقــم (‪ )..........‬بصفتــه وكيــا عــن ابنــه‪ ........‬ســعودي بالســجل‬\n‫املدنــي رقــم ‪...........‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل شــروره‬\n‫برقــم ‪ 11‬وتاريــخ ‪1433/7/14‬ه ـ وبســؤاله عــن دعــواه قــال إن املدعــى‬\n‫عليــه يــدرس مــع موكلــي يف مدرســة واحــدة وقــد خرجــا ذات يــوم مــن‬\n‫املدرســة وقــام املدعــى عليــه بالترصــد ملوكلــي بســيارته التــي كان‬\n‫يقودهــا وهــي ‪ ......‬املوصوفــة يف التقريــر الطبــي املرفــق باملعاملــة وأنــا‬\n‫أطلــب مجازاتــه شــرعا لقــاء ذلــك وبعــرض ذلــك علــى املدعــى عليــه قــال‬\n‫مــا ذكــره املدعــي باحلــق اخلــاص يف دعــواه مــن صدمــي لــه عمــدا فهــذا‬\n\n\n                                                                                    ‫‪94‬‬\n\f     ‫غيــر صحيــح فقــد كان مــوكل املدعــي ومــن معــه مــن أبنــاء قبيلتهــم‬\n     ‫يقــوم بحــذف احلجــارة واألحذيــة علــي وقــد هربــت منهــم اتقــاء ألذيتهــم‬\n     ‫فصدمــت موكلــه مــن دون عمــد وحصــل لــه مــا حصــل هــذه إجابتــي ‪.‬‬\n     ‫وبعــرض ذلــك علــى املدعــي وكالــة قــال غيــر صحيــح والصحيــح مــا‬\n     ‫ذكــرت وبســؤاله هــل لديــك بينــة علــى مــا جــاء يف دعــواك قــال ال بينــة‬\n     ‫لــدي فأفهمتــه بأنــه ليــس لــك إال ميينــه فأجــاب بقولــه بانــي ال أريــد ميينــه‬\n     ‫هكــذا أجــاب ثــم جــرى منــا اإلطــاع علــى أقــوال املدعــى عليــه يف‬\n     ‫دفتــر التحقيــق رقــم (‪ )2‬واملــدون علــى الصفحــات (‪ )12.11‬فوجدناهــا‬\n     ‫مطابقــة ملــا جــاء يف إجابتــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n     ‫وحيــث أنكــر املدعــى عليــه صدمــه للمجنــي عليــه ‪............‬متعمــدا‬\n     ‫وبنــاء علــى مــا شــهدت البينــة املعدلــة شــرعا وملــا كان الشــهود هــم مــن‬\n     ‫قبيلــة واحــدة وتطــرق التهمــة لهــم بالتعصــب لبعضهــم البعــض واحتمــال‬\n     ‫وجــود احلميــة بينهــم أضعــف مــن رتبــة تلــك الشــهادة وإثبــات مــا جــاء يف‬\n     ‫الدعــوى مــن خاللهــا وقــد نــص أهــل العلــم أنــه ال تقبــل شــهادة مــن عــرف‬\n     ‫بعصبيــة وإفــراط يف حميــة كتعصــب قبيلــة علــى قبيلــة وإن لــم تبلــغ‬\n     ‫رتبــة العــداوة (الــروض املربــع ‪ )605/7‬وحيــث عجــز املدعــي وكالــة‬\n     ‫باحلــق اخلــاص عــن إثبــات دعــواه شــرعا ورفــض ميــن املدعــى عليــه علــى‬\n     ‫نفــي حصــول العمديــة منــه يف صــدم موكلــه وبنــاء علــى عــدم وجــود‬\n                        ‫ســوابق جنائيــة علــى املدعــى عليــه فقــد قــررت مــا يلــي ‪:‬‬\n     ‫‪ -1‬لــم يثبــت لــدي إدانــة املدعــى عليــه بصدمــه للمجنــي عليــه ‪ ....‬عمــدا‬\n     ‫وقــررت توجيــه التهمــة للمدعــى عليــه بصدمــه للمجنــي عليــه ‪........‬‬\n     ‫بســيارته خطــأ وحكمــت بإيقافــه ملــدة شــهرين وجلــده ثمانــن جلــدة‬\n     ‫مفرقــة علــى دفعتــن كل دفعــة أربعــون جلــدة وهــذا احلكــم للحــق العام‪.‬‬\n\n\n‫‪95‬‬\n\f‫‪ -2‬صــرف النظــر عــن دعــوى املدعــي وكالــة باحلــق اخلــاص وإخــاء‬\n‫ســبيل املدعــى عليــه منهــا وبعــرض احلكــم علــى املدعــي وكالــة‬\n‫باحلــق اخلــاص قــرر اعتراضــه علــى احلكــم بالئحــة فأفهمتــه بتعليمــات‬\n‫االعتــراض واســتالم نســخة مــن إعــام احلكــم لتقــدمي اعتراضــه عليــه‬\n‫خــال مــدة أقصاهــا ثالثــون يومــا وإذا لــم يقــدم اعتراضــه خــال تلــك‬\n‫املــدة يســقط حقــه يف االســتئناف ويكتســب احلكــم القطعيــة كمــا‬\n‫قــرر املدعــى عليــه قناعتــه باحلكــم فيمــا قــرر املدعــي العــام اعتراضــه‬\n‫علــى احلكــم بــدون الئحــة فأمــرت بتنظيــم قــرار يرفــق بــاألوراق ويرســل‬\n‫حملكمــة االســتئناف بعســير للتدقيــق ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/16‬هـ‬\n‫احلمــد اهلل وحــده وبعــد ففــي يــوم األحــد ‪1433/12/26‬ه ـ فتحت اجللســة‬\n‫وقــد جــرى منــا االطــاع علــى الالئحــة االعتراضيــة املقدمــة مــن املدعــي‬\n‫باحلــق اخلــاص واملقيــدة بهــذه احملكمــة برقــم ‪ 332220446‬وبتاريــخ‬\n‫‪1433/12/22‬ه ـ فلــم أجــد مــا يؤثــر علــى مــا حكمــت بــه وبنــاء علــى‬\n‫املــادة (‪ )197‬مــن نظــام اإلجــراءات اجلزائيــة أمــرت برفــع كامــل أوراق‬\n‫املعاملــة إلــى محكمــة االســتئناف بعســير للتدقيــق ‪ .‬وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                              ‫‪ 1433/12/26‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائية بنجــران برقم ‪33704997‬‬\n‫وتاريــخ ‪1434/1/11‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمة الشيخ ‪............ /‬برقم ‪ 33463784‬وتاريخ ‪1433/11/23‬هـ‬\n\n\n                                                                                     ‫‪96‬‬\n\f     ‫اخلــاص بدعــوى املدعــي العــام ضــد احلــدث ‪ ( .......... /‬ســعودي اجلنســية)‬\n     ‫يف قضيــة (إصابــة) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم‬\n     ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه‬\n     ‫والالئحــة االعتراضيــة وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم‪.‬‬\n             ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪97‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":89,"source_page_end":97,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d2d7476946488bacea8f73cddf0498e8420b977255acf3d8ae5735f3ad8fc4e6","normalized_text_hash":"6151eb8d4a9ae4b20b26c3d2c6b0182af269c69b189b9a08dcd1d534e3183641","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p89-33263784"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"184a92d5-c4b9-5da6-ad37-8be281d41fa8","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء -سكب أحد السجناء الزيت الساخن على سجني آخر مما تسبب يف إصابته بحروق -إقرار -وجود سوابق -التعزير بالسجن االنفرادي ملدة ستني يوم ا واجللد .","document_number":"34189860","case_number":"3493295","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة قلوة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/16","year":"1434","subject":"إيذاء -سكب أحد السجناء الزيت الساخن على سجني آخر مما تسبب يف إصابته بحروق -إقرار -وجود سوابق -التعزير بالسجن االنفرادي ملدة ستني يوم ا واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34189860 :‬تاريخه‪1434/4/16 :‬هـ‬\n                     ‫رقم الدعوى‪3493295:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34189860‬تاريخه‪1434/4/16 :‬هـ‬\n\n\n\n‫إيــذاء‪ -‬ســكب أحــد الســجناء الزيــت الســاخن علــى ســجني آخــر ممــا‬\n‫تســبب يف إصابتــه بحــروق ‪ -‬إقــرار ‪ -‬وجــود ســوابق ‪ -‬التعزيــر بالســجن‬\n                                  ‫االنفــرادي ملــدة ســتني يوم ـ ًا واجللــد ‪.‬‬\n\n\n\n\n‫‪-‬عــن أبــي بكــرة رضــي اهلل عنــه أن النبــي صلــى اهلل عليــه وســلم قــال ‪:‬‬\n‫(إن دمائكــم وأموالكــم وأعراضكــم عليكــم حــرام كحرمــة يومكــم هــذا‬\n             ‫يف شــهركم هــذا يف بلدكــم هــذا ) رواه البخــاري ومســلم‬\n\n\n\n‫توجيــه االتهــام للمدعــى عليــه بالقيــام بســكب زيــت ســاخن علــى أحــد‬\n‫الســجناء ممــا تســبب لــه يف اإلصابــة املوصوفــة بالتقريــر الطبــي‪ ،‬وذلــك‬\n‫بعــد وروود خطــاب مــن الســجن املتضمــن بــاغ ســجني لديهــم مفــاده‬\n‫قيــام الســجني املدعــى عليــه بســكب زيــت طعــام علــى يــده والتســبب يف‬\n‫إصابتــه وذلــك بحضــور عــدد مــن الســجناء ‪ ،‬طلــب املدعــي العــام إثبــات‬\n‫إدانتــه مبــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة رادعــة والتشــديد‬\n‫عليــه لقــاء تعــدد ســوابقه وإثــارة الفوضــى داخــل الســجن ‪ ،‬بعــرض‬\n‫دعــوى املدعــي العــام علــى املدعــى عليــه صــادق عليهــا جملــة وتفصيــا‬\n‫ونظــر ًا ألن املدعــى عليــه أقــر مبــا جــاء يف دعــوى املدعــي العــام وألن مــا‬\n\n                                                                                       ‫‪52‬‬\n\f     ‫أقــدم عليــه املدعــى عليــه فيــه مــن اجلــرأة علــى أذيــة النــاس يف أبدانهــم‬\n     ‫مــا يــدل علــى اســتهتاره بأرواحهــم ممــا يقتضــي عقوبتــه مبــا يردعــه‪،‬‬\n     ‫ونظــر ًا لكثــرة ســوابق املدعــى عليــه وعــدم ارتداعــه رغــم احلكــم‬\n     ‫عليــه أكثــر مــن مــرة وألن املدعــى عليــه قــد ســبق وأن أثــار فوضــى‬\n     ‫يف الســجن بســبب مشــاكله مــع الســجناء ومــن أجــل ذلــك جــرى نقلــه‬\n     ‫إلــى ســجن ‪ ........‬جلميــع مــا تقــدم فقــد مت احلكــم بتعزيــر املدعــى عليــه‬\n     ‫لقــاء ذلــك بالســجن يف الســجن االنفــرادي ملــدة ســتني يومـ ًا وجلــده تســعا‬\n     ‫وســبعني جلــدة دفعــة واحــدة وبعــرض ذلــك علــى املدعــي العــام قــرر عــدم‬\n     ‫قناعتــه باحلكــم معتبــر ًا الئحــة الدعــوى الئحتــه االعتراضيــة وبعرضــه‬\n     ‫علــى املدعــى عليــه قــرر قناعتــه باحلكــم‪ ،‬وبعــد رفــع احلكــم حملكمــة‬\n                                                   ‫االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنا‪......‬القاضــي يف احملكمــة العامــة‬\n     ‫مبحافظــة قلــوة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمة العامة مبحافظة قلوة برقم ‪ 3493295‬وتاريخ ‪1434/02/25‬‬\n     ‫هـ املقيدة باحملكمة برقم ‪ 34478656‬وتاريخ ‪ 1434/02/25‬هـ ففي‬\n     ‫يوم الثالثاء املوافق‪ 1434/04/16‬هـ افتتحت اجللســة الســاعة ‪09 : 30‬‬\n     ‫وفيهــا حضــر املدعــي العــام بهيئــة التحقيــق واالدعــاء العــام مبحافظــة‬\n     ‫قلوة‪......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪......‬مدعيــا علــى‬\n     ‫احلاضــر معــه ‪......‬ســعودي بالســجل املدنــي رقــم ‪......‬قائــا املدعــي العــام‬\n     ‫يف دعــواه أنــه بتاريــخ ‪1434/2/2‬ه ـ ورد لشــرطة محافظــة قلوة خطاب‬\n     ‫مــن ســجن قلــوة املتضمــن بــاغ الســجني لديهم‪......‬مفــاده قيــام الســجني‬\n\n‫‪53‬‬\n\f‫املدعــى عليــه أعــاه بســكب زيــت طعــام علــى يــده والتســبب يف إصابتــه‬\n‫وذلــك بحضــور عــدد مــن الســجناء‪ .‬وبســماع شــهادة الســجني‪...... /‬أفــاد‬\n‫بأنــه أثنــاء جلوســه يف العزبــة داخــل الســجن برفقــة ‪......‬حضــر املدعــى‬\n‫عليــه أعــاه وبيــده مقــاة بهــا زيــت مغلــي فقــام بســكبها علــى ‪......‬ممــا‬\n‫تســبب لــه بحــروق‪ .‬وبســماع شــهادة الســجني ‪......‬أفــاد مبثــل مــا أفــاد بــه‬\n‫الســجني‪ ......‬وقــد أثبــت التقريــر اإلصابــي النهائــي رقــم (‪ )......‬وتاريــخ‬\n‫‪1434/2/6‬ه ـ الصــادر مــن مستشــفى قلــوة العــام املتضمــن إصابــة‬\n‫الســجني (‪ )......‬بحريــق مــن الدرجــة األولــى بنســبة ‪ %12‬بأجــزاء متفرقــة‬\n‫مــن اجلســم وحــددت مــدة الشــفاء بعشــرة أيام فقــط‪ .‬وباســتجواب املدعى‬\n‫عليــه ومواجهتــه مبــا نســب إليــه أقــر بقيامــه بســكب زيــت مغلــي علــى‬\n‫املدعــو‪...... /‬وأنــه هــو املتســبب الوحيــد يف تلــك اإلصابــات ولم يشــاركه‬\n‫أحــد يف ذلــك وقــد انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه‬\n‫بالقيــام بســكب زيــت ســاخن علــى املواطــن‪...... /‬ممــا تســبب لــه يف‬\n‫اإلصابــة املوصوفــة بالتقريــر الطبــي املشــار إليــه وذلــك لألدلــة والقرائــن‬\n                                                                           ‫التاليــة ‪-:‬‬\n      ‫‪-1‬اعترافه املدون ص (‪ )14‬من دفتر التحقيق املرفق لفه رقم (‪.)1‬‬\n                ‫‪-2‬التقرير اإلصابي النهائي املنوه عنه املرفق لفة رقم (‪.)13‬‬\n‫‪-3‬مــا جــاء بشــهادة الشــهود املنــوه عنهــا املدونــة ص رقــم (‪ )16‬مــن دفتــر‬\n‫التحقيــق لفــه رقــم (‪ .)1‬وبالبحــث عــن ســوابقه عثــر لــه علــى ســت ســوابق‬\n‫جنائيــة مســجلة عليــه األولــى ســرقة محــات جتاريــة والثانيــة ســرقة‬\n‫أمــوال والثالثــة والرابعــة شــرب املســكرات وســرقة ســيارات واخلامســة‬\n                                       ‫والسادســة اســتعمال املخــدرات وســرقة ‪.‬‬\n‫وحيــث أن مــا قــام بــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n\n\n                                                                                          ‫‪54‬‬\n\f     ‫فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا اطلــب إثبــات إدانتــه مبــا اســند‬\n     ‫إليــه واحلكــم عليــه بعقوبــة تعزيريــة رادعــه والتشــديد عليــه لقــاء تعــدد‬\n     ‫ســوابقه وإثــارة الفوضــى داخــل الســجن ‪( .‬علم ـ ًا بــأن احلــق اخلــاص ال‬\n     ‫زال قائم ـ ًا ) ويف هــذه اجللســة حضــر املدعــى عليــه وبعــرض دعــوى‬\n     ‫املدعــي العــام عليــه أجــاب قائ ـاً‪ :‬مــا ذكــره املدعــي العــام يف دعــواه‬\n     ‫ا وكان ذلــك بســبب انــه يتكلــم علــي‬         ‫كلــه صحيــح جملــة وتفصي ـ ً‬\n     ‫ويســبني ويســب أهلــي فاشــتكيته علــى مديــر الســجن وقلــت لــه تــرى‬\n     ‫اللــي يؤذينــي راح أحرقــه واســتمر املذكــور يف أذيتــي فســكبت عليــه‬\n     ‫الزيــت كمــا جــاء يف دعــوى املدعــي العــام هكــذا أجــاب فبنــاء علــى‬\n     ‫مــا تقــدم مــن الدعــوى واإلجابــة وحيــث اعتــرف املدعــى عليــه مبــا جــاء‬\n     ‫يف دعــوى املدعــي العــام مــن ســكبه للزيــت الســاخن علــى الســجني‬\n     ‫املذكــور وأحــدث بــه اإلصابــة املذكــورة وحيــث أن مــا أقــدم عليــه‬\n     ‫املدعــى عليــه فيــه مــن اجلــرأة علــى أذيــة النــاس يف أبدانهــم مــا يــدل علــى‬\n     ‫اســتهتاره بأرواحهــم ممــا يقتضــي عقوبتــه مبــا يردعــه وقــد روى البخاري‬\n     ‫ومســلم عــن أبــي بكــرة رضــي اهلل عنــه أن النبــي صلــى اهلل عليــه وســلم‬\n     ‫قــال (إن دمائكــم وأموالكــم وأعراضكــم عليكــم حــرام كحرمــة‬\n     ‫يومكــم هــذا يف شــهركم هــذا يف بلدكــم هــذا ) ونظــر ًا لكثــرة‬\n     ‫ســوابق املدعــى عليــه وعــدم ارتداعــه رغــم احلكــم عليــه أكثــر مــن مــرة‬\n     ‫وحيــث أن املدعــى عليــه قــد ســبق وأن أثــار فوضــى يف ســجن قلــوة بســبب‬\n     ‫مشــاكله مــع الســجناء ومــن أجــل ذلــك جــرى نقلــه إلــى ســجن املخــواة‬\n     ‫جلميــع مــا تقــدم فقــد قــررت تعزيــر املدعــى عليــه لقــاء ذلــك بالســجن‬\n     ‫يف الســجن االنفــرادي ملــدة ســتني يوم ـ ًا وجلــده تســعا وســبعني جلــدة‬\n     ‫دفعــة واحــدة وبــه حكمــت وبعــرض ذلــك علــى املدعــي العــام قــرر عــدم‬\n\n\n‫‪55‬‬\n\f‫قناعتــه باحلكــم معتبــر ًا الئحــة الدعــوى الئحتــه االعتراضيــة وبعرضــه‬\n‫علــى املدعــى عليــه قــرر قناعتــه باحلكــم وســيتم رفــع كامــل أوراق‬\n‫املعاملــة حملكمــة اإلســتئناف كاملتبــع وأغلقــت اجللســة ‪10 : 00‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫حــرر يف ‪ 1434/04/16‬ه ـ احلمــد هلل وحــده والصــاة والســام علــى‬\n‫مــن ال نبــي بعــده وبعــد ‪ :‬فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫الثالثــة مبحكمــة االســتئناف يف منطقــة مكــة املكرمــة االطــاع علــى‬\n‫املعاملــة الــواردة مــن فضيلــة القاضــي باحملكمــة العامــة مبحافظــة‬\n‫قلــوة الشــيخ‪....../‬برقم ‪ 34478656‬وتاريــخ ‪1434/5/15‬ه ـ املرفــق بهــا‬\n‫الصــك الصــادر مــن فضيلتــه برقــم ‪ 34189860‬وتاريــخ ‪1434/4/16‬ه ـ‬\n‫املتضمــن دعــوى املدعــي العــام ضــد‪ ،....../‬املتهــم بالقيــام بســكب زيــت‬\n‫ســاخن علــى شــخص ممــا تســبب يف اصابتــه احملكــوم فيــه مبــا دون‬\n‫باطــن الصــك ‪.‬وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــى‬\n‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                        ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪56‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":52,"source_page_end":56,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"93c0e5375a620ec9f72ff036207c25274f251f741d641eb1a87b978ae7a8461f","normalized_text_hash":"d2680cd8d44d4ab961dd47001ad1ed961cbd918fef228376424ec478e8f31312","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p52-34189860"},{"id":"fd27e600-c293-5383-b5ca-68fed751b431","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -ضرب الزوج لزوجته -التعريض بالقذف -سب الزوج زوجته -توجه التهمة بالقرائن -تعزير الزوج بالسجن لضربه زوجته وسبها والتعريض بقذفها.","document_number":"34229637","case_number":"32464220","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بخميس مشيط وصدق ذلك احلكم من محكمة الاستئناف مبنطقة عسير هكذا قالت","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/4","year":"1434","subject":"اعتداء -ضرب -ضرب الزوج لزوجته -التعريض بالقذف -سب الزوج زوجته -توجه التهمة بالقرائن -تعزير الزوج بالسجن لضربه زوجته وسبها والتعريض بقذفها.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 34229637 :‬تاريخه‪1434/6/4 :‬هـ‬\n                        ‫رقم الدعوى‪32464220:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34364666‬تاريخه‪1434/11/20 :‬هـ‬\n\n\n\n     ‫اعتــداء ‪ -‬ضــرب ‪ -‬ضــرب الــزوج لزوجتــه ‪ -‬التعريــض بالقــذف ‪ -‬ســب‬\n     ‫الــزوج زوجتــه ‪ -‬توجــه التهمــة بالقرائــن ‪ -‬تعزيــر الــزوج بالســجن‬\n                              ‫لضربــه زوجتــه وســبها والتعريــض بقذفهــا‪.‬‬\n\n\n\n\n                              ‫‪-1‬قول اهلل تعالى ‪( :‬وال تنسوا الفضل بينكم)‬\n     ‫‪-2‬قيــام الشــبهة علــى االعتــداء بالضــرب والتعريــض بالقــذف موجــب‬\n                                                                    ‫للتعزيــر‪.‬‬\n     ‫‪-3‬النكــول عــن اليمــن يف الدعــوى اجلنائيــة اخلاصــة بطلــب التعزيــر‬\n     ‫قرينــة تــورث التهمــة بالنــاكل يجــوز معهــا تعزيــره خصوصــا إذا قامــت‬\n                                                     ‫قرائــن أخــرى تعضدهــا‪.‬‬\n\n\n\n\n     ‫ادعــت املدعيــة بــأن زوجهــا املدعــى عليــه رزقــت منــه بأربعــة أوالد وهــو‬\n     ‫يكثــر مــن ضربهــا وســبها وشــتمها وأنــه عــرض بقذفهــا بقولــه أن إحدى‬\n     ‫بناتــه ال تشــبهه وأنهــا مقيمــة لــدى أهلهــا وال ترغــب بالعــودة إليــه وتطلــب‬\n     ‫إيقــاع العقوبــة التعزيريــة عليــه‪ ،‬أقــر املدعــى عليــه بــأن املدعيــة ‪ -‬زوجتــه‬\n     ‫‪ -‬ال زالــت يف عصمتــه وأنهــا مقيمــة لــدى أهلهــا منــذ فتــرة إال أنــه لــم‬\n     ‫يضربهــا ولــم يعــرض بقذفهــا وأن ســبب غضبهــا قيامــه بالــزواج مــن‬\n\n‫‪57‬‬\n\f‫امــرأة أخــرى وأن دعواهــا كيديــة ويرغــب يف عودتهــا لــه‪ ،‬بعرضــه علــى‬\n‫املدعيــة قــررت بــأن غضبهــا العتدائــه عليهــا ضربــا وقذفــا وليــس ألجــل‬\n‫زواجــه‪ ،‬قــررت بــأن بينتهــا األشــعة الســينية املتضمنــة وجــود شــرخني‬\n‫صغيريــن بعظمــة األنــف اليمنــى واليســرى وقــررت بأنــه املتســبب فيهمــا‬\n‫وال بينــة لديهــا ســوى ذلــك وتطلــب ميينــه وباالطالع على األشــعة وعرضها‬\n‫علــى املدعــى عليــه أنكــر تســببه بهــذا الفعــل‪ ،‬ثــم جــرى محاولــة‬\n‫الصلــح بينهمــا فلــم يصطلحــا ثــم حضــرت املدعيــة وقــررت بأنــه صــدر‬\n‫لهــا حكــم مصــدق مــن االســتئناف بفســخ نكاحهــا مــن املدعــى عليــه‬\n‫وتطلــب مواصلــة النظــر يف القضيــة‪ ،‬قــرر املدعــى عليــه طلــب إيقــاف‬\n‫النظــر يف القضيــة حلــن الفصــل يف قضيــة احلضانــة والنفقــة املقامــة مــن‬\n‫املدعيــة إال أن احملكمــة لعــدم وجاهتــه لــم تلتفــت لطلبــه‪ ،‬جــرى محاولة‬\n‫الصلــح بينهمــا مــرة أخــرى وبــاءت بالفشــل ‪ .‬قــرر املدعــى عليــه بأنــه لــن‬\n‫يحلــف اليمــن علــى نفــي دعــوى املدعيــة إال إن أثبتــت دعواهــا ضــده‬\n‫ـاء علــى جميــع مــا ســبق فقــد قــررت احملكمــة مؤاخــذة املدعــى‬      ‫‪ ،‬وبنـ ً‬\n‫عليــه ‪ ،‬بيــد أنــه مــع قيــام موجــب التشــديد يف العقوبــة فهنــاك مــا يوجــب‬\n‫أيضــا تخفيفهــا كضعــف القرائــن‪ ،‬وجــود قرابــة بــن الزوجــن وأوالد‬\n‫بينهمــا وقــد قــال اهلل تعالــى‪« :‬وال تنســوا الفضــل بينكــم» ولهــذا رأت‬\n‫احملكمــة التوســط يف العقوبــة فقــررت توجيــه التهمــة للمدعــى عليــه‬\n‫باعتدائــه بالضــرب علــى املدعيــة وســبها وشــتمها والتعريــض بقذفهــا‬\n‫بســجنه خمســة عشــر يومــا ورد دعــوى املدعــى عليــه إيقــاف النظــر يف‬\n‫الدعــوى وبــه حكمــت‪ ،‬وبعــرض احلكــم علــى الطرفــن قــررا عــدم‬\n‫القناعــة بــه وطلبــا رفعــه إلــى محكمــة االســتئناف بالئحــة اعتراضيــة‪،‬‬\n                                   ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n                                                                                     ‫‪58‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة اجلزئيــة‬\n     ‫بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة اجلزئيــة بخميــس مشــيط برقــم وتاريــخ ‪ 1432/10/20‬ه ـ‬\n     ‫املقيــدة باحملكمــة برقــم وتاريــخ ‪ 1432/10/20‬ه ـ ففــي يــوم االحــد‬\n     ‫املوافق‪ 1432/10/20‬هـ افتتحت اجللســة الســاعة ‪9 : 30‬وفيها حضرت‬\n     ‫املدعيــة ‪ ،..........‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪،..........‬‬\n     ‫وهــي برفقــة والدهــا حامــل الســجل املدنــي رقــم ‪ ،..........‬وادعــت علــى‬\n     ‫احلاضــر معهــا يف مجلــس القضــاء ‪ ،..........‬ســعودي اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم ‪ ،..........‬قائلــه يف دعواهــا إن هــذا احلاضــر هــو‬\n     ‫زوجــي وقــد أجنبــت منــه أربعــة أوالد ثــاث بنــات وابــن وخــال فتــرة‬\n     ‫حياتــي الزوجيــة معــه لــم أهنــأ معــه بعيشــة طيبــة ‪ ،‬حيــث أنــه يتكــرر‬\n     ‫منــه االعتــداء علــي بالضــرب والســب والشــتم ‪ ،‬بــل بلــغ بــه األمــر أنــه‬\n     ‫قذفنــي يف عرضــي بقولــه إن هــذه البنــت ويقصــد إحــدى بناتــه منــي‬\n     ‫ال تشــبهني‪ ،‬وهــو بذلــك يعــرض بقــذيف ‪ ،‬وإنــي أطلــب احلكــم عليــه‬\n     ‫بعقوبــة رادعــة‪ ،‬علمــا أننــي اآلن غاضبــة منــه وجالســة يف منــزل والــدي‬\n     ‫ولــم يعــد لــي أي رغبــة يف العــودة إليــه ‪ ،‬وأوالدي يســكنون معــي هكــذا‬\n     ‫ادعــت‪ ،‬وبســؤال املدعــى عليــه قــال صحيــح أن املدعيــة زوجتــي وال زالــت‬\n     ‫يف عصمتــي ولــي منهــا أربعــة أوالد ‪ ،‬وهــي اآلن عنــد أهلهــا مــع أوالدهــا‬\n     ‫غاضبــة منــي منــذ ســتة أشــهر بســبب أننــي تزوجــت عليهــا بطلــب منهــا‪،‬‬\n     ‫ثــم ملــا تزوجــت غضبــت منــي وذهبــت إلــى بيــت أهلهــا‪ ،‬ولــم أعتــدِ عليهــا‪،‬‬\n     ‫ولــم أتعــرض لهــا بالقــذف ‪ ،‬ودعواهــا مجــرد دعــوى كيديــة‪ ،‬وأنــا لــي‬\n\n‫‪59‬‬\n\f‫رغبــة أكيــدة يف عودتهــا إلــى بيــت الطاعــة هكــذا أجــاب ‪ ،‬وبعــرض‬\n‫ذلــك علــى املدعيــة قالــت إننــي لــم أغضــب مــن زواجــه ‪ ،‬وأنــا راضيــة‬\n‫اآلن بزواجــه مــن الثانيــة ‪،‬وإمنــا أنــا غاضبــة منــه بســبب اعتــداءه وســبه‬\n‫وتعريضــه لــي بالقــذف ‪ ،‬والــذي يــدل علــى صحــة دعــواي هــي األشــعة‬\n‫الســينية علــى األنــف الــذي ضربنــي عليــه ‪ ،‬حيــث أثبتــت تلــك األشــعة‬\n‫الصــادرة مــن مجمــع ‪..........‬الطبــي بخميــس مشــيط أنــه يوجــد شــرخان‬\n‫صغيــران بعظمتــي األنــف اليمنــى واليســرى وهــذا يؤكــد صحــة مــا‬\n‫ذكرتــه ‪ ،‬وأمــا اعتداءاتــه الســابقة لــي بالضــرب والتعريــض بالقــذف‬\n‫فليــس بينــي وبينــه يف ذلــك إال اهلل تعالــى ‪ ،‬وإذا لــم يعتــرف بذلــك فإنــي‬\n‫أطلــب ميينــه علــى نفــي صحــة ذلــك االعتــداء الســابق والتعريــض بالقــذف‬\n‫‪ ،‬وأمــا االعتــداء الــذي أوضحتــه األشــعة فإنــه لــو طلبــت ميينــي علــى ذلــك‬\n‫حللفــت ‪ ،‬وكذلــك لــو طلبــت ميينــي علــى االعتــداء الســابق والتعريــض‬\n‫بالقــذف فإنــي أحلــف وأنــا صادقــة ‪ ،‬هكــذا أجابــت وأبــرزت األشــعة‬\n‫التــي ذكرتهــا ومعهــا تقريــر األشــعة بتوقيــع وختــم طبيــب األشــعة‬\n‫مبجمع‪..........‬الطبــي ‪ ،..........‬وقــد تضمــن التقريــر مــا ذكرتــه املدعيــة‬\n‫ووجــدت أصلــة مرفــق علــى اللفتــن ‪ 10,9‬مــن أوراق املعاملــة ‪ ،‬وبعرضــه‬\n‫علــى املدعــى عليــه قــال ال أعلــم عــن هــذا التقريــر ‪ ،‬وقد قامــت بإخراجه‬\n‫وهــي عنــد أهلهــا ‪ ،‬وأمــا أنــا فلــم أضربهــا ‪ ،‬وليســت تلــك اإلصابة بســبب‬\n‫منــي ‪ ،‬ولــو طلبــت ميينــي علــى نفــي صحــة دعواهــا فإنــي ال أحلــف اليمــن‬\n‫إال إذا أثبتــت دعواهــا ضــدي هكــذا أجــاب ‪ ،‬وعنــد وصــول القضيــة‬\n‫إلــى هــذا احلــد مت نصــح الطرفــن ووعظهمــا وبيــان حــق بعضهمــا علــى‬\n‫األخــر وعــدم نســيان الفضــل بينهمــا وكــذا العشــرة ومــا بينهمــا مــن‬\n‫أوالد ‪ ،‬وأن عليهمــا التأنــي والتعقــل ومحاولــة االصطــاح لــرأب الصــدع‬\n\n\n                                                                                      ‫‪60‬‬\n\f     ‫ولــم الشــمل ‪ ،‬هكــذا مت نصحهمــا ‪ ،‬وقــد رأيــت جتاوبــا مــن املدعــى‬\n     ‫عليــه ‪ ،‬ولكــن املدعيــة متــرددة وتكــرر الشــكوى ‪ ،‬وقــد مت إقناعهمــا‬\n     ‫برفــع اجللســة إلــى مــا بعــد عيــد األضحــى املبــارك ‪ ،‬لعــل اهلل يحــدث‬\n     ‫بعــد ذلــك أمــرا ‪ ،‬وأفهمــت املدعيــة مبراجعتنــا بعــد عيــد األضحــى‬\n     ‫إلعطائهــا موعــدا آخــر عنــد مراجعتهــا ‪ ،‬وملعرفــة مــا قــد يســتجد‬\n     ‫بينهمــا بنــاءا علــى مــا مت مــن وعــظ ونصــح ‪ ،‬ففهمــت ذلــك وقنعــت بــه‬\n     ‫‪ ،‬وبــذا رفعــت اجللســة إلــى مــا بعــد عيــد األضحــى لهــذا العــام ‪1432‬ه ـ‬\n     ‫‪ ،‬ويف يــوم الســبت املوافــق ‪1434/6/3‬ه ـ افتتحــت اجللســة الرابعــة يف‬\n     ‫الســاعة العاشــرة ‪ ،‬وفيهــا حضــرت املدعيــة برفقــة شــقيقها ‪..........‬حامــل‬\n     ‫البطاقــة رقــم ‪ ،..........‬وقالــت ليــس لــدي ســوى مــا قدمتــه ســابقا وأنــا‬\n     ‫ال زلــت علــى طلبــي الســابق‪ ،‬وقــد مت فســخ عقــد النــكاح بينــي وبــن‬\n     ‫املدعــى عليــه مبوجــب حكــم شــرعي مــن احملكمــة العامــة بخميــس‬\n     ‫مشــيط وصــدق ذلــك احلكــم مــن محكمــة االســتئناف مبنطقــة عســير‬\n     ‫هكــذا قالــت ‪،‬كمــا حضــر املدعــى عليــه وقــال إننــي أطلــب إيقــاف‬\n     ‫النظــر يف هــذه القضيــة حتــى الفصــل يف قضيــة نفقــة وحضانــة أوالدي‬\n     ‫املرفوعــة مــن قبــل املدعيــة لــدى احملكمــة العامــة بخميــس مشــيط‬\n     ‫وذلــك علــى ضــوء املادة(‪)82‬مــن نظــام املرافعــات الشــرعية والئحتــه‬\n     ‫التنفيذيــة‪ ،‬وإذا انتهــت تلــك القضيــة فــا مــا نــع لــدي مــن إكمــال النظر‬\n     ‫يف هــذه القضيــة بالوجــه الشــرعي ‪ ،‬ألننــي أرى أن إكمــال النظــر يف‬\n     ‫هــذه القضيــة يتوقــف علــى إكمــال النظــر يف القضيــة األخــرى علــى‬\n     ‫ضــوء املــادة‪ 83/1/2‬مــن نظــام املرافعــات الشــرعية ‪ ،‬وصحيــح أنــه مت‬\n     ‫احلكــم بفســخ عقــد النــكاح بينــي وبــن املدعيــة وصــدق احلكــم مــن‬\n     ‫محكمــة االســتئناف ولكننــي ال زلــت غيــر مقتنــع بهــذا الفســخ ولهــذا‬\n\n\n‫‪61‬‬\n\f‫فقــد رفعــت التماســا بهــذا إلــى املجلــس األعلــى للقضــاء هكــذا أجــاب‬\n‫‪ ،‬وبعــرض ذلــك علــى املدعيــة قالــت إننــي أرغــب يف إنهــاء قضيتــي هــذه‬\n‫بالوجــه الشــرعي وعــدم ربطهــا بــأي قضيــة أخــرى ال عالقــة لهــا بهــذه‬\n‫القضيــة هكــذا أجابــت ‪ ،‬ويف هــذه اجللســة متــت احملاولــة مــرة أخــرى‬\n‫ألجــل اإلصــاح بــن الطرفــن ومت عــرض عــدة حلــول بينهمــا إال أن‬\n‫املدعــى عليــه لــم يتجــاوب مــع أي عــرض مــن تلــك احللــول رغــم إبــداء‬\n‫املدعيــة للموافقــة علــى بعــض احللــول املقدمــة ممــا تعــذر معــه الصلــح‬\n‫ولــزم األمــر إنهــاء دعــوى املدعيــة بالوجــه الشــرعي ‪ ،‬ولــم أر وجاهــة‬\n‫لطلــب املدعــى عليــه إيقــاف النظــر يف هــذه القضيــة ‪ ،‬ألنــه ال عالقــة‬\n‫لهــا مباذكــره مــن مطالبــات أخــرى ‪ ،‬فنظــرا إلــى مــا ورد يف الدعــوى ‪،‬‬\n‫وإلــى إجابــة املدعــى عليــه ‪،‬وحيــث أنكــر مــا نســب إليــه إال أن املدعيــة‬\n‫قدمــت مــا يؤيــد دعواهــا وكانــت لهجتهــا قويــة ومطالبتهــا متكــررة‬\n‫وأبــدت تظلمهــا أكثــر مــن مــرة وكانــت تظهــر بــكل قــوة قدرتهــا علــى‬\n‫أداء اليمــن أنهــا صادقــة بــكل مــا أدعــت بــه علــى املدعــى عليــه بينمــا‬\n‫قــرر املدعــى عليــه عــدم قدرتــه علــى بــذل اليمــن لــو طلبــت منــه ممــا‬\n‫توجــه معــه لــدي التهمــة إلــى املدعــى عليــه مبــا أدعــت بــه جتاهــه املدعيــة‬\n‫مــن اعتــداء وســب وشــتم وتعريــض بالقــذف ‪ ،‬ومــا كان ينبغــي للمدعــي‬\n‫ذلــك ألن أصــل احليــاة الزوجيــة إمســاك مبعــروف أو تســريح بإحســان وال‬\n‫يحــل للمســلم أن يعتــدي علــى مــن كان بعيــدا عنــه ومــن بــاب أولــى عــدم‬\n‫االعتــداء علــى مــن هــو قريــب منــه ‪،‬وعندمــا أبــاح اهلل تعالــى للرجــل أن‬\n‫يضــرب زوجتــه فإمنــا ذلــك بشــروط كثيــرة منهــا عــدم ضــرب الوجــه‬\n‫ومنهــا تعــذر جــدوى النصــح واإلعــراض والهجــر ثــم ال يكــون الضــرب‬\n‫بعــد ذلــك إال ضربــا غيــر مبــرح ‪ ،‬ولهــذا قــررت مؤاخــذة املدعــى عليــه‬\n\n\n                                                                                        ‫‪62‬‬\n\f     ‫يف هــذه القضيــة وال ســيما وقــد زاد بــه احلــد إلــى التلفــظ بألفــاظ أدت‬\n     ‫إلــى التعريــض مبــا ال يحــل التعريــض بــه فضــا عــن التصريــح بــه ‪،‬‬\n     ‫ومــا ذكرتــه آنفــا موجــب لتشــديد العقوبــة علــى املدعــى عليــه ‪ ،‬وهــذه‬\n     ‫العقوبــة هــي التعزيــر يف كل مــا نســب إليــه ‪ ،‬إال أنــه ومــع ذكــر‬\n     ‫موجبــات تشــديد العقوبــة فــإن هنــاك موجبــات لتخفيــف العقوبــة يف‬\n     ‫هــذه القضيــة وهــي كــون األدلــة مجــرد قرائــن إضافــة إلــى وجودالقرابة‬\n     ‫بــن الطرفــن ‪ ،‬كمــا أن بينهمــا أوالد وأواصــر الرحــم ال زالــت بينهمــا‬\n     ‫والســيما وقــد قــال اهلل تعالــى بعــد الفــراق «وال تنســوا الفضــل بينكــم»‬\n     ‫‪ ،‬ولهــذا اختــرت التوســط يف العقوبــة بــن اجلانبــن ‪ ،‬وبنــاء علــى كل مــا‬\n     ‫تقــدم فقــد توجهــت لــدي التهمــة إلــى املدعــى عليــه باعتدائــه بالضــرب‬\n     ‫علــى املدعيــة وســبها وشــتمها والتعريــض بقذفهــا ويســجن لقــاء ذلــك‬\n     ‫خمســة عشــر يومــا ‪ ،‬ورددت طلــب املدعــى عليــه يف إيقــاف النظــر يف‬\n     ‫هــذه القضيــة ملــا ذكرتــه يف احليثيــات أعــاه ‪ ،‬ومبــا تقــدم حكمــت‬\n     ‫‪ ،‬وبعــرض احلكــم علــى الطرفــن قــررا عــدم القناعــة بــه وطلبــا رفعــه‬\n     ‫إلــى محكمــة االســتئناف بالئحــة اعتراضيــة ‪ ،‬فأفهمتهمــا أن عليهمــا‬\n     ‫مراجعــة احملكمــة يــوم الثالثــاء املوافــق ‪1434/6/6‬ه ـ الســتالم صــورة‬\n     ‫مــن احلكــم ومــن ثــم تقــدمي االعتــراض عليــه يف غضــون ثالثــن يومــا مــن‬\n     ‫تاريــخ ذلــك االســتالم ‪ ،‬وأن مــن يتأخــر عــن تقــدمي الئحتــه االعتراضيــة‬\n     ‫أثنــاء املــدة النظاميــة فــإن حقــه يف االعتــراض ســوف يســقط ومــن ثــم‬\n     ‫يكــون احلكــم مكتســبا للقطعيــة يف جانبــه ففهمــا ذلــك ‪ ،‬وبــذا‬\n     ‫انتهــت يف الســاعة احلاديــة عشــرة ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/03‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة لتدقيــق‬\n\n\n‫‪63‬‬\n\f‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس مشــيط برقــم‬\n‫‪ 342097209‬وتاريــخ ‪1434/10/11‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيل ــة القاضــي باحملكمــة الشــيخ‪.......... /‬برقــم ‪ 34229637‬وتاريــخ‬\n      ‫‪1434/6/4‬ه ـ اخلــاص بدعــوى ‪.......... /‬ض ـ ـ ـ ـ ــد ‪.......... /‬يف قضيــة‬\n‫( إيــذاء زوجتــه بالضــرب والســب والشــتم ) علــى الصفــة املوضحــة يف‬\n‫القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وحيــث‬\n‫ســبق دراســة القــرار وصــورة ضبطــه والئحتــي االعتــراض وأوراق‬\n‫املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه وأحلقــه بالقــرار وصــورة‬\n‫ـاء علــى قرارنــا رقــم ( ‪ ) 34288368‬وتاريــخ ‪1434/8/6‬ه ـ ‪.‬‬              ‫ضبطــه بنـ ً‬\n‫تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                              ‫وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                         ‫‪64‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":57,"source_page_end":64,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c671bf812c265f38b337df4b6948f870b79f200b0e2c6bf390f912fc098961ff","normalized_text_hash":"a1f229a3d4089e5ad5652d4f2fa80f7787c5562534f79d6c553f30d278737b33","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p57-34229637"},{"id":"046960c5-21f6-51bd-bcea-22eb213fce6c","document_type":"judgment","category":"judicial","subcategory":"general","title":"قذف -إيذاء -تشهير -إساءة سمعة -جرمية معلوماتية يف حق خاص -عدم قبول الرجوع عن اإلقرار يف حق آدمي -قذف من ال يتصور منه الزنا -نسبة الولد لغير أبيه هو قذف ألمه -إقامة حد القذف ثمانن جلدة وعدم قبول شهادة املدعى عليها إال بعد توبتها -التعزير بالسجن واجللد.","document_number":"3459216","case_number":"32560705","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/10","year":"1434","subject":"قذف -إيذاء -تشهير -إساءة سمعة -جرمية معلوماتية يف حق خاص -عدم قبول الرجوع عن اإلقرار يف حق آدمي -قذف من ال يتصور منه الزنا -نسبة الولد لغير أبيه هو قذف ألمه -إقامة حد القذف ثمانن جلدة وعدم قبول شهادة املدعى عليها إال بعد توبتها -التعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3459216 :‬تاريخه‪1434/3/10 :‬هـ‬\n                         ‫رقم الدعوى‪32560705:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 35267898‬تاريخه‪1435/6/7 :‬هـ‬\n\n\n\n     ‫قــذف ‪ -‬إيــذاء ‪ -‬تشــهير ‪ -‬إســاءة ســمعة ‪ -‬جرميــة معلوماتيــة يف حــق‬\n     ‫خــاص ‪ -‬عــدم قبــول الرجــوع عــن اإلقــرار يف حــق آدمــي ‪ -‬قــذف مــن ال‬\n     ‫يتصــور منــه الزنــا ‪ -‬نســبة الولــد لغيــر أبيــه هــو قــذف ألمــه ‪ -‬إقامــة‬\n     ‫حــد القــذف ثمانــن جلــدة وعــدم قبــول شــهادة املدعــى عليهــا إال بعــد‬\n                                            ‫توبتهــا ‪ -‬التعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n     ‫‪-‬قــول اهلل تعالــى‪( :‬فــا وربــك ال يؤمنــون حتــى يحكمــوك فيمــا شــجر‬\n                                                                         ‫بينهــم)‪.‬‬\n     ‫‪-‬جــاء يف كشــاف القنــاع‪« :)91/14( :‬وإن قــذف جماعــة يتصــور الزنــى‬\n                  ‫ا «‪.‬‬\n                     ‫منهــم عــادة بكلمــات حــد لــكل واحــد منهــم حــدا كامـ ً‬\n\n\n\n\n     ‫تقــدم أحــد املواطنــن ألميــر املنطقــة بشــكوى مفادهــا أن شــقيقته‬\n     ‫ُش ـ ِوهت ســمعتها بــكالم بــذيء عــن طريــق إحــدى مواقــع االنترنــت‬\n     ‫واملنتديــات وال يتهــم أحــد ًا بذلــك ‪ ،‬و بإجــراء البحــث والتحــري عــن‬\n     ‫مصــدر التشــهير واإلســاءة ضــد املجنــي عليهــا ظهــر أن امللقم الذي كان‬\n     ‫يســتخدمه اجلانــي لطليــق املدعيــة باحلــق اخلــاص‪ ،‬وباســتجواب املذكــور‬\n     ‫أفــاد أن امللقــم املســتخدم مــن خــال الهاتــف يعــود لــه ويســتخدم هــو‬\n\n‫‪65‬‬\n\f‫وزوجتــه (اجلانيــة)‪ ،‬انتهــى التحقيــق مــع املدعــى عليهــا إلــى اتهامهــا‬\n‫بإســاءة ســمعة امــرأة والتشــهير بهــا يف مواقــع اإلنترنــت‪ ،‬طلــب املدعــي‬\n‫العــام إثبــات مــا أســند إليهــا واحلكــم عليهــا وفــق الفقــرة اخلامســة مــن‬\n‫املــادة الثالثــة مــن نظــام مكافحــة اجلرائــم املعلوماتيــة‪ ،‬بعــرض دعــوى‬\n‫املدعــي العــام علــى املدعــى عليهــا أنكرتهــا جملــة وتفصيــا‪ ،‬وبعــد أن‬\n‫وزانــت احملكمــة بــن أقــوال األطــراف قــررت احلكــم بجلدهــا ثمانــن‬\n‫جلــدة حــد القــذف وبعــدم قبــول شــهادتها إال بعــد توبتهــا كمــا ثبتــت‬\n‫إدانتهــا بجرميــة التشــهير بغيــر وجــه حــق باملدعيــة وإســاءة ســمعتها عبــر‬\n‫املواقــع اإللكترونيــة واحلكــم عليهــا بالســجن ســتة أشــهر وبالغرامــة‬\n‫عشــرة آالف ريــال للحــق العــام وبســجنها ســنة وســتة أشــهر للحــق‬\n‫اخلــاص‪ ،‬وإفهامهــا أال يتكــرر منهــا ذلــك مســتقبال ويكــون هــذا‬\n‫احلكــم شــامال للحقــن اخلــاص والعــام‪ ،‬وبعــرض احلكــم علــى املدعــى‬\n‫عليهــا قــررت عــدم قناعتهــا واالعتــراض بالئحــة وقــرر املدعــون باحلــق‬\n‫اخلــاص االعتــراض كل بالئحــة وقــرر املدعــي العــام واملدعيــة باحلــق‬\n   ‫اخلــاص عــدم املعارضــة وجــرى التصديــق مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n                                                                                     ‫‪66‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنا‪......‬القاضــي باحملكــة اجلزئيــة باملدينــة‬\n     ‫املنــورة والقائــم بعمــل القاضــي ‪ ......‬القاضــي يف احملكمــة اجلزئيــة‬\n     ‫باملدينــة املنــورة إثنــاء إجازتــه وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n     ‫رئيــس احملكمــة اجلزئيــة باملدينــة املنــورة برقــم ‪ 32560705‬وتاريــخ‬\n     ‫‪ 1432/11/26‬ه ـ املقيــدة باحملكمــة برقــم ‪ 321522230‬وتاريــخ‬\n     ‫‪1432/11/26‬ه ـ ففــي يــوم األحــد املوافــق‪ 1433/04/11‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة ‪ 10 : 13‬وفيها ادعى املدعي العام ‪......‬ســعودي مبوجب‬\n     ‫الســجل املدنــي رقــم‪ ......‬والتعميــد رقــم ‪ 17648‬وتاريــخ ‪1432/6/12‬ه ـ‬\n     ‫علــى ‪ ......‬ســعودية مبوجــب الســجل املدنــي رقــم ‪ ......‬محصنــه مطلقــة‬\n     ‫الســراح بالكفالــة احلضوريــة قائــا يف حتريــر دعــواه انــه بتاريــخ‬\n     ‫‪1430/11/7‬ه ـ تقــدم املواطــن ‪ ......‬لصاحــب الســمو امللكــي أميــر‬\n     ‫منطقــة ‪ .....‬مفادهــا أن شــقيقته تعمــل يف جامعــة ‪ .....‬وحتمــل شــهادة‬\n     ‫الدكتــوراه وقــد مت تشــويه ســمعتها بــكالم بــذيء عــن طريــق إحــدى‬\n     ‫مواقــع اإلنترنــت وموقــع منتديــات طــاب وطالبــات جامعــة …‪ .‬واليتهــم‬\n     ‫أحــدا وبإجــراء البحــث والتحــري عــن مصــدر التشــهير واإلســاءة ضــد‬\n     ‫املجنــي عليهــا ظهــر ان امللقــم الــذي كان يســتخدمه اجلانــي تابع للهاتف‬\n     ‫رقــم ‪......‬العائــد للمدعــو‪ ......‬طليــق املذكــورة وباســتجواب ‪ ......‬افــاد ان‬\n     ‫امللقــم املســتخدم مــن خــال الهاتــف رقــم ‪......‬يعــود لــه ويســتخدمه هــو‬\n     ‫وزوجتــه ‪......‬فقــط وباســتجواب املــرأة املدعــى عليهــا ‪......‬اعترفــت انهــا‬\n     ‫هــي مــن قامــت بإســاءة ســمعة الدكتــورة ‪......‬مــن خــال اإلنترنــت‬\n     ‫والتشــهير بهــا وبــررت ذلــك بغيرتهــا منهــا ألن زوجهــا قــرر إرجاعهــا‬\n\n‫‪67‬‬\n\f‫الــى عصمتــه بعــد طالقهــا وذكــرت انــه لــم يشــاركها احــد يف ذلــك‬\n‫وانتهــى التحقيــق الــى اتهــام املــرأة املدعــى عليهــا ‪......‬بإســاءة ســمعت‬\n‫امــرأة والتشــهير بهــا يف مواقــع االنترنــت وذلــك لألدلــة التاليــة ‪-1 :‬‬\n‫اعترافهــا ‪ -2‬مــا ورد يف برقيــة صاحــب الســمو نائــب وزيــر الداخليــة‬\n‫املرفــق وببحــث ســوابقها لــم يعثــر لهــا علــى ســوابق وحيــث ان مــا اقــدم‬\n‫عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرعا اطلــب اثبــات مــا اســند‬\n‫اليهــا واحلكــم عليهــا وفــق املــادة الثالثــة فقــره ‪ 5‬مــن نظــام مكافحــة‬\n‫اجلرائــم املعلوماتيــة وبعــرض دعــوى املدعــي العــام علــى املدعــى عليهــا‬\n‫اجابــت بــأن مــا ذكــره املدعــي العــام غيــر صحيــح جملــة وتفصيــا‬\n‫هكــذا اجابــت ولطلــب البينــة مــن املدعــي العــام علــى مــا ادعــى بــه‬\n‫وانكرتــه املدعــى عليهــا ويف جلســة الحقــة لــدي أنــا ‪......‬حضــرت‬\n‫املتهمــة وبجانبهــا وكيلهــا اخوهــا ‪......‬ســعودي مبوجــب الســجل املدنــي‬\n‫رقــم ‪......‬مبوجــب الوكالــة رقــم ‪ ......‬يف ‪1433/4/26‬ه ـ مــن كتابــة‬\n‫عــدل املدينــة الثانيــة كمــا حضــر وكيــا املدعيــة باحلــق اخلــاص ‪......‬‬\n‫ســعودي مبوجــب الســجل املدنــي رقــم ‪......‬و‪......‬مبوجــب الوكالــة رقــم‬\n‫‪......‬يف ‪1432/12/2‬ه ـ وقــدم وكيــل املتهمــة مذكــرة بدفــاع موكلتــه‬\n‫أكــد فيهــا نفــي االتهــام املوجــه اليهــا وأن طليقها ‪......‬هــو الذي اجبرها‬\n‫علــى االعتــراف امــام هيئــة التحقيــق واالدعــاء العــام وســلمت صــورة مــن‬\n‫املذكــرة لوكيلــي املدعيــة وإلحضــار طليــق املتهــم ‪......‬رفعــت اجللســة‬\n‫فحضــر وكيــل املدعيــة كمــا حضــر طليقهــا ‪ ......‬ســعودي مبوجــب‬\n‫الســجل املدنــي رقــم ‪......‬كمــا حضــر وكيــل ‪......‬و ‪......‬و‪......‬الســابق‬\n‫حضوره وبسؤال احلاضر ‪......‬عما جاء بإفادة املدعى عليها ووكيلها‬\n‫مــن أنــه اجبرهــا علــى االدالء بأقوالهــا امــام هيئــة التحقيــق واالدعــاء‬\n\n\n                                                                                   ‫‪68‬‬\n\f     ‫العــام وغيرهــا مــن االقــرارات اجــاب مــا ذكرتــه املدعــى عليهــا‬\n     ‫ووكيلهــا غيــر صحيــح وبســؤال املدعــى عليهــا ووكيلهــا هــل توجــد‬\n     ‫بينــه علــى االكــراه فيمــا ادليــت بــه اجابــت هددنــي بابنــي ‪......‬وتقريــر‬\n     ‫املستشــفى املرفــق انــه ضربنــي وبعــرض ذلــك علــى طليقهــا اجــاب كل‬\n     ‫مــا ذكرتــه غيــر صحيــح فتــم حجــز القضية للدراســة وســمح لألطراف‬\n     ‫بتقــدمي مذكــرات وتبــادل بينهــم خــال االجــل ويف املوعــد احملــدد‬\n     ‫حضــرت املدعــى عليهــا ‪ ......‬وحضــر بجانبهــا وكيلهــا كمــا حضــر‬\n     ‫وكيــل املدعيــة كذلــك حضــر وكيــل كل مــن ‪......‬و‪ ......‬و‪ ......‬أبنــاء‬\n     ‫‪......‬وقــدم وكيــل املدعيــة مذكــرة طلــب فيهــا تعديــل االتهــام بحيــث‬\n     ‫يشــمل األمــر الــذي جرمتــه املــادة السادســة مــن نظــام مكافحــة اجلرائم‬\n     ‫املعلوماتيــة ســلمت نســخة عنهــا لوكيــل املدعــى عليهــا ونســخة للمدعــي‬\n     ‫العــام كمــا قــدم وكيــل املدعــى عليهــا مذكــرة بدفاع موكلته ســلمت‬\n     ‫نســخة عنهــا لوكيــل املدعيــة ولوكيــل كل مــن ‪......‬و‪ ......‬و‪ ......‬وطلــب‬\n     ‫وكيــل املدعيــة إعطــاءه مهلــة لتقــدمي طلبــات موكلتــه ويف املوعــد‬\n     ‫حضــرت املتهمــة وبجانبهــا وكيلهــا ‪......‬كمــا حضــر وكيــل املدعيــة‬\n     ‫باحلــق اخلــاص ‪......‬كمــا حضــر ‪......‬اصيــا عــن نفســه ووكيــا عــن‬\n     ‫والــده ‪ ......‬و‪ ......‬و‪ ......‬و‪ ......‬و‪......‬و‪ ......‬و‪ ......‬و‪......‬و‪ ......‬و‪......‬ابنــاء ‪......‬‬\n     ‫مبوجــب التوكيــل رقــم ‪......‬يف ‪1429/11/25‬ه ـ والوكالــة رقــم ‪......‬يف‬\n     ‫‪1433/11/24‬ه ـ وبســؤاله عــن دعــواه ودعــوى موكليــه اجــاب اننــا‬\n     ‫نطالــب مبــا يســتحق لنــا شــرعا نظيــر قــذف اختنــا ‪......‬والتشــهير بهــا‬\n     ‫باســم العائلــة وقــدم مذكــرة ســلمت نســخة عنهــا حملامــي املتهمــة الــذي‬\n     ‫طلــب اجــا للــرد وقــدم وكيــل املتهمــة مذكــرة ردا علــى مذكــرة‬\n     ‫محامــي املدعيــة ولتبــادل املذكــرات ترفــع اجللســة ويف املوعــد احملــدد‬\n\n\n‫‪69‬‬\n\f‫حضــر األطــراف قــدم كل طــرف مــا لديــه ومتســك بــه وعليــه وبنــاء علــى‬\n‫مــا جــاء بالئحــة االتهــام والتــي انتهــى فيهــا التحقيــق إلــى توجيــه االتهــام‬\n‫إلــى ‪ 27 ......‬ســنة ســعودي اجلنســية بإســاءة ســمعة امــرأة والتشــهير بهــا‬\n‫يف مواقــع اإلنترنــت ولكــون مــا أقدمــت عليــه فعــل محــرم ومعاقــب عليــه‬\n‫شــرعا طلــب املدعــي العــام إثبــات مــا أســند إليهــا واحلكــم عليهــا وفــق‬\n‫املــادة الثانيــة فقــرة (‪ )5‬مــن نظــام مكافحــة جرائــم املعلوماتيــة وبنــاء‬\n‫علــى الدعــوى التــي تقدمــت بهــا املدعيــة ‪......‬التــي تعمــل عضــو هيئــة‬\n‫تدريــس بجامعــة طيبــة بواســطة شــقيقها ‪......‬ضــد املتهمــة املذكــورة‬\n‫ذلــك أنهــا شــهرت بهــا عــن طريــق اإلنترنــت ورميهــا بــكالم بــذيء‬\n‫وقذفهــا بالزنــا صراحـ ًة طبقــا ملــا هــو موجــود يف مواقــع اإلنترنــت ومواقع‬\n‫منتديــات طــاب وطالبــات جامعــة طيبــة وبنــاء علــى املذكــرة املقدمــة‬\n‫مــن محاميهــا ‪......‬الــذي شــرح فيهــا دعــوى موكلتــه وطلــب فيهــا احلكــم‬\n‫بحــد القــذف وبتعزيرهــا تعزيــرا بليغــا بالســجن واجللــد لســبها وشــتمها‬\n‫موكلتــه واحلكــم بتعزيرهــا بالســجن واجللــد لتوزيعهــا ونشــرها رقــم‬\n‫جــوال موكلتــه ودعوتهــا إقامــة عالقــات معهــا واحلكــم بســجنها‬\n‫وجلدهــا لتصويــر موكلتــه ودبلجتهــا وتركيبهــا علــى أشــكال مخلــة‬\n‫بالشــرف وســجنها وجلدهــا إلســاءة ســمعة موكلتــه وباألخــص يف‬\n‫محيــط اجلامعــة وانتهــى إلــى طلــب تعويــض قــدره مليــون ريــال لقــاء مــا‬\n‫حلقهــا مــن ضــرر واحلكــم عليهــا بــأن تقــدم اعتــذارا ملوكلتــه يف املواقــع‬\n‫اإللكترونيــة التــي اســتخدمتها ويف اجلريــدة الرســمية وبنــاء علــى‬\n‫الدعــوى التــي تقــدم بهــا وكيــل أســرة املجنــي عليهــا ‪......‬وهــم والدهــا‬\n‫وإخوانهــا وأخواتهــا يطلــب فيهــا رد اعتبارهــم مــن املدعــى عليهــا وبنــاء‬\n‫علــى دعــوى كل مــن املدعيــن ‪......‬و‪ ......‬و‪ ......‬أبنــاء‪ ......‬بــأن املتهمــة‬\n\n\n                                                                                         ‫‪70‬‬\n\f     ‫تلفظــت عليهــم بالقــذف الصريــح وطعنــت يف نســبهم ألبيهــم كمــا جــاء‬\n     ‫علــى لســان موكلهــم ‪......‬الــذي طلــب يف نهايــة دعــواه احلكــم عليهــا‬\n     ‫بحــد القــذف وبنــاء علــى مــا أجابــت بــه املتهمــة حيــث أنكــرت مــا جــاء‬\n     ‫بالئحــة االتهــام ودعــاوى املدعيــن باحلــق اخلــاص وحيــث مت االطــاع على‬\n     ‫أقوالهــا لــدى هيئــة التحقيــق واالدعــاء العــام فوجــدت معترفــة صراحــة‬\n     ‫بقــذف املدعيــة بالزنــا وفعــل الفواحــش وكالم بــذيء ميــس شــرفها‬\n     ‫وشــرف أوالدهــا مــن الدكتــور ‪......‬زوجهــا الســابق عــن طريــق املوقــع‬\n     ‫اإللكترونــي الــوارد يف األوراق وملــا ووجهــت بــه قالــت أن زوجهــا ‪......‬‬\n     ‫املذكــور أجبرهــا علــى هــذا االعتــراف حتــت التهديــد لكنهــا لــم تقــدم‬\n     ‫دليــا علــى ذلــك وكل الــذي تذرعــت بــه تهديدهــا ونــزع ابنهــا ‪......‬مــن‬\n     ‫يدهــا وضربهــا الضــرب الــوارد باالســتمارة الطبيــة لكــن ذلــك ال يبــرر‬\n     ‫مــا أدلــت بــه وبالتالــي فــإن هــذا اإلقــرار حجــة عليهــا تعامــل مبقتضــاه‬\n     ‫شــرعا ألنــه أخــذ أمــام جهــة رســمية مخولــة بأخــذه وهــو إقــرار يف حــق‬\n     ‫آدمــي معصــوم ال يجــوز الرجــوع فيــه وممــا تقــدم يتضــح أن الدعــوى ذات‬\n     ‫شــقني شــق يتعلــق بحــد القــذف وشــق يتعلــق بدعــوى التشــهير ويجانــب‬\n     ‫هذين الشــقني مطالبة باحلق اخلاص وفيما يتعلق بالشــق االول فســيطبق‬\n     ‫فيهــا حــد القــذف الشــرعي ومــا يتعلــق بالشــق الثانــي ففيــه التعزيــر‬\n     ‫املناســب فيمــا ال يتعــارض مــع نظــام مكافحــة اجلرائــم املعلوماتيــة ومبــا‬\n     ‫أن تعــدد املقذوفــن يوجــب حــدا بقــدر تعددهــم كمــا نــص علــى ذلــك‬\n     ‫صاحــب كشــاف القنــاع ص‪ 91‬ج‪ 41‬حيــث قــال»وإن قــذف جماعــة‬\n     ‫يتصــور الزنــى منهــم عــادة بكلمــات حــد لــكل واحــد منهــم حــدا‬\n     ‫كامــا» ومبــا أن املطالبــن بحــد القــذف هــم كل مــن ‪ ......‬و‪......‬مــن‬\n     ‫مواليــد ‪1419/07/03‬ه ـ و‪......‬مــن مواليــد ‪1422/07/03‬ه ـ و‪......‬مــن‬\n\n\n‫‪71‬‬\n\f‫مواليــد ‪1425/3/4‬ه ـ لكــن هــؤالء األبنــاء نســبتهم إلــى غيــر أبيهــم هــو‬\n‫يف احلقيقــة قــذف ألمهــم املذكــورة وقــد حركــت الدعــوى بذلــك وبحــد‬\n‫واحــد يظهــر كــذب القــاذف وتــزول املعــرة فوجــب أن يكتفــي بذلــك‬\n‫أمــا دعــوى أســرتها والدهــا واخوتهــا بــرد اعتبارهــم فــإن يف عقوبــة حــد‬\n‫القــذف والتشــهير جبــرا لــكل األضــرار التــي ذكروهــا وردا العتبارهم‬\n‫وشــفاء ملــا يف النفــوس وعلــى املؤمــن أن يذعــن حلكــم اهلل عــز وجــل‬\n‫ورســوله صلــى اهلل وعليــه وســلم قــال تعالى(فــا وربــك ال يؤمنــون حتــى‬\n‫يحكمــوك فيمــا شــجر بينهــم) اآليــة وفيمــا يخــص طلــب التعويــض‬\n‫املــادي املقــدر مبليــون ريــال فــإن الشــريعة اإلســامية ال جتعــل شــرف‬\n‫اإلنســان وســمعته مــاال متقومــا وأيضــا فهــو أمــر معنــوي ال ميكــن تقديره‬\n‫وحتديــده وليــس لــه ضابــط والضــرر األدبــي املعنــوي ال يجيــره التعويــض‬\n‫املــادي وإمنــا شــرعت فيــه العقوبــة باحلــد واألدب وهــو أمــر مناســب جلبــر‬\n‫الضــرر وســيكون احلكــم شــامال للحقــن اخلــاص والعــام مــن أجــل مــا‬\n‫تقــدم حكمــت بإدانــة املتهمــة بجرميــة قــذف املدعيــة ‪......‬واحلكــم‬\n‫بجلدهــا ثمانــن جلــدة حــد القــذف وبعــدم قبــول شــهادتها إال بعــد توبتهــا‬\n‫وبإدانتهــا بجرميــة التشــهير بغيــر وجــه حــق باملدعيــة واســاءة ســمعتها عبر‬\n‫املواقــع اإللكترونيــة واحلكــم عليهــا بالســجن ســنتني وبالغرامــة عشــر‬\n‫آالف ريــال وأفهمتهــا بــأال يتكــرر منهــا ذلــك مســتقبال حكمــا شــامال‬\n‫للحقــن اخلــاص والعــام بــذا صــدر احلكــم وأفهــم حســب األصــول‬\n‫فقــررت املتهمــة عــدم قناعتهــا واالعتــراض بالئحــة وقــرر املدعــون باحلــق‬\n‫اخلــاص االعتــراض كل بالئحــة وقــرر املدعــي العــام عــدم املعارضــة‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                   ‫وسلم ‪ .‬حرر يف ‪1434/3/3‬هـ‬\n\n\n                                                                                    ‫‪72‬‬\n\f     ‫احلمــد اهلل وحــده وبعــد لــدي أنــا ‪ ......‬القاضــي باحملكمــة اجلزائيــة‬\n     ‫باملدينــة املنــورة ففــي يــوم الثالثــاء املوافق‪1434/06/27‬ه ـ افتتحــت‬\n     ‫اجللســة وفيهــا جــرى االطــاع علــى القــرار رقــم ‪ 34236414‬وتاريــخ‬\n     ‫‪1434/06/11‬ه ـ الصــادر مــن محكمــة االســتئناف الدائــرة اجلزائيــة‬\n     ‫الثانيــة مبكــة املكرمــة بتصديــق احلكــم الصــادر عنــا بالقــرار‬\n     ‫رقــم ‪ 3459216‬وتاريــخ ‪1434/03/10‬ه ـ ولكــي ال يخفــى جــرى‬\n     ‫التهميــش وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n     ‫حــرر يف ‪1434/06/27‬ه ـ احلمــد هلل وحــده وبعــد فلــدي أنــا ‪......‬‬\n     ‫القاضــي يف احملكمــة اجلزائيــة باملدينــة املنــورة ففــي يــوم األحــد‬\n     ‫املوافق‪1434/09/20‬ه ـ افتتحــت اجللســة الســاعة وفيها حضــر‪......‬و‪......‬‬\n     ‫الســابق حضورهمــا‪ .‬بنــاء علــى خطــاب مديــر مركــز شــرطة ‪......‬رقــم‬\n     ‫‪22/6709/22‬وتاريــخ ‪1434/9/7‬ه ـ بشــأن االستفســار عــن العقوبــة‬\n     ‫املوقعــة علــى احملكــوم عليهــا ‪ ......‬لتحديــد احلكــم للحــق العــام‬\n     ‫ليتســنى للجنــة دراســة أوراقهــا علــى ضــوء تعليمــات العفــو وعليــه مت‬\n     ‫اعــادة الدعــوى للمرافعــة واســتدعاء احملكــوم عليهــا واحملكــوم لهــا‬\n     ‫واملدعــي العــام فحضــر ‪ ......‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n     ‫رقــم ‪ .....‬مبوجــب الوكالــة رقــم ‪ 70904‬يف‪1432/12/2‬ه ـ وكيــا عــن‬\n     ‫املدعيــة ‪ ......‬كمــا حضــر ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n     ‫رقــم …… وكيــا عــن احملكــوم عليهــا بدريــة مبوجــب التوكيــل رقــم‬\n     ‫‪29672‬وتاريــخ ‪1433/04/26‬ه ـ وبعــد االطــاع علــى كامــل األوراق‬\n     ‫فقــد تقــرر جعــل عقوبــة احلــق العــام ســتة أشــهر والغرامــة املذكــورة‬\n     ‫وابقــاء احلكــم فيمــا عــدا ذلــك للحــق اخلــاص بالنســبة حلــد القــذف‬\n     ‫والســجن ســنه وســتة أشــهر فقــرر وكيــل املدعيــة قناعتــه وقــرر وكيــل‬\n\n\n‫‪73‬‬\n\f‫احملكــوم عليهــا اعتراضــه بالئحــة فأفهــم بتعليمــات االســتئناف وقــرر‬\n‫املدعــي العــام االعتــراض بــدون الئحــة‪ ... .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/9/20‬ه ـ‬\n   ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪-:‬‬\n‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثانيــة يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪321522230‬‬\n‫وتاريــخ ‪1434/5/21‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ‪/‬‬\n‫…‪ .‬القاضــي باحملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪3459216‬‬\n‫وتاريــخ ‪1434/3/10‬ه ـ ‪ ،‬املتضمــن دعــوى املدعــي العــام ضد‪، …… /‬‬\n‫املتهمــة يف قضيــة تشــهير ‪ ،‬احملكــوم فيــه مبــا دون باطنــه ‪ .‬وبدراســة‬\n‫القــرار وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق‬\n                 ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪74‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":65,"source_page_end":74,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ae2c671f90d114864283bd0efcff2c87e3fa08937e6e9ab29a4936c58c80f356","normalized_text_hash":"7eabec09f4840454a1dc0e67021f92b9dd0052d85cdd6503124100041c8ce3b0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p65-3459216"},{"id":"8befe02a-fb6c-572d-b74a-da2f7b2dd028","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -ضرب الزوج لزوجته -إنكار الزوج ضرب زوجته -حلف الزوجة اليمن على قيام الزوج بضربها -اليمن تشرع يف جانب أقوى املتداعين -تعزير الزوج بالسجن واجللد لقاء ضربه","document_number":"33327938","case_number":"33172110","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/5","year":"1434","subject":"اعتداء -ضرب -ضرب الزوج لزوجته -إنكار الزوج ضرب زوجته -حلف الزوجة اليمن على قيام الزوج بضربها -اليمن تشرع يف جانب أقوى املتداعين -تعزير الزوج بالسجن واجللد لقاء ضربه","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 33327938 :‬تاريخه‪1433/7/5 :‬هـ‬\n                         ‫رقم الدعوى‪33172110:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34165875‬تاريخه‪1434/3/18 :‬هـ‬\n\n\n\n     ‫اعتــداء ‪ -‬ضــرب ‪ -‬ضــرب الــزوج لزوجتــه ‪ -‬إنــكار الــزوج ضــرب زوجتــه‬\n     ‫‪ -‬حلــف الزوجــة اليمــن علــى قيــام الــزوج بضربهــا ‪ -‬اليمــن تشــرع يف‬\n     ‫جانــب أقــوى املتداعيــن ‪ -‬تعزيــر الــزوج بالســجن واجللــد لقــاء ضربــه‬\n                                                                     ‫لزوجتــه ‪.‬‬\n\n\n\n\n     ‫‪-1‬جتــاوز احلــد الشــرعي فيمــن لــه واليــة التأديــب أمــر محــرم ومعصيــة‬\n                                                                   ‫توجــب التعزير‪.‬‬\n     ‫‪-2‬قــول صاحــب شــرح منتهــى اإلرادات‪ (:‬ولــه ‪ -‬أي‪ :‬الــزوج واألب والســيد‬\n     ‫‪ -‬تأديــب زوجــة وتأديــب ولــد لــو كان الولــد مكلفـ ًا مزوجـ ًا بضــرب غيــر‬\n                                                                ‫مبــرح ) ( ‪.)686 /5‬‬\n     ‫‪-3‬قولــه يف كشــاف القناع‪(:‬ويحــرم ضــرب الوجــه ويف اآلدمــي أشــد‬\n                                              ‫ألنــه أعظــم حرمــة) (‪.)2846 /4‬‬\n                              ‫‪ -4‬اليمني تشرع يف جانب األقوى من املتداعيني‪.‬‬\n\n\n\n\n     ‫تقدمــت املدعيــة بدعــوى ضــد زوجهــا املدعــى عليــه بأنــه أســاء عشــرتها‬\n     ‫وقــام بضربهــا وســعى يف الشــروع بقتلهــا ممــا تركهــا يف حالــة نفســية‬\n     ‫عصيبــة وتطلــب تعزيــره علــى ذلــك‪ ،‬أقــر املدعــى عليــه بــأن املدعيــة ‪-‬‬\n\n‫‪75‬‬\n\f‫زوجتــه ‪ -‬وينكــر ضربهــا واالعتــداء عليهــا وشــروعه يف قتلهــا‪ ،‬بســؤال‬\n‫وكيــل املدعيــة عــن البينــة قــرر بــأن بينتــه التقريــر الطبــي الصــادر مــن‬\n‫أحــد املجمعــات الطبيــة املتضمــن ظهــور آثــار كدمــات متفرقــة باجلســم‬\n‫وكدمتــن بالــذراع األعلــى األميــن وكدمــة بأعلــى الــذراع األيســر‬\n‫وكدمتــن بالســاق األميــن وكدمــة بالســاق األيســر وجــرح عميــق صغير‬\n‫خلــف الكعــب األيســر وجــرح بســيط بالشــفة الســفلية ومــدة الشــفاء‬\n‫أســبوعني مــا لــم حتــدث مضاعفــات‪ ،‬كمــا قــرر املدعــي وكالــة بــأن‬\n‫بينتــه األوراق املرفقــة باملعاملــة ‪ ،‬فجــرى الرجــوع لهــا واالطــاع علــى‬\n‫محضــر االســتجواب للمدعــى عليــه املتضمــن إقــراره بأنــه قــام بســحب‬\n‫املدعيــة مــن رأســها فقــط ‪ ،‬كمــا جــرى االطــاع علــى تقريــر احلالــة‬\n‫األســرية الصــادر مــن مركــز التنميــة األســرية املتضمــن بــأن املدعــى‬\n‫عليــه اعتــرف بشــد رأس املدعيــة وكســر جوالهــا‪ ،‬وبعرضــه علــى‬\n‫املدعــى عليــه أقــر بأنــه قــام بشــد شــعر رأســها وكســر جوالهــا وأنكــر‬\n‫قيامــه بإحلــاق إصابــة بهــا‪ ،‬جــرى توجيــه اليمــن للمدعيــة بنــاء علــى مــا‬\n‫قــرره الفقهــاء مــن أن اليمــن تشــرع يف جانــب األقــوى مــن املتداعيــن‬\n‫فحلفــت املدعيــة اليمــن بــأن املدعــى عليــه قــام بضربهــا علــى وجههــا‬\n‫وشــد شــعر رأســها وضربهــا مــع ذراعيهــا وســاقها ممــا أدى حلــدوث‬\n‫ـاء علــى جميــع مــا ســبق فقــد قــررت‬    ‫اإلصابــة التــي حلقــت بهــا‪ ،‬بنـ ً‬\n‫احملكمــة ثبــوت قيــام املدعــى عليــه بضــرب املدعيــة وتعزيــر املدعــى‬\n‫عليــه بالســجن شــهر ًا حتتســب منهــا مــدة إيقافــه وجلــده خمســن جلــدة‬\n‫دفعــة واحــدة ‪ ،‬وبعــرض احلكــم علــى الطرفــن قــررا االعتــراض عليــه‬\n‫وطلبــا اســتئنافه بالئحــة فأفهمــا بتعليمــات االســتئناف‪ ،‬صــدق احلكــم‬\n                                                    ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n                                                                                     ‫‪76‬‬\n\f     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n     ‫أنــا ‪ ........‬القاضــي باحملكمــة اجلزئيــة بالدمــام بنــاء علــى املعاملــة‬\n     ‫املقيــدة لــدى احملكمــة برقــم ‪33453450‬وتاريــخ ‪1433/03/09‬ه ـ‬\n     ‫واحملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزئيــة بالدمــام‬\n     ‫برقم‪33172110‬وتاريخ‪1433/03/09‬ه ـ افتتحــت اجللســة يف يــوم‬\n     ‫االثنــن ‪1433/04/19‬ه ـ الســاعة احلاديــة عشــرة وفيهــا حضــر‪........‬‬\n     ‫الوكيــل الشــرعي عــن ‪........‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n     ‫عــدل الدمــام الثانيــة برقــم يف ‪1433/04/12‬ه ـ املتضمنــة حــق املرافعــة‬\n     ‫واملدافعــة واملطالبــة والصلــح والتنــازل وطلــب اليمــن ورده أ‪.‬ه ـ وحضــر‬\n     ‫ا إن‬  ‫حلضــوره ‪........‬مبوجــب الســجل املدنــي ‪........‬وادعــى األول قائ ـ ً‬\n     ‫املدعــى عيلــه هــو زوج ملوكلتــي ابنتــي ‪........‬وقــد أســاء عشــرتها وقــام‬\n     ‫بضربهــا وكذلــك حــاول الشــروع يف قتلهــا ممــا أدى بهــا إلــى حالــة‬\n     ‫نفســية عصبيــة لــذا أطلــب تعزيــره علــى ذلــك هكــذا ادعــى‪ ،‬وبعــرض‬\n     ‫الدعــوى علــى املدعــى عليــه قــال ما ذكــره املدعي مــن زواجي مبوكلته‬\n     ‫فذلــك صحيــح وأمــا ضربــي لهــا ومحاولــة الشــروع يف قتلهــا فذلــك غيــر‬\n     ‫صحيــح كلــه ولــم أقــم باالعتــداء عليهــا هكــذا أجــاب وبعــرض ذلــك‬\n     ‫علــى املدعــي وكالــة قــال مــا ذكــره املدعــى عليــه مــن عــدم ضربــه لهــا‬\n     ‫ومحاولــة الشــروع يف قتلهــا فذلــك غيــر صحيــح والصحيح ما ذكرت يف‬\n     ‫دعــواي هكــذا أجــاب وبســؤال املدعــي وكالــة البينــة علــى دعــواه قــال‬\n     ‫بينتــي التقريــر الطبــي وأطلــب مهلــة إلحضــاره ولــذا رفعــت اجللســة ويف‬\n     ‫يــوم الثالثــاء ‪1433/05/25‬ه ـ الســاعة احلاديــة عشــرة افتتحــت اجللســة‬\n\n‫‪77‬‬\n\f‫وفيهــا حضــر الطرفــان وبســؤال املدعــي وكالــة البينــة علــى دعــواه قــال‬\n‫بينتــي مــا جــاء يف التقريــر الطبــي املرفــق بخطــاب رئيــس دائــرة التحقيــق‬\n‫يف قضايــا االعتــداء علــى النفــس رقــم (‪ )........‬وتاريــخ ‪1433/05/05‬ه ـ‬\n‫هكــذا أجــاب ثــم جــرى االطــاع علــى التقريــر الطبــي فوجدتــه صــادر‬\n‫مــن مجمــع الدمــام الطبــي برقــم ‪........‬يف ‪1432/12/02‬ه ـ املتضمــن مــا‬\n‫نصــه (بالكشــف علــى املذكــورة أعــاه بتاريــخ ‪1432/12/02‬ه ـ تبــن‬\n‫وجــود آثــار كدمــات متفرقــة باجلســم كدمتــن بالــذراع األعلــى األميــن‬\n‫كدمــه بأعلــى الــذراع األيســر وكدمتــن بالســاق األميــن وكدمــه‬\n‫بالســاق األيســر وجــرح عميــق صغيــر ‪1 2/1‬ســم خلــف الكعــب األيســر‬\n‫جــرح بســيط بالشــفة الســفلية ومــدة الشــفاء أســبوعني مــا لــم حتــدث‬\n‫مضاعفــات) كمــا جــرى ســؤال املدعــي وكالــة هــل يوجــد لديــه زيــادة‬\n‫بينــة فقــال توجــد لــدي زيــادة بينــة وأطلــب الرجــوع إلــى املعاملــة هكــذا‬\n‫أجــاب ثــم جــرى الرجــوع إلــى املعاملــة فوجــدت علــى لفــة رقــم (‪ )1‬تقريــر‬\n‫األحــوال األمنيــة ص (‪ )11‬محضــر اســتجواب املدعــى عليــه املتضمــن‬\n‫إقــراره بأنــه قــام بســحبها مــن رأســها فقــط كمــا وجــدت علــى لفــه رقــم‬\n‫(‪ )37-31‬تقريــر حالــة أســرية صــادر مــن مركــز التنميــة األســرية حيــث‬\n‫وجــدت علــى لفــه رقــم (‪ )35‬أن الــزوج اعتــرف بشــد شــعرها وتكســير‬\n‫جوالهــا وبعــرض ذلــك علــى املدعــى عليــه قــال صحيــح أننــي ســحبتها مــن‬\n‫رأســها وقمــت بشــد شــعرها وتكســير جوالهــا لكــن لــم أصبهــا بــأي‬\n‫إصابــة هكــذا أجــاب ثــم طلبــت مــن املدعــي وكالــة إحضــار املدعيــة‬\n‫أصالــة ولــذا رفعــت اجللســة ويف يــوم الســبت ‪1433/07/05‬ه ـ الســاعة‬\n‫الثانيــة عشــرة افتتحــت اجللســة وفيهــا حضــرت املدعية‪........‬ســعودية‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬املعــرف بهــا مــن قبــل وكيلها‬\n\n\n                                                                                     ‫‪78‬‬\n\f     ‫والداهــا ‪........‬كمــا حضــر املدعــى عليــه وبعــد التأمــل يف الدعــوى ومبــا‬\n     ‫أن اليمــن تشــرع يف جانــب أقــوى املتداعيــن كمــا ذكــر ذلــك الفقهــاء‬\n     ‫لــذا جــرى عــرض اليمــن علــى املدعيــة فاســتعدت باحللــف فأذنــت لهــا‬\n     ‫فحلفــت قائلــة ( واهلل العلــي العظيــم عالــم الغيــب والشــهادة أن زوجــي‬\n     ‫املدعــى عليــه ‪........‬قــام بضــرب وجهــي وشــد شــعر رأســي وضربــي مــع‬\n     ‫ذراعــي وســاقي ممــا أدى إلــى حــدوث اإلصابــة التــي حلقــت بــي ) هكــذا‬\n     ‫حلفــت فبنــاء علــى مــا تقــدم مــن دعــوى املدعيــة وإجابــة املدعــى عليــه‬\n     ‫وإقــراره بشــد شــعر املدعيــة وســحب رأســها وإنــكار حــدوث اإلصابــة‬\n     ‫بهــا وبنــاء علــى التقريــر الطبــي ومبــا أن اليمــن تشــرع يف جانــب أقــوى‬\n     ‫املتداعيــن وجانــب املدعيــة تقــوى بالتقريــر الطبــي ومبــا أن املدعيــة‬\n     ‫حلفــت اليمــن كمــا طلبــت منهــا ومبــا أن املدعــى عليــه جتــاوز حــد‬\n     ‫التأديــب ممــا أدى إلــى إصابــة املدعــى عليهــا وهــذا الفعــل موجــب‬\n     ‫للتعزيــر فقــد ورد يف شــرح منتهــى اإلرادات (‪ )254/10‬مــا نصــه‪( :‬ولــه‬\n     ‫‪ -‬أي‪ :‬الــزوج واألب والســيد ‪ -‬تأديــب زوجــة وتأديــب ولــد لــو كان الولــد‬\n     ‫مكلفـ ًا مزوجـ ًا بضــرب غيــر مبــرح ) كمــا ورد يف كشــاف القنــاع عــن‬\n     ‫مــن اإلقنــاع (‪ )463/19‬مــا نصــه‪( :‬ويحــرم ضــرب الوجــه ويف اآلدمــي‬\n     ‫أشــد ألنــه أعظــم حرمــة) لــذا كلــه فقــد ثبــت لــدي قيــام املدعــى عليــه‬\n     ‫بضــرب زوجتــه املدعيــة ممــا ادى إلــى حــدوث اإلصابــة التــي حلقــت بهــا‬\n     ‫يف التقريــر وقــررت تعزيــر املدعــى عليــه بالســجن ملــدة شــهر حتتســب‬\n     ‫منهــا مــدة إيقافــه وجلــده خمســن جلــدة تعزيــر ًا دفعــة واحــدة وبعــرض‬\n     ‫احلكــم علــى الطرفــن قــررا االعتــراض علــى احلكــم وطلبــا االســتئناف‬\n     ‫بالئحــة يقدمانهــا فأفهمتهمــا بأنــه ســوف يجــري بعــد قليــل تســليمهما‬\n     ‫نســخة مــن احلكــم ليقدمــا اعتراضهمــا خــال ثالثــن يوم ـ ًا مــن اآلن‬\n\n\n‫‪79‬‬\n\f‫يكــون حقهمــا يف االســتئناف بعــد مضــي هــذه املــدة ســاقط ًا ففهمــا‬\n‫ذلــك وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر يف‬\n                                                                 ‫‪1433/07/05‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت ‪1434/03/28‬ه ـ الســاعة‬\n‫العاشــرة إال ربــع افتتحــت اجللســة وفيهــا وردتنــا املعاملــة مــن محكمــة‬\n‫االســتئناف باملنطقــة الشــرقية وبرفقهــا القــرار الصــادر مــن الدائــرة‬\n‫اجلزائيــة الثانيــة برقــم ‪34165875‬يف ‪1434/03/18‬ه ـ املتضمــن‬\n‫املصادقــة علــى احلكــم وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                                            ‫محمــد ‪ .‬حــرر يف ‪1434/03/28‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/34/521772‬ج‪ 2‬وتاريــخ ‪1434/3/1‬ه ـ الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام املكلــف برقــم‬\n‫‪ 33/2039747‬وتاريــخ ‪1434/2/30‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ ‪......../‬املســجل برقــم ‪33327938‬‬\n‫وتاريــخ ‪1433/7/5‬ه ـ اخلــاص بدعوى‪......../‬ضــد‪......../‬يف قضيــة عنــف‬\n‫ضــد املــرأة وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه والالئحتــن االعتراضيتــن‬\n‫وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه علــى قرارنــا‬\n‫رقــم ‪/33407761‬ج‪/2‬ب وتاريــخ ‪1433/9/11‬ه ـ قررنــا املصادقــة علــى‬\n‫احلكــم بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمد‬\n                                ‫وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/3/18‬ه ـ‬\n\n\n\n                                                                                         ‫‪80‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":75,"source_page_end":80,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d2dc3422a4f75f181baeaacabd8afe8de8eef13efaeda0931660f5c6b3dd9422","normalized_text_hash":"4f02fcf03f1f185c8a9bf3a0e01cf17bed185e7882b1c0bb7cb3da4187843016","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p75-33327938"},{"id":"32dad764-2b14-59f1-a2ad-968c9a952242","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء-ضرب -شرب مسكر -رجوع عن إقرار حتقيق ا -احلدود تدرأ بالشبهات -التعزير بالسجن واجللد وأخذ التعهد.","document_number":"3416887","case_number":"33254614","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/19","year":"1434","subject":"اعتداء-ضرب -شرب مسكر -رجوع عن إقرار حتقيق ا -احلدود تدرأ بالشبهات -التعزير بالسجن واجللد وأخذ التعهد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 3416887 :‬تاريخه‪1434/1/19 :‬هـ‬\n                        ‫رقم الدعوى‪33254614:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34235036‬تاريخه‪1434/6/10 :‬هـ‬\n\n\n\n     ‫اعتداء‪-‬ضــرب ‪ -‬شــرب مســكر ‪ -‬رجــوع عــن إقــرار حتقيق ـ ًا ‪ -‬احلــدود‬\n               ‫تــدرأ بالشــبهات ‪-‬التعزيــر بالســجن واجللــد وأخــذ التعهــد‪.‬‬\n\n\n\n\n     ‫‪-1‬قــول اهلل تعالــى‪« :‬وتعاونــوا علــى البــر والتقــوى وال تعاونــوا علــى‬\n                                                             ‫اإلثــم والعــدوان»‪.‬‬\n     ‫‪-2‬عــن ابــن عبــاس ‪-‬رضــي اهلل عنهمــا‪ -‬قــال‪ :‬قــال رســول اهلل صلــى اهلل‬\n                ‫عليــه وســلم‪« :‬ادرؤوا احلــدود بالشــبهات» أخرجــه ابــن عــدي‪.‬‬\n     ‫‪-3‬عــن ابــن عمــر ‪-‬رضــي اهلل عنهمــا‪ -‬عــن النبــي صلــى اهلل عليــه وســلم‬\n                 ‫قــال‪« :‬كل مســكر خمــر وكل خمــر حــرام» أخرجــه مســلم‪.‬‬\n\n\n\n\n     ‫جــرى توجيــه االتهــام مــن االدعــاء العــام للمدعــى عليهمــا أحدهمــا‬\n     ‫وهــو األول لــم يحضــر كونــه مطلــق الســراح باالجتمــاع علــى مفســدة‬\n     ‫شــرب املســكر وتوجيــه االتهــام للثانــي بشــرب املســكر وطلــب إثبــات‬\n     ‫مــا أســند إليهمــا وإيقــاع العقوبــة التعزيريــة لهمــا وإقامــة حــد املســكر‬\n     ‫علــى الثانــي حيــث قبــض عليهمــا علــى إثــر مضاربــة فلوحــظ انبعــاث‬\n     ‫رائحــة املســكر مــن جوفهمــا ‪ ،‬أفــاد املدعــى عليــه الثانــي أن إقــراره‬\n     ‫انتــزع منــه بالقــوة وألن احلــدود تــدرأ بالشــبهات إرتــأت احملكمــة عــدم‬\n\n‫‪81‬‬\n\f‫ـاء عليــه قــررت احملكمــة احلكــم علــى‬     ‫إدانــة املدعــى عليــه الثانــي وبنـ ً‬\n‫املدعــى عليــه الثانــي للشــبهة مبــا يلــي‪ :‬أوال‪ /‬الســجن ملــدة أســبوع يحســب‬\n‫منهــا الفتــرة التــي أمضاهــا يف الســجن ألجــل هــذه القضيــة وجلــده‬\n‫ثالثــون جلــدة دفعــة واحــدة للشــبهة يف اجتماعــه علــى مفســدة‪ .‬ثانيــا‪/‬‬\n‫جلــده ســبعون جلــدة دفعــة واحــدة وأخــذ التعهــد الشــديد بلــزوم طريــق‬\n‫االســتقامة والبعــد عــن احملرمــات وأال يعــود ملثــل مــا بــدر منــه وذلــك‬\n‫للشــبهة يف شــربه املســكر ويكــون بــن اجللــد وســابقه مــدة ال تقــل عــن‬\n‫خمســة عشــر يوما‪،‬جــرى تأجيــل النظــر يف الدعــوى املقامــة علــى املدعى‬\n‫عليــه األول حلــن إحضاره‪،‬بعــرض احلكــم علــى الطرفــن قــرر املدعــى‬\n‫عليــه القناعــة بينمــا قــرر املدعــي العــام االعتــراض طالبــا متكينــه مــن‬\n‫تقــدمي الئحــة اعتراضيــة فأفهــم بتعليمــات االســتئناف‪ ،‬صــدق احلكــم‬\n                                                     ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــد هــو بعــد فلــدي أنــا ‪...........‬القاضــي يف احملكمة اجلزائية‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪ .....‬وتاريــخ‬\n‫‪1433/04/12‬ه ــاملقيدة باحملكمــة برقــم وتاريــخ ‪1433/04/10‬ه ـ‬\n‫ففــي يــوم الثالثــاء املوافق‪1433/05/25‬ه ـ افتتحــت اجللســة الســاعة ‪24‬‬\n‫‪ 11 :‬وفيهــا حضــر املدعــي العــام ‪...........‬نيابــة عــن املدعــي العــام مبوجــب‬\n‫خطــاب التعميــد رقــم ‪...........‬وتاريــخ ‪1432/08/15‬ه ـ وادعــى علــى‬\n‫ال مــن ‪ )21( ........... -1‬عام ـ ًا ســعودي اجلنســية ســجل مدنــي رقــم‬      ‫ك ً‬\n‫(‪ )...........‬مفــرج عنــه بالكفالــة احلضوريــة ‪ )23(........... -2‬ســعودي‬\n\n                                                                                        ‫‪82‬‬\n\f     ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )...........‬مفــرج عنــه بضمــان مقــر‬\n     ‫ا بدعــواه أنــه بتاريــخ ‪1431/12/14‬ه ـ قبــض علــى املدعــى‬               ‫عملــه قائ ـ ً‬\n     ‫عليهمــا األول والثانــي إثــر قضيــة مضاربــة وباستشــمام املدعــى عليــه‬\n     ‫الثانــي اتضــح انبعــاث رائحــة املســكر مــن جوفــه وباســتجواب املدعــى‬\n     ‫عليــه األول أفــاد أن املدعــى عليــه األول واملتهــم ‪ ...........‬واملتهــم ‪...........‬‬\n     ‫كانــوا يف حالــة ســكر بداخــل الشــقة (فــرزت بحقهمــا أوراق مســتقلة‬\n     ‫حملاكمتهمــا مبقــر إقامتهمــا يف قضيــة شــرب املســكر كمــا فصلــت‬\n     ‫أوراق مســتقلة لقضيــة املضاربــة) وباســتجواب املدعــى عليــه الثانــي أفــاد‬\n     ‫أنــه حضــر إلــى الشــقة ووجــد فيهــا املدعــى عليــه األول واملتهــم ‪...........‬‬\n     ‫واملتهــم ‪...........‬يتناولــون املســكر وشــرب معهــم املســكر وقــد انتهــى‬\n     ‫التحقيــق إلــى توجيــه االتهــام إلى املدعى عليهما األول والثاني باالجتماع‬\n     ‫علــى مفســدة الشــرب وشــرب الثانــي للمســكر وذلــك لألدلــة والقرائــن‬\n     ‫التاليــة‪ :‬مــا جــاء بأقــوال املدعــى عليهمــا ص ‪ 10‬والثانــي ص ‪ 13‬مــن‬\n     ‫دفتــر التحقيــق لفــة (‪ )13.7‬ومــا جــاء مبحضــر االستشــمام ص ‪ 12‬مــن‬\n     ‫دفتــر التحقيــق لفــة (‪ )13‬وبالبحــث عــن ســوابقهما لــم يعثــر لهمــا علــى‬\n     ‫ســوابق مســجلة وحيــث إن مــا أقــدم عليــه املدعــى عليهمــا وهمــا بكامــل‬\n     ‫أهليتهمــا املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا اطلــب‬\n     ‫إثبــات إدانتهمــا مبــا اســند إليهمــا واحلكــم علــى املدعــى عليــه الثانــي‬\n     ‫بحــد املســكر واحلكــم عليهمــا بعقوبــة تعزيريــة لقــاء بقيــة مــا أســند‬\n     ‫إليهمــا وأســألهما اجلــواب ويف هــذه اجللســة حضــر املدعــى عليــه الثانــي‬\n     ‫‪...........‬ولــم يحضــر املدعــى عليــه األول ‪...........‬كونــه مطلــق ســراح‬\n     ‫وســيتم النظــر يف شــأنه حــن حضــوره وبســؤال املدعــى عليــه الثانــي‬\n     ‫‪ ...........‬عــن دعــوى املدعــي العــام قــال مــا ذكــره املدعــي العــام مــن أنــه‬\n\n\n‫‪83‬‬\n\f‫قبــض علينــا بتاريــخ ‪1431/12/14‬ه ـ فصحيــح وأنــا لــم أقــم باملضاربــة‬\n‫ولــم أقــم بشــرب املســكر معهــم وكنــت معهــم بالشــقة وبحمــد اهلل ال‬\n‫توجــد علــي أي ســوابق مســجلة هكــذا أجــاب وبســؤال املدعــي العــام‬\n‫عــن بينتــه قــال لــدي بينــة اطلــب إمهالــي إلحضارهــا لــذا رفعــت اجللســة ‪.‬‬\n‫ويف اجللســة املقــررة يــوم الســبت املوافــق‪ 1433/06/14‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 11: 15‬لســماع دعــوى املدعــي العام ضــد‪ ...........‬وحضر‬\n‫املدعــي العــام وحضــر املدعــى عليــه وبســؤال املدعــي العــام عــن بينتــه‬\n‫قــال لــم حتضــر وأطلــب إمهالــي إلحضارهــا لــذا رفعــت اجللســة ‪ .‬ويف‬\n‫اجللســة املقــررة يــوم الســبت املوافــق‪ 1433/07/05‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 12 : 15‬لســماع دعوى املدعي العام ضد‪...........‬وحضر املدعي‬\n‫العــام وحضــر املدعــى عليــه وبســؤال املدعــي العــام عــن بينتــه قــال لــم‬\n‫حتضــر وأطلــب إمهالــي إلحضارهــا لــذا رفعــت اجللســة ‪ .‬ويف اجللســة‬\n‫املقــررة يــوم الســبت املوافــق ‪ 1433/08/03‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪01 : 15‬لســماع دعــوى املدعــي العــام ضد‪...........‬وحضــر املدعــي العــام‬\n‫ولــم يحضــر املدعــى عليــه وبســؤال املدعــي العــام عــن بينتــه قــال لــم‬\n‫حتضــر وأطلــب إمهالــي إلحضارهــا وبعــد انتهــاء اجللســة يف متــام الســاعة‬\n‫الواحــدة ظهــر ًا حضــر املدعــى عليــه وجــرى إفهامــه بااللتــزام باحلضــور‬\n‫يف املوعــد احملــدد وذلــك يف يــوم االثنــن املوافــق ‪1433/08/12‬ه ـ‬\n‫الســاعة ‪ 10 : 15‬وأقفلت هذه اجللســة يف متام الســاعة الواحدة والنصف‬\n‫‪ .‬ويف اجللســة املقررة يوماإلثنيناملوافق‪ 1434/01/19‬هـ افتتحت اجللســة‬\n‫الســاعة ‪ 10 :00‬لســماع دعــوى املدعــي العــام ضــد‪ ...........‬و‪.........../‬‬\n‫وفيهــا حضراملدعــي العــام وجــري إحضــار املدعــى عليــه وبســؤال املدعي‬\n‫العــام عــن بينتــه التــي أســتمهل إلحضارهــا اجــاب قائــا لقــد طلبــت‬\n\n\n                                                                                     ‫‪84‬‬\n\f     ‫البينــة ولكنهــا لــم حتضــر أطلــب الرجــوع إلــي أوراق املعاملــة والنظــر‬\n     ‫مبــا فيهــا مــن أدلــة وقرائــن هكــذا أجــاب هــذا وقــد جــري اطالعــي‬\n     ‫علــى أوراق املعاملــة وعلــى طلبــات إحضــار البينــة املرفقــة باملعاملــة‬\n     ‫فوجدتهــا كمــا يلــي الطلــب األول برقــم ‪...........‬وتاريــخ ‪1433/6/2‬ه ـ‬\n     ‫للحضــور يف يــوم الســبت املوافــق ‪1433/6/14‬ه ـ والطلــب الثانــي‬\n     ‫برقم‪...........‬وتاريــخ ‪1433/10/24‬ه ـ للحضــور يف يــوم األثنــن املوافــق‬\n     ‫‪1433/11/8‬ه ـ والطلــب الثالــث برقــم ه ـ م م ‪ 49/2/‬وتاريــخ‬\n     ‫‪1433/1/6‬ه ـ للحضــور يف يــوم األثنــن املوافــق ‪1433/1/19‬ه ــوحيث‬\n     ‫جــرى إمهــال املدعــي العــام إلحضــار بينتــه مــرات ولكنهــا لــم حتضــر‬\n     ‫فقــد قــررت الســير يف نظــر القضيــة هــذا وقــد اطلعــت علــى إقــرار‬\n     ‫املدعــى عليــه الثانــي خالــد املرفــق باملعاملــة باللفــة (‪ )13‬صحيفــة رقــم‬\n     ‫(‪ )15‬واملتضمــن مــا نصــه أقــر وأعتــرف انــا‪........... /‬ســعودي اجلنســية‬\n     ‫وأنــا بكامــل قــواي العقليــة املعتبــره شــرعا بــدون إكــراه وال إجبــار مــن‬\n     ‫أحــد باننــي حضــرت إلــي الشــقة ووجــدت بهــا كال مــن ‪........... /1‬‬\n     ‫ســعودي اجلنســية ‪........... /2‬ســعودي اجلنســية ‪ ........... /3‬ســعودي‬\n     ‫اجلنســية وكانــوا جالســن بالغرفــة يتناولــون مــادة العــرق املســكر‬\n     ‫وقمــت بتنــاول املســكر معهــم يف الشــقة وقــد ذهبــت إلــي أحــد الغــرف‬\n     ‫وبعدهــا منــت وال أعلــم ماحــدث بعــد ذلــك وهــذا إقــراري وعليــه أوقــع‬\n     ‫كمــا جــري منــي الرجــوع إلــي أقــوال املدعــى عليــه املرفــق باملعاملــة لفــة‬\n     ‫رقــم (‪ )13‬صحيفــة رقــم (‪ )14/13‬واملتضمنــة ســؤال املدعــى عليــه وضــح‬\n     ‫لنــا مفصــا عــن مــا حــدث بينكــم بالشــقة التــي كنتــم جالســن بهــا ج‪/‬‬\n     ‫لقــد حضــرت إلــى الشــقة يف الســاعة الثانيــة عشــر ليــا مــن يــوم اجلمعــة‬\n     ‫‪1431/12/14‬ه ـ وعنــد وصولــي إلــى الشــقة وجــدت جالــس بالشــقة‬\n\n\n‫‪85‬‬\n\f‫كال مــن ‪.........../3.........../2........... /1‬وكانــوا جالســن بغرفــة‬\n‫وكانــوا يتناولــون املســكر وقمــت بشــرب املســكر معهــم ثــم ذهبــت‬\n‫إلــي الغرفــة ومنــت وال أعلــم مــا حــدث بعــد ذلــك س‪ /‬ماهي مادة املســكر‬\n‫التــي قمــت بتناولهــا ج‪ /‬مــادة العــرق املســكر يف قــارورة مــاء صحــه س‪/‬‬\n‫مــن الــذي احضــر املســكر ج‪ /‬ال أعلــم وجدتــه يف الشــقة كمــا جــري‬\n‫اطالعــي علــى محضــر االستشــمام املرفــق باملعاملــة لفــه رقــم (‪)13‬‬\n‫صحيفــة رقــم (‪ )12‬مــن دفتــر التحقيــق واملتضمنــه مــا نصــه وبحضورنــا‬\n‫نحــن املوقعــن ادنــاه بالتاريــخ أعــاه جــري إشــمام كال مــن ‪.........../1‬‬\n‫ســعودي ‪.........../2‬ســعودي ‪.........../3‬ســعودي وأتضــح انبعــاث رائحــه‬\n‫املســكر تفــوح مــن أفواههــم وجــري تدويــن احملضــر حفظــا للواقعــة‬\n‫وعليــه جــري التوقيــع وبالبحــث عــن صحيفــة ســوابق للمدعــى عليــه‬\n‫باملعاملــة لــم أجــد شــيئا وبســؤال املدعــى عليــه عــن إقــراره يف دفتــر‬\n‫التحقيــق وأقوالــه أجــاب قائــا لقــد ضربــت حتــى أوقــع علــى ذلــك‬\n‫وبســؤاله هــل لديــه بينــه علــى ذلــك قــال ال هكــذا أجــاب فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوي واإلجابــة وإلنــكار املدعــى عليــه للدعــوي يف مجلــس‬\n‫احلكــم وإقــراره حتقيقــا بذلــك ولعجــز املدعــي العــام عــن إحضــار بينتــه‬\n‫ومبــا أن احلــدود تــدرأ بالشــبهات لقــول النبــي صلــى اهلل عليــه وســلم‬\n‫(ادرؤوا احلــدود بالشــبهات ) وإلنــكار املدعــى عليــه ملــا نســب إليــه بعــد‬\n‫إقــراره حتقيقــا شــبهة يــدرأ بهــا احلــد وملــا جــاء يف محضــر القبــض‬\n‫ومحضــر االستشــمام وهــذه قرائــن تعضــد دعــوى املدعــي العــام فلمــا‬\n‫ســبق لــم يثبــت لــدي إدانــة املدعــى عليــه الثانــي‪ ...........‬مبــا نســب إليــه يف‬\n‫الدعــوي يف اجتماعــه علــى مفســدة وشــربه للمســكر مــع توجيه الشــبهة‬\n‫القويةلــه بذلــك ومبــا ان تعاطــي املســكر واالجتمــاع والتعــاون علــى‬\n\n\n                                                                                            ‫‪86‬‬\n\f     ‫شــربه فعــل محــرم يســتحق فاعلــه العقــاب عليــه واهلل تعالــى يقول(يــا‬\n     ‫أيهــا الذيــن ءامنــوا إمنــا اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن‬\n     ‫عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) ولقولــه صلــى اهلل عليــه‬\n     ‫وســلم ( كل مســكر خمر وكل خمر حرام)فلما ســبق فقد حكمت‬\n     ‫علــى املدعــى عليــه للشــبهة مبــا يلــي أوال‪ /‬يســجن املدعــى عليــه الثانــي‬\n     ‫‪...........‬ملــدة اســبوع يحتســب منهــا مــا امضــاه موقوفــا يف هــذه القضيــة‬\n     ‫ويجلــد ثالثــون جلــدة دفعــه واحــده وذلــك لقــاء االشــتباه لــه الجتماعــه‬\n     ‫علــى مفســدة ‪ .‬ثانيــا‪ /‬يجلــد املدعــى عليــه الثانــي ‪...........‬ســبعون جلــدة‬\n     ‫دفعــه واحــدة ويؤخــذ عليــه التعهــد الشــديد بلــزوم طريــق االســتقامة‬\n     ‫والبعــد عــن احملرمــات وأال يعــود ملثــل مــا بــدر منــه وذلــك لقــاء االشــتباه‬\n     ‫بــه لشــربه املســكر ويكــون بــن هــذا اجللــد وســابقه مــدة ال تقــل عــن‬\n     ‫خمســة عشــر يومــا علمــا بــأن املدعــى عليــه األول‪ ...........‬ســيتم النظــر يف‬\n     ‫شــأنه حــال حضــوره وبعــرض احلكــم علــى الطــريف نقــرر املدعــي العــام‬\n     ‫معارضتــه علــى احلكــم مــع تقــدمي الئحــة اعتراضيــة عليــه فأفهمتــه‬\n     ‫باحلضــور يف يــوم األربعــاء املوافــق ‪1434/1/21‬ه ـ الســتالم نســخه مــن‬\n     ‫قــرار احلكــم لتقــدمي اعتراضــه عليــه خــال مــدة ثالثــن يــوم اعتبــارا مــن‬\n     ‫التاريــخ املشــار إليــه فــإن مضــت املــدة ولــم يســتلم نســخه مــن احلكــم‬\n     ‫أولــم يقــدم اعتراضــه عليــه خاللهــا فــإن حقــه يف تقــدمي الئحــة االعتراض‬\n     ‫يكــون ســاقطا كمــا قــرر املدعــى عليــه قناعتــه بــه وجــري النطــق‬\n     ‫باحلكــم يف األثنــن املوافــق ‪1434/1/19/‬ه ـ الســاعة ‪ 10 : 30‬وبــه‬\n     ‫أقفلــت اجللســة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد والــه‬\n     ‫وصحبــه اجمعــن حــرر يف ‪1434/01/19‬ه ــاحلمد هلل وحــده والصــاة‬\n     ‫والســام علــى مــن ال نبــي بعــده وبعــد فلــدي أن ‪...........‬القاضــي‬\n\n\n‫‪87‬‬\n\f‫باحملكمــة اجلزائيــة بجــدة ففــي يــوم االثنــن املوافــق ‪1434/01/26‬ه ـ‬\n‫وبعــد ورود الالئحــة االعتراضيــة مــن املدعــي العــام املتعلقــة بدعــواه ضــد‬\n‫‪...........‬و‪ ...........‬املكونــة مــن ثــاث صفحــات وبعــد االطــاع عليهــا لــم‬\n‫أجــد فيهــا مــا يؤثــر علــى مــا حكمــت بــه وقــررت رفــع املعاملــة مــع القرار‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة حملكمــة االســتئناف مبكــة‬\n‫املكرمــة لتدقيــق احلكــم كاملتبــع وعليــه حصــل التوقيــع وبــاهلل‬\n‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آله وصحبــه أجمعني‬\n‫حــرر يف ‪1434/01/26‬ه ــاحلمد هلل وحــده والصــاة والســام علــى مــن‬\n‫ال نبــي بعــده وبعــد ‪ :‬فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة‬\n‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة‬\n‫الــواردة إلينــا شــفع خطــاب فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة‬\n‫جــدة رقــم ‪ 34/555032‬وتاريــخ ‪1434/5/20‬ه ــاملشتملةعلى القــرار‬\n‫الصــادر مــن فضيلــة الشــيخ‪........... /‬القاضــي باحملكمــة اجلزائيــة بجــدة‬\n‫املــؤرخ يف ‪1434/1/19‬ه ــواملسجل بعــدد ‪ ،3416887‬املتضمــن دعــوى‬\n‫املدعــي العــام ضــد‪........... /‬ورفيقــه املتهمــن باالجتمــاع علــى مفســدة‬\n‫الشــرب وشــرب الثانــي للمســكر احملكــوم فيــه مبــا ّدون بباطــن القــرار‬\n‫وبدراســة القــرار وصــورة ضبــط والالئحــة االعتراضيــة تقــررت املوافقــة‬\n‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                   ‫وصحبه وسلم ‪.‬‬\n\n\n\n\n                                                                                         ‫‪88‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":81,"source_page_end":88,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4b4524fc1107650e9e88c2681c0e6886728afd296662af12c5763b3aa1bbf600","normalized_text_hash":"ee924c0b1f3aee1d254951bb79e19c16dc097b4ad31886bbfd8b548b94f076eb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p81-3416887"},{"id":"51f3784e-93ef-5edb-9940-f07ce8bd5719","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -مطاردة بسيارة وتسبب يف إصابة -عدم قبول شهادة من عرف بعصبية وإفراط يف حمية -تقرير طبي -سجن -جلد -","document_number":"33263784","case_number":"33261681","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بشروره بشأن استخالفهم يف سماع شهادة من حضر الواقعة فوردنا كتاب رئيس المحكمة العامة بشروره ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/23","year":"1434","subject":"اعتداء -مطاردة بسيارة وتسبب يف إصابة -عدم قبول شهادة من عرف بعصبية وإفراط يف حمية -تقرير طبي -سجن -جلد -","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 33263784 :‬تاريخه‪1433/11/23:‬هـ‬\n                         ‫رقم الدعوى‪33261681:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3421337‬تاريخه‪1434/1/25 :‬هـ‬\n\n\n\n     ‫اعتــداء ‪ -‬مطــاردة بســيارة وتســبب يف إصابــة ‪ -‬عــدم قبــول شــهادة مــن‬\n     ‫عــرف بعصبيــة وإفــراط يف حميــة ‪ -‬تقريــر طبــي ‪ -‬ســجن ‪ -‬جلــد ‪-‬‬\n                                                                         ‫تهمــة‪.‬‬\n\n\n\n     ‫‪-‬نــص أهــل العلــم أن ال تقبــل شــهادة مــن عــرف بعصبيــة وإفــراط يف‬\n     ‫حميــة كتعصــب قبيلــة علــى قبيلــة وإن ملتبلــغ رتبــة العــداوة (الــروض‬\n                                                                   ‫املربــع ‪.)605/7‬‬\n\n\n\n\n     ‫اتهــام املدعــي العــام للمدعــى عليــه بقيامــه باالعتــداء بســيارته علــى‬\n     ‫مواطنني يســيران على أقدامهما مبطاردتهما بقصد إصابتهما وتســببه‬\n     ‫يف إصابــة أحدهمــا عمــد ًا والهــروب مــن املوقــع يطلــب إثبــات إدانتــه مبــا‬\n     ‫أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة والنظــر يف عقوبــات بديلة عن‬\n     ‫الســجن اســتناد ًا للفقــرة اخلامســة م قــرار مجلــس الــوزراء رقــم (‪)169‬‬\n     ‫وتاريــخ ‪ ،1429/6/19‬أقــر املدعــى عليــه بالصــدم خطــأ وإنــكاره‬\n     ‫العمدية‪،‬احضــر املدعــي العــام شــهود ًا تضمنــت شــهادتهم صحــة‬\n     ‫الدعــوى ‪،‬أجــاب املدعــى عليــه عــن الشــهادة بأنهــا ليســت صحيحــة وهــم‬\n     ‫أبنــاء قبيلــة واحــدة ‪،‬حضــر املدعــي يف احلــق اخلــاص وكالــة عــن املجنــي‬\n\n‫‪89‬‬\n\f‫عليــه الثانــي وقــرر إن املدعــى عليــه قــام بصــدم موكلــه عمــدا ويطلــب‬\n‫مجازاتــه ‪،‬أنكــر املدعــى عليــه العمديــة وطلــب مــن املدعــي البينــة‬\n‫وذكــر أن هــا بينــة لــه و ال يرغــب ميــن املدعــى عليــه ‪،‬توجــه الشــبهة‬\n‫واحلكــم مبــا يلــي ‪،‬إيقافــه ملــدة شــهرين‪ ،‬بجلــده ثمانــن جلــدة مفرقــة‬\n‫علــى دفعتــن كل دفعــة أربعــون جلــدة وهــذا احلكــم للحــق العــام‪ ،‬قــرر‬\n‫املدعــي العــام االعتــراض وطلــب االســتئناف بــدون الئحــة وقــرر املدعــى‬\n‫يف احلــق اخلــاص االعتــراض وطلــب االســتئناف بالئحــة وقــرر املدعــى‬\n              ‫عليــه القناعــة ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة‬\n‫اجلزئيــة بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزئيــة بنجــران برقــم ‪ 33261681‬وتاريــخ ‪1433/04/14‬‬\n‫ه ـ املقيــدة باحملكمــة برقــم ‪ 33704997‬وتاريــخ ‪ 1433/04/14‬ه ـ‬\n‫ففــي يــوم الســبت املوافــق‪ 1433/04/17‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪ 10 : 24‬وفيهــا حضــر املدعــي العام‪.......‬مبوجــب التكليــف الصــادر‬\n‫مــن هيئــة التحقيــق واالدعــاء العــام بنجــران رقــم ه ـ ن ‪11178/2/1‬‬\n‫بتاريــخ ‪1430/12/29‬ه ـ وادعــى علــى احلــدث ‪...... /‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ ).....‬قائــا يف دعــواه عليــه أنــه بتاريــخ‬\n‫‪1433/3/21‬هـ ورد يف احملضر املعد من قبل مدير شــعبة مرور شــرورة‬\n‫ورود بــاغ للعمليــات عــن وجــود حــادث دهــس وهــروب مــن قبــل ســيارة‬\n‫نــوع ‪ ........‬اللــون ‪ .....‬وباالنتقــال للمستشــفى اتضــح وجــود املصــاب ‪/‬‬\n‫‪.......‬بكســر مضاعــف يف رجلــه منــوم باملستشــفى والــذي أفــاد أن املتهــم‬\n\n                                                                                  ‫‪90‬‬\n\f     ‫هــو مــن قــام بصدمــه بالســيارة املشــار إليهــا ‪ .‬ويضبــط إفــادة املصــاب ‪/‬‬\n     ‫‪........‬ذكــر أن املتهــم قــام بصدمــه عمــد ًا بعــد أن حــاول الهــرب حيــث‬\n     ‫كان يســير علــى قدميــه برفقــة زميلــه ‪...... /‬أمــام مدرســة ‪ ............‬بحــي‬\n     ‫‪ ............‬وكان املتهــم يقــود ســيارة نــوع ‪ ..........‬ويحــاول صــدم ‪......‬الــذي‬\n     ‫هــرب ثــم انحرفــت ســيارة املتهــم مــرة أخــرى واجتــه لهمــا ليصدمهمــا‬\n     ‫فتمكــن ‪....‬مــن الهــرب وعنــد محاولــة ‪......‬الهــرب أصابــه املتهــم وصدمــه‬\n     ‫مبقدمــة الســيارة ‪ ......‬وتســبب يف إصابــة رجلــه اليســرى ثــم هــرب املتهــم‬\n     ‫علــى الســيارة املشــار إليهــا ‪ .‬وبضبــط أقوال‪...... /‬أفــاد أنه أثناء خروجهم‬\n     ‫مــن مدرســة ‪ ............‬كان يســير علــى قدميــه برفقــة ‪.... /‬فقــام املتهــم‬\n     ‫بقيــادة الســيارة املشــار إليهــا مبطاردتــه محــاو ًال صدمــه فهــرب منــه ثــم‬\n     ‫عــاد املتهــم مــرة أخــرى وصــدم ‪.......‬ممــا أدى إلــى إصابتــه واحتجــازه بــن‬\n     ‫ســيارة ‪ .....‬وســيارة ‪ ....‬أخــرى وذكــر إن املتهــم يــدرس معهــم يف نفــس‬\n     ‫املدرســة وإن بينهمــا مشــكلة ســابقة قبــل ســنة وانتهــت بالصلــح مــن‬\n     ‫قبــل شــرطة شــرورة واملشــايخ ‪ .‬وباســتجواب احلــدث ‪..... /‬أقــر بقيادتــه‬\n     ‫الســيارة املشــار إليهــا والعائــدة ملكيتهــا جلــده املواطــن ‪....... /‬أثنــاء‬\n     ‫خروجــه مــن مدرســة ‪ ..............‬وتلفــظ عليــه مجموعــة مــن الطــاب وهــم‬\n     ‫كل مــن ‪....../‬و‪......‬و‪ ......‬وحذفــوه باألحذيــة والكتــب ( مت مخاطبــة‬\n     ‫الشــرطة إلكمــال اإلجــراءات األوليــة حيــال دعــواه باخلطــاب رقــم ( ه ـ‬\n     ‫ن ‪ ) 639/3/2‬وتاريــخ ‪1433/3/22‬ه ـ وســيتم إحالتهــم إذا ثبــت االتهــام‬\n     ‫حملكمــة شــرورة العامــة بالقضيــة املفــرزة ) فهــرب منهــم وصــدم ســيارة‬\n     ‫نــوع ‪ ......‬ممــا أدى إلصابــة ‪.....‬فشــاهده وعــرف أنــه مصــاب وهــرب خوفـ ًا‬\n     ‫علــى نفســه ‪ .‬وبســماع شــهادة املواطنــن ‪...... /‬و‪ .......‬أفــادا أنهمــا شــاهدا‬\n     ‫صاحــب ســيارة نــوع ‪ ... .....‬كان يطــارد ‪ .......‬بســرعة عاليــة ليصدمــه‬\n\n\n‫‪91‬‬\n\f‫لكــن ‪...‬هــرب فعــاد صاحــب الســيارة ‪ ....‬مــرة أخــرى بعــد أن أخــذ‬\n‫الــدوران والتوجــه إلــى ‪....‬مــرة أخــرى يريــد صدمــه فتمكــن مــن الهــرب‬\n‫ثــم شــاهد ‪.....‬يحــاول الهــرب فاجتــه إليــه وصدمــه فانحشــرت رجلــه‬\n‫اليســرى بــن مقدمــة الســيارة ‪ ......‬ومؤخــرة ســيارة نــوع ‪ ....‬كانــت واقفــة‬\n‫جانــب الطريــق ثــم هــرب مــن املوقــع ‪ .‬وقــد اثبــت التقريــر الطبــي الصــادر‬\n‫من مستشــفى شــرورة العام برقم ( بدون ) وتاريخ ‪1433/4/5‬هـ إصابة‬\n‫‪....... /‬بكســر يف الركبــة اليســرى وســحجات واســعة االمتــداد علــى‬\n‫الفخــذ األيســر مــع جــروح قطعيــة متعــددة ( ‪ 4‬جــروح ) ومــدة الشــفاء‬\n‫مــن ( ‪ ) 6-3‬أشــهر مــا لــم حتــدث مضاعفــات ‪ .‬وانتهــى التحقيــق لتوجيــه‬\n‫االتهــام للحــدث ‪........ /‬باالعتــداء بســيارته علــى مواطنــن يســيران علــى‬\n‫أقدامهمــا مبطاردتهمــا بقصــد إصابتهمــا وتســببه يف إصابــة أحدهمــا‬\n                                                   ‫عمــد ًا والهــروب مــن املوقــع ‪.‬‬\n                                                 ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n‫‪ -1‬إقــراره املنــوه عنــه واملــدون علــى ص ( ‪ ) 4‬مــن ملــف التحقيــق املرفــق‬\n           ‫رقــم ( ‪ ) 6‬وص ( ‪ ) 4 ، 3‬مــن ملــف التحقيــق املرفــق لفــة ( ‪.) 2‬‬\n‫‪ -2‬شــهادة الشــهود املنــوه عنهــا املدونــة علــى الصفحــات ( ‪ ) 12 ، 11‬مــن‬\n                                               ‫دفتــر التحقيــق املرفــق رقــم ( ‪.) 2‬‬\n‫‪ -3‬مــا جــاء يف إفــادة املصــاب املنــوه عنهــا واملرفقــة لفــة ( ‪ ) 9‬واملدونــة‬\n‫علــى ص ( ‪ ) 7 ، 2‬مــن ملــف التحقيــق املرفــق رقــم ( ‪ ) 1‬وص ( ‪ ) 10‬مــن‬\n                                            ‫ملــف التحقيــق املرفــق رقــم ( ‪. ) 2‬‬\n‫‪ -4‬مــا جــاء يف أقــوال ‪ ............‬املنــوه عنهــا واملدونــة ص ( ‪ ) 9‬مــن ملــف‬\n                                                   ‫التحقيــق املرفــق رقــم ( ‪. ) 2‬‬\n                             ‫‪ -5‬التقرير الطبي املنوه عنه واملرفق لفة ( ‪. ) 6‬‬\n\n\n                                                                                        ‫‪92‬‬\n\f     ‫وحيــث أن مــا أقــدم عليــه املتهــم وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n     ‫فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات إدانتــه مبــا أســند إليــه‬\n     ‫واحلكــم عليــه بعقوبــة تعزيريــة والنظــر يف عقوبــات بديلــة عــن الســجن‬\n     ‫اســتناد ًا للفقــرة اخلامســة مــن قــرار مجلــس الــوزراء رقــم ( ‪ ) 169‬وتاريــخ‬\n                                                                     ‫‪1429/6/19‬هــ‪..‬‬\n     ‫( علم ـ ًا بــأن احلــق اخلــاص مــا زال قائم ـ ًا ) هــذه دعــواي وبعــرض دعــوى‬\n     ‫املدعــي العــام علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي العــام‬\n     ‫يف دعــواه مــن اعتدائــي بالســيارة علــى مواطنــن يســيران علــى أقدامهمــا‬\n     ‫بقصــد إصابتهمــا وتســببي يف إصابــة أحدهمــا عمــدا و الهــروب مــن‬\n     ‫املوقــع هــذا غيــر صحيــح والصحيــح أننــي كنــت خــارج مــن املدرســة‬\n     ‫وركبــت ســيارتي مــن نــوع ‪ ..........‬إنتــاج ‪2006‬م و كان قــد تلفــظ علـ ّـي‬\n     ‫بعــض الطــاب بألفــاظ نابيــة وكانــوا يريدون ضربي فركبت ســيارتي‬\n     ‫وصدمــت أحدهــم مــن دون شــعور ولــم أكــن أتعمــد ذلــك ثــم هربــت مــن‬\n     ‫املوقــع خوفــا علــى نفســي هــذه إجابتــي وبســؤال املدعــي العــام عــن ذلــك‬\n     ‫قــال غيــر صحيــح والصحيــح مــا ذكــرت وبســؤاله عــن مــا لديــه مــن بينــة‬\n     ‫قــال بينتــي مــا جــاء يف أوراق املعاملــة ثــم رفعــت اجللســة لالطــاع عليهــا‬\n     ‫وتأمــل مــا جــاء فيهــا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                            ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/04/17‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء املوافــق ‪1433/11/16‬ه ـ فتحت‬\n     ‫اجللســة يف متــام الســاعة احلاديــة عشــر صباحــا وفيهــا حضــر املدعــي‬\n     ‫العــام كمــا حضــر املدعــى عليــه وقــد متــت الكتابــة إلــى احملكمــة‬\n     ‫العامــة بشــروره بشــأن اســتخالفهم يف ســماع شــهادة مــن حضــر الواقعــة‬\n     ‫فوردنــا كتــاب رئيــس احملكمــة العامــة بشــروره برقــم ‪1684/3/916‬‬\n\n\n‫‪93‬‬\n\f‫وتاريــخ ‪1433/10/22‬ه ـ واملتضمــن صــورة مــن الشــهادة واملعدلــة شــرعا‬\n‫واملتضمــن مــا يلــي (وفيهــا حضــر كال مــن ‪......‬ســعودي بالســجل املدنــي‬\n‫رقــم (‪ )........‬و‪ .............‬ســعودي بالســجل املدنــي رقــم (‪ )......‬وبســؤال‬\n‫كل واحــد منهمــا عمــا لديــه مــن شــهادة أجــاب قائــا إننــي شــاهدت‬\n‫املدعــو ‪.......... /‬يســتقل ســيارة نــوع ‪ ..........‬موديــل ‪2006‬م عنــد مدرســة‬\n‫‪ ............‬واجتــه نحــو املدعــو ‪....... /‬يريــد صدمــه بالســيارة فقــام ‪....‬‬\n‫بالهــروب مــن أمــام الســيارة وطلــع علــى الرصيــف فقــام املدعــو ‪......./‬‬\n‫بالــدوران مــرة أخــرى واجتــه نحــو ‪.......‬لكنــه لــم يســتطع اللحــاق بــه‬\n‫فقــام باالجتــاه نحــو املدعــو ‪.......... /‬والــذي كان قائمــا عنــد ركــن‬\n‫املدرســة ومســتندا إلــى ســيارة ‪ ......‬فصدمــه بالســيارة يف رجلــه اليســرى‬\n‫واصطــدم يف الســيارة ‪ .......‬ثــم قــام بعدهــا بالهــروب هــذا مــا لــدي مــن‬\n‫شــهادة وقــد جــرى تعديلهمــا مــن قبــل كال مــن‪.......‬و‪ )...........‬وبعرضهــا‬\n‫علــى املدعــى عليــه احلاضــر يف مجلــس احلكــم أجــاب بقولــه غيــر‬\n‫صحيــح جملــة وتفصيــا وأنــا أطعــن يف الشــهود لكونهــم مــن قبيلــة‬\n‫واحــدة هكــذا أجــاب وقــد حضــر يف هــذه اجللســة ‪.......‬ســعودي بالســجل‬\n‫املدنــي رقــم (‪ )..........‬بصفتــه وكيــا عــن ابنــه‪ ........‬ســعودي بالســجل‬\n‫املدنــي رقــم ‪...........‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل شــروره‬\n‫برقــم ‪ 11‬وتاريــخ ‪1433/7/14‬ه ـ وبســؤاله عــن دعــواه قــال إن املدعــى‬\n‫عليــه يــدرس مــع موكلــي يف مدرســة واحــدة وقــد خرجــا ذات يــوم مــن‬\n‫املدرســة وقــام املدعــى عليــه بالترصــد ملوكلــي بســيارته التــي كان‬\n‫يقودهــا وهــي ‪ ......‬املوصوفــة يف التقريــر الطبــي املرفــق باملعاملــة وأنــا‬\n‫أطلــب مجازاتــه شــرعا لقــاء ذلــك وبعــرض ذلــك علــى املدعــى عليــه قــال‬\n‫مــا ذكــره املدعــي باحلــق اخلــاص يف دعــواه مــن صدمــي لــه عمــدا فهــذا‬\n\n\n                                                                                    ‫‪94‬‬\n\f     ‫غيــر صحيــح فقــد كان مــوكل املدعــي ومــن معــه مــن أبنــاء قبيلتهــم‬\n     ‫يقــوم بحــذف احلجــارة واألحذيــة علــي وقــد هربــت منهــم اتقــاء ألذيتهــم‬\n     ‫فصدمــت موكلــه مــن دون عمــد وحصــل لــه مــا حصــل هــذه إجابتــي ‪.‬‬\n     ‫وبعــرض ذلــك علــى املدعــي وكالــة قــال غيــر صحيــح والصحيــح مــا‬\n     ‫ذكــرت وبســؤاله هــل لديــك بينــة علــى مــا جــاء يف دعــواك قــال ال بينــة‬\n     ‫لــدي فأفهمتــه بأنــه ليــس لــك إال ميينــه فأجــاب بقولــه بانــي ال أريــد ميينــه‬\n     ‫هكــذا أجــاب ثــم جــرى منــا اإلطــاع علــى أقــوال املدعــى عليــه يف‬\n     ‫دفتــر التحقيــق رقــم (‪ )2‬واملــدون علــى الصفحــات (‪ )12.11‬فوجدناهــا‬\n     ‫مطابقــة ملــا جــاء يف إجابتــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n     ‫وحيــث أنكــر املدعــى عليــه صدمــه للمجنــي عليــه ‪............‬متعمــدا‬\n     ‫وبنــاء علــى مــا شــهدت البينــة املعدلــة شــرعا وملــا كان الشــهود هــم مــن‬\n     ‫قبيلــة واحــدة وتطــرق التهمــة لهــم بالتعصــب لبعضهــم البعــض واحتمــال‬\n     ‫وجــود احلميــة بينهــم أضعــف مــن رتبــة تلــك الشــهادة وإثبــات مــا جــاء يف‬\n     ‫الدعــوى مــن خاللهــا وقــد نــص أهــل العلــم أنــه ال تقبــل شــهادة مــن عــرف‬\n     ‫بعصبيــة وإفــراط يف حميــة كتعصــب قبيلــة علــى قبيلــة وإن لــم تبلــغ‬\n     ‫رتبــة العــداوة (الــروض املربــع ‪ )605/7‬وحيــث عجــز املدعــي وكالــة‬\n     ‫باحلــق اخلــاص عــن إثبــات دعــواه شــرعا ورفــض ميــن املدعــى عليــه علــى‬\n     ‫نفــي حصــول العمديــة منــه يف صــدم موكلــه وبنــاء علــى عــدم وجــود‬\n                        ‫ســوابق جنائيــة علــى املدعــى عليــه فقــد قــررت مــا يلــي ‪:‬‬\n     ‫‪ -1‬لــم يثبــت لــدي إدانــة املدعــى عليــه بصدمــه للمجنــي عليــه ‪ ....‬عمــدا‬\n     ‫وقــررت توجيــه التهمــة للمدعــى عليــه بصدمــه للمجنــي عليــه ‪........‬‬\n     ‫بســيارته خطــأ وحكمــت بإيقافــه ملــدة شــهرين وجلــده ثمانــن جلــدة‬\n     ‫مفرقــة علــى دفعتــن كل دفعــة أربعــون جلــدة وهــذا احلكــم للحــق العام‪.‬‬\n\n\n‫‪95‬‬\n\f‫‪ -2‬صــرف النظــر عــن دعــوى املدعــي وكالــة باحلــق اخلــاص وإخــاء‬\n‫ســبيل املدعــى عليــه منهــا وبعــرض احلكــم علــى املدعــي وكالــة‬\n‫باحلــق اخلــاص قــرر اعتراضــه علــى احلكــم بالئحــة فأفهمتــه بتعليمــات‬\n‫االعتــراض واســتالم نســخة مــن إعــام احلكــم لتقــدمي اعتراضــه عليــه‬\n‫خــال مــدة أقصاهــا ثالثــون يومــا وإذا لــم يقــدم اعتراضــه خــال تلــك‬\n‫املــدة يســقط حقــه يف االســتئناف ويكتســب احلكــم القطعيــة كمــا‬\n‫قــرر املدعــى عليــه قناعتــه باحلكــم فيمــا قــرر املدعــي العــام اعتراضــه‬\n‫علــى احلكــم بــدون الئحــة فأمــرت بتنظيــم قــرار يرفــق بــاألوراق ويرســل‬\n‫حملكمــة االســتئناف بعســير للتدقيــق ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/16‬هـ‬\n‫احلمــد اهلل وحــده وبعــد ففــي يــوم األحــد ‪1433/12/26‬ه ـ فتحت اجللســة‬\n‫وقــد جــرى منــا االطــاع علــى الالئحــة االعتراضيــة املقدمــة مــن املدعــي‬\n‫باحلــق اخلــاص واملقيــدة بهــذه احملكمــة برقــم ‪ 332220446‬وبتاريــخ‬\n‫‪1433/12/22‬ه ـ فلــم أجــد مــا يؤثــر علــى مــا حكمــت بــه وبنــاء علــى‬\n‫املــادة (‪ )197‬مــن نظــام اإلجــراءات اجلزائيــة أمــرت برفــع كامــل أوراق‬\n‫املعاملــة إلــى محكمــة االســتئناف بعســير للتدقيــق ‪ .‬وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                              ‫‪ 1433/12/26‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائية بنجــران برقم ‪33704997‬‬\n‫وتاريــخ ‪1434/1/11‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمة الشيخ ‪............ /‬برقم ‪ 33463784‬وتاريخ ‪1433/11/23‬هـ‬\n\n\n                                                                                     ‫‪96‬‬\n\f     ‫اخلــاص بدعــوى املدعــي العــام ضــد احلــدث ‪ ( .......... /‬ســعودي اجلنســية)‬\n     ‫يف قضيــة (إصابــة) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم‬\n     ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه‬\n     ‫والالئحــة االعتراضيــة وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم‪.‬‬\n             ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪97‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":89,"source_page_end":97,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d2d7476946488bacea8f73cddf0498e8420b977255acf3d8ae5735f3ad8fc4e6","normalized_text_hash":"6151eb8d4a9ae4b20b26c3d2c6b0182af269c69b189b9a08dcd1d534e3183641","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p89-33263784"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
